UPDATE `quest_template` SET `RequestItemsText`='$N, the kidnapped Druids of the Talon will be forever trapped in the Emerald Dream if we cannot retrieve the Relics of Wakening from the Ban''ethil Barrow Den to the west.$B$BFor every minute we delay their fate comes one step closer to eternal doom.' WHERE `Id`=483 AND (`RequestItemsText` IS NULL OR `RequestItemsText`='');
UPDATE `quest_template` SET `OfferRewardText`='You have succeeded, young $C! Well done. And just in time I might add.' WHERE `Id`=483 AND (`OfferRewardText` IS NULL OR `OfferRewardText`='');
UPDATE `quest_template` SET `RequestItemsText`='Our brethren cannot be awakened until Ursal the Mauler has been slain, $N.' WHERE `Id`=486 AND (`RequestItemsText` IS NULL OR `RequestItemsText`='');
UPDATE `quest_template` SET `OfferRewardText`='$N you have proven yourself a most worthy and able $C. A $R who follows the path of honor as sure as you do is certain to find great glory in this world.$B$BMay the forest spirits protect you wherever your travels may take you.' WHERE `Id`=486 AND (`OfferRewardText` IS NULL OR `OfferRewardText`='');
UPDATE `quest_template` SET `RequestItemsText`='The road is still not safe, $C. Travel forth and slay 6 Gnarlpine Ambushers and return to me.' WHERE `Id`=487 AND (`RequestItemsText` IS NULL OR `RequestItemsText`='');
UPDATE `quest_template` SET `OfferRewardText`='You have served the good people of Dolanaar and Darnassus well, brave $C. As a member of the Sentinel force of Teldrassil I salute your efforts.' WHERE `Id`=487 AND (`OfferRewardText` IS NULL OR `OfferRewardText`='');
UPDATE `quest_template` SET `RequestItemsText`='Have you been a busy little bee, $N? I''ve been waiting for you to bring me what I need.' WHERE `Id`=488 AND (`RequestItemsText` IS NULL OR `RequestItemsText`='');
UPDATE `quest_template` SET `OfferRewardText`='Ha ha! Well, done indeed.$B$BWho would have ever guessed that I, Zenn Foulhoof, would have a $R to do my bidding? Certainly not me! But so it goes... this beloved world of ours is full of surprises.$B$BThree cheers for the naive and gullible!' WHERE `Id`=488 AND (`OfferRewardText` IS NULL OR `OfferRewardText`='');
UPDATE `quest_template` SET `RequestItemsText`='What do you have for me, $N? A lovely snack I presume?' WHERE `Id`=489 AND (`RequestItemsText` IS NULL OR `RequestItemsText`='');
UPDATE `quest_template` SET `OfferRewardText`='Ah, what a sweet $R! I knew you would come in handy!' WHERE `Id`=489 AND (`OfferRewardText` IS NULL OR `OfferRewardText`='');
UPDATE `quest_template` SET `RequestItemsText`='Do you have the seeds? I am eager to plant them.' WHERE `Id`=918 AND (`RequestItemsText` IS NULL OR `RequestItemsText`='');
UPDATE `quest_template` SET `OfferRewardText`='You got them. This is good!$B$BI will plant these seeds in special soil I have prepared. I believe the seeds will sprout into timberlings who are much more docile. Perhaps later you can see the results!' WHERE `Id`=918 AND (`OfferRewardText` IS NULL OR `OfferRewardText`='');
UPDATE `quest_template` SET `RequestItemsText`='Hello, $N. Have you found any sprouts near the waters?' WHERE `Id`=919 AND (`RequestItemsText` IS NULL OR `RequestItemsText`='');
UPDATE `quest_template` SET `OfferRewardText`='That''s a lot! I''m afraid they''re spreading at a dangerous rate. I hope I can solve the riddle of what is tainting them.$B$BThank you for your help, $N. The land is a cleaner place from your efforts.' WHERE `Id`=919 AND (`OfferRewardText` IS NULL OR `OfferRewardText`='');
UPDATE `quest_template` SET `RequestItemsText`='Hello...$B$BAnd how may I help you?' WHERE `Id`=922 AND (`RequestItemsText` IS NULL OR `RequestItemsText`='');
UPDATE `quest_template` SET `OfferRewardText`='Ah, a timberling seed? I wanted to try growing one of these to help Denalan with his studies.$B$BBut I''m afraid I''ve discovered that a corruption has grown in many of the timberlings, and seeds from such creatures carry their parent''s taint. They are beyond my talents to repair.$B$BDenalan is very skilled with things that grow. He may find a cure for future timberlings. He may be their only hope.' WHERE `Id`=922 AND (`OfferRewardText` IS NULL OR `OfferRewardText`='');
UPDATE `quest_template` SET `RequestItemsText`='Have you been to Wellspring Lake, $N? Have you been hunting the timberlings there?' WHERE `Id`=923 AND (`RequestItemsText` IS NULL OR `RequestItemsText`='');
UPDATE `quest_template` SET `OfferRewardText`='Well done! These tumors are the symptom of the timberling''s disease. They are filled with a poison that we must cleanse from our new land.$B$BI will dispose of these tumors. Thank you, $N.' WHERE `Id`=923 AND (`OfferRewardText` IS NULL OR `OfferRewardText`='');
UPDATE `quest_template` SET `RequestItemsText`='$N! You have something for me?' WHERE `Id`=927 AND (`RequestItemsText` IS NULL OR `RequestItemsText`='');
UPDATE `quest_template` SET `OfferRewardText`='...What is this? A timberling heart?? It''s covered with a foul moss!$B$BThank you for bringing this to me, $N. I will examine the heart and, if fortune shines, determine the nature of the moss about it.' WHERE `Id`=927 AND (`OfferRewardText` IS NULL OR `OfferRewardText`='');
UPDATE `quest_template` SET `RequestItemsText`='Hello again, $N. Have you completed your task?' WHERE `Id`=929 AND (`RequestItemsText` IS NULL OR `RequestItemsText`='');
UPDATE `quest_template` SET `OfferRewardText`='After the Battle of Mount Hyjal, we were without direction. Nordrassil smoked from the fire it unleashed, and our immortality--the very essence of our beings!--was lost.$B$BIt was in this trying time that the Betrayer was freed from his prison, and Shan''do Stormrage disappeared. A dark time for all.' WHERE `Id`=929 AND (`OfferRewardText` IS NULL OR `OfferRewardText`='');
UPDATE `quest_template` SET `RequestItemsText`='$N, you look like you have something to tell me. Do you have news concerning the timberlings?' WHERE `Id`=930 AND (`RequestItemsText` IS NULL OR `RequestItemsText`='');
UPDATE `quest_template` SET `OfferRewardText`='You found this on Teldrassil? Intriguing... this fruit is exotic. Perhaps its seeds were brought here from far off. Perhaps even as far as Azeroth! And there''s something about this fruit... it seems to have reacted very strangely with the soil of Teldrassil.$B$BThank you, $N. Now if you''ll excuse me, I must study this further...' WHERE `Id`=930 AND (`OfferRewardText` IS NULL OR `OfferRewardText`='');
UPDATE `quest_template` SET `RequestItemsText`='You have something for me?' WHERE `Id`=931 AND (`RequestItemsText` IS NULL OR `RequestItemsText`='');
UPDATE `quest_template` SET `OfferRewardText`='Where did you get this? I haven''t seen a plant like this since a sojourn I made to the Swamp of Sorrows... decades ago! It''s amazing that a specimen made its way to Teldrassil. And it''s grown to such a size!$B$BThank you, $N. Forgive my shortness of words, but there is a test I would like to perform on this frond...' WHERE `Id`=931 AND (`OfferRewardText` IS NULL OR `OfferRewardText`='');
UPDATE `quest_template` SET `RequestItemsText`='Did you kill Lord Melenas yet? It is vital that he be taken care of quickly and quietly, $N. His continued existence is an embarrassment to us all.' WHERE `Id`=932 AND (`RequestItemsText` IS NULL OR `RequestItemsText`='');
UPDATE `quest_template` SET `OfferRewardText`='With Lord Melenas laid to rest I can finally move on to other matters. Thank you, $N.' WHERE `Id`=932 AND (`OfferRewardText` IS NULL OR `OfferRewardText`='');
UPDATE `quest_template` SET `RequestItemsText`='At first the reports of crazed furbolg attacks were dismissed. Who could have thought that the peace-loving bear-men would turn to mindless rage? Yet another of the problems that plagues us here in our new home.' WHERE `Id`=933 AND (`RequestItemsText` IS NULL OR `RequestItemsText`='');
UPDATE `quest_template` SET `OfferRewardText`='Shan''do Stormrage never returned, and the druids were in disarray, and to this day we still do not know what became of him. With Malfurion missing, Arch Druid Fandral Staghelm took over the leadership of the druids, convincing the Circle of Ancients in Darkshore that it was time for our people to rebuild, and that it was time for our people to regain their immortality.$B$BWith the approval of the Circle, Staghelm and the most powerful druids grew Teldrassil, the new World Tree.' WHERE `Id`=933 AND (`OfferRewardText` IS NULL OR `OfferRewardText`='');
UPDATE `quest_template` SET `RequestItemsText`='I know that I did not summon you, so I cannot help but wonder why it is you have come to speak with me.$B$BWhatever it is, please make it quick.' WHERE `Id`=935 AND (`RequestItemsText` IS NULL OR `RequestItemsText`='');
UPDATE `quest_template` SET `OfferRewardText`='Ah yes, the water I had requested. Tenaron and Corithras certainly took their time in having it delivered... perhaps not choosing the most reliable of messengers... hmm.$B$BNonetheless, I can finally get back to my work then. The weight of Teldrassil''s problems fall upon my shoulders. A yoke I would wish to soon be rid of.$B$BTake this, you may find some use for it.' WHERE `Id`=935 AND (`OfferRewardText` IS NULL OR `OfferRewardText`='');
UPDATE `quest_template` SET `RequestItemsText`='Their slashing talons and piercing beaks may prove a difficult match for your own abilities, $N, but I have faith that you will not fail in this task.' WHERE `Id`=937 AND (`RequestItemsText` IS NULL OR `RequestItemsText`='');
UPDATE `quest_template` SET `OfferRewardText`='I am impressed by what you have accomplished here in so short a time, $N. Would that I could ask you to remain here to assist me with my duties... but I know in my heart that greater tasks lie ahead for you.$B$BI have noticed the Oracle Tree has just shed a piece of its bark. No doubt it has a task that it wishes completed. You should speak with it.' WHERE `Id`=937 AND (`OfferRewardText` IS NULL OR `OfferRewardText`='');
UPDATE `quest_template` SET `RequestItemsText`='Mist... It was my fault! The witches caught me off guard... I should not have let them take you...' WHERE `Id`=938 AND (`RequestItemsText` IS NULL OR `RequestItemsText`='');
UPDATE `quest_template` SET `OfferRewardText`='Oh, thank you, $N! I feared I would never see Mist again, knowing only her death in my heart, never to be united with my faithful companion. I owe you more than you can know, and you have my eternal gratitude.' WHERE `Id`=938 AND (`OfferRewardText` IS NULL OR `OfferRewardText`='');
UPDATE `quest_template` SET `RequestItemsText`='This planter is filled with soil, specially prepared by Denalan.' WHERE `Id`=941 AND (`RequestItemsText` IS NULL OR `RequestItemsText`='');
UPDATE `quest_template` SET `OfferRewardText`='You place the heart within the planter, and it quickly digs itself in!$B$BA few seconds later it wriggles back out, cleansed. It pulses slightly... beckoning for you to take it.' WHERE `Id`=941 AND (`OfferRewardText` IS NULL OR `OfferRewardText`='');
UPDATE `quest_template` SET `RequestItemsText`='You have something for me?' WHERE `Id`=997 AND (`RequestItemsText` IS NULL OR `RequestItemsText`='');
UPDATE `quest_template` SET `OfferRewardText`='Ah, it''s here! I have waited for this rare earth for quite some time. I hope it''s still fresh...$B$BThank you for bringing it to me, $N. You are a $R who is generous with his time.' WHERE `Id`=997 AND (`OfferRewardText` IS NULL OR `OfferRewardText`='');
UPDATE `quest_template` SET `OfferRewardText`='You notice the chest does not seem to have any water damage.$B$BThe second thing you notice is that the top has been forced open, and whatever magical traps were set to safeguard it have long been triggered--this much is obvious from the burn marks around its edges.' WHERE `Id`=1454 AND (`OfferRewardText` IS NULL OR `OfferRewardText`='');
UPDATE `quest_template` SET `OfferRewardText`='Welcome back to Nijel''s Point, $N. So, tell me what you found.$B$BWhat!? Nothing? An empty chest ain''t gonna get us paid, I''m afraid.$B$BTell me more about these marks you saw... these slashes.' WHERE `Id`=1455 AND (`OfferRewardText` IS NULL OR `OfferRewardText`='');
UPDATE `quest_template` SET `RequestItemsText`='No offense to whoever Nijel is, but this camp ain''t the most comfortable place I''ve spent a night, if you know what I mean, $N.' WHERE `Id`=1456 AND (`RequestItemsText` IS NULL OR `RequestItemsText`='');
UPDATE `quest_template` SET `OfferRewardText`='This is great, $N! You found Karnitol''s belongings!$B$BThose blasted naga, always causing trouble. I think I''d rather spend my life at war with the Horde than have to go against their kind. You''ve done a great service to the Reclaimers.' WHERE `Id`=1456 AND (`OfferRewardText` IS NULL OR `OfferRewardText`='');
UPDATE `quest_template` SET `RequestItemsText`='How might I be of service to you, young one? Are you here to rest in the inn? Do you require a hearthstone?' WHERE `Id`=2159 AND (`RequestItemsText` IS NULL OR `RequestItemsText`='');
UPDATE `quest_template` SET `OfferRewardText`='Ah yes, the delivery of herbs from Shadowglen. It is a shame Porthannius could not bring it himself, for we have much to discuss, he and I. But I am glad to get the herbs nonetheless, and I am glad you came.$B$BWhile you are here, please, rest yourself. Heroes must keep their strength and spirits high, and must find rest and solace whenever they may. For to neglect one''s peace of body and mind is a sure path to failure.$B$BSo... rest.' WHERE `Id`=2159 AND (`OfferRewardText` IS NULL OR `OfferRewardText`='');
UPDATE `quest_template` SET `RequestItemsText`='Please move swiftly. I can only hope that my emerald dreamcatcher has been unharmed by the furbolg.$B$BHave you recovered it yet, $N?' WHERE `Id`=2438 AND (`RequestItemsText` IS NULL OR `RequestItemsText`='');
UPDATE `quest_template` SET `OfferRewardText`='My emerald dreamcatcher is of great importance to me. It is a gift only given to few. Thank you for returning it, $N.' WHERE `Id`=2438 AND (`OfferRewardText` IS NULL OR `OfferRewardText`='');
UPDATE `quest_template` SET `RequestItemsText`='Ferocitas and the Gnarlpine mystics must return what is mine. Please retrieve the emerald so that I may repair my emerald dreamcatcher.' WHERE `Id`=2459 AND (`RequestItemsText` IS NULL OR `RequestItemsText`='');
UPDATE `quest_template` SET `OfferRewardText`='Now I can repair my dreamcatcher. Thank you, $N.' WHERE `Id`=2459 AND (`OfferRewardText` IS NULL OR `OfferRewardText`='');
UPDATE `quest_template` SET `RequestItemsText`='Have you located Oakenscowl yet, $R?' WHERE `Id`=2499 AND (`RequestItemsText` IS NULL OR `RequestItemsText`='');
UPDATE `quest_template` SET `OfferRewardText`='I knew you were more than capable of ridding the lake of that horrible beast.$B$BIt is a distressing situation; Oakenscowl was once a grand leader amongst his kind... but corruption does not discriminate between the lowly and the noble.$B$BThe size of this tumor is quite disturbing, but I must study it to learn more about the disease that upsets the timberling population.$B$BThank you, $N.' WHERE `Id`=2499 AND (`OfferRewardText` IS NULL OR `OfferRewardText`='');
UPDATE `quest_template` SET `RequestItemsText`='I regret the task that I have asked you to carry out; but Lady Sathrah is beyond hope.$B$BIt is our hope to offer the sacrifice of the spinnerets to Elune. With this sacrifice, Elune will bless Sathrah so that she might be reborn, and at peace.' WHERE `Id`=2518 AND (`RequestItemsText` IS NULL OR `RequestItemsText`='');
UPDATE `quest_template` SET `OfferRewardText`='The forest mourns for Lady Sathrah, but it was something that had to be done.$B$BThank you, $N.' WHERE `Id`=2518 AND (`OfferRewardText` IS NULL OR `OfferRewardText`='');
UPDATE `quest_template` SET `RequestItemsText`='If I can examine the charm, I may be able to figure out how to break the enchantment. Have you found one?' WHERE `Id`=2541 AND (`RequestItemsText` IS NULL OR `RequestItemsText`='');
UPDATE `quest_template` SET `OfferRewardText`='Thank you, $N.$B$BWhat an odd trinket this is... I can sense the vile aura emanating from it; this is a very powerful enchantment.' WHERE `Id`=2541 AND (`OfferRewardText` IS NULL OR `OfferRewardText`='');
UPDATE `quest_template` SET `RequestItemsText`='$N, be wary when approaching my physical form; the enchantment it is under is quite powerful.' WHERE `Id`=2561 AND (`RequestItemsText` IS NULL OR `RequestItemsText`='');
UPDATE `quest_template` SET `OfferRewardText`='I am finally free of the control of the Gnarlpine. Thank you, $N.$B$BMy spirit may now rest peacefully forever in the Emerald Dream.$B$BPerhaps one day we may meet again, young $C. But, for now, please accept this reward as a symbol of my gratitude.' WHERE `Id`=2561 AND (`OfferRewardText` IS NULL OR `OfferRewardText`='');
UPDATE `quest_template` SET `RequestItemsText`='Do you have the bones? The caravan will be here any moment. I need just ten more kodo bones to reach a career high. A career high, I tell you!' WHERE `Id`=5501 AND (`RequestItemsText` IS NULL OR `RequestItemsText`='');
UPDATE `quest_template` SET `OfferRewardText`='Ah, goodie! My bones!$B$BI can''t wait till the chaps at home see my face on the front cover of Goblin''preneur. I''ll be the richest goblin in the world... and my physical education teacher said I would never amount to anything.' WHERE `Id`=5501 AND (`OfferRewardText` IS NULL OR `OfferRewardText`='');
UPDATE `quest_template` SET `RequestItemsText`='The caravan will be here shortly; do you have the five new tamed kodos I was asking for?' WHERE `Id`=5561 AND (`RequestItemsText` IS NULL OR `RequestItemsText`='');
UPDATE `quest_template` SET `OfferRewardText`='<Smeed Scrabblescrew begins counting.>$B$BThree, four, and five... excellent, I ask for five tamed kodos and I get five tamed kodos... I am going to be rich... yes, very rich! I hope to see the look on Bibbly''s green face when he hears about my success!' WHERE `Id`=5561 AND (`OfferRewardText` IS NULL OR `OfferRewardText`='');
UPDATE `quest_template` SET `OfferRewardText`='You bring most welcome news $C. It is good to hear that Aynasha is alive and well thanks to you. I would hope that you might accept a reward for your valor. May Elune watch over you and light your path.' WHERE `Id`=5713 AND (`OfferRewardText` IS NULL OR `OfferRewardText`='');
UPDATE `quest_template` SET `RequestItemsText`='Have you seen my sister Melizza? She''s always on the go, which gets her into trouble all the time.' WHERE `Id`=6132 AND (`RequestItemsText` IS NULL OR `RequestItemsText`='');
UPDATE `quest_template` SET `OfferRewardText`='My sister Melizza said you''d be coming. Thanks a lot for getting her out of the jam she was in; it''s too bad that she''s already probably found herself in a new one!' WHERE `Id`=6132 AND (`OfferRewardText` IS NULL OR `OfferRewardText`='');
UPDATE `quest_template` SET `RequestItemsText`='Where''s my ghost-o-plasm, $N?' WHERE `Id`=6134 AND (`RequestItemsText` IS NULL OR `RequestItemsText`='');
UPDATE `quest_template` SET `OfferRewardText`='There it is! Looks like you got some of it on you too. Kinda slimey, eh?$B$BWell, thanks a lot for all the trouble, $N. This stuff will be worth a fortune... if I can convince the centaurs what it is!' WHERE `Id`=6134 AND (`OfferRewardText` IS NULL OR `OfferRewardText`='');
UPDATE `quest_template` SET `RequestItemsText`='How may I help you? Are you in need of transport?' WHERE `Id`=6341 AND (`RequestItemsText` IS NULL OR `RequestItemsText`='');
UPDATE `quest_template` SET `OfferRewardText`='Ah, you wish to get this to Auberdine? Very well...' WHERE `Id`=6341 AND (`OfferRewardText` IS NULL OR `OfferRewardText`='');
UPDATE `quest_template` SET `RequestItemsText`='Have you come from Teldrassil? Tell me, how is the fishing there?' WHERE `Id`=6342 AND (`RequestItemsText` IS NULL OR `RequestItemsText`='');
UPDATE `quest_template` SET `OfferRewardText`='A package from Nessa? Thank you, $N! She told me she would send me samples of the fish caught near Rut''theran village. She thinks they may be very different from the fish caught here...$B$BMy! This jawbone is nearly twice the size of the same fish found here. And these scales are as big as a closed fist! Amazing!' WHERE `Id`=6342 AND (`OfferRewardText` IS NULL OR `OfferRewardText`='');
UPDATE `quest_template` SET `RequestItemsText`='$N, you''re back from Auberdine? Did you speak with Laird?' WHERE `Id`=6343 AND (`RequestItemsText` IS NULL OR `RequestItemsText`='');
UPDATE `quest_template` SET `OfferRewardText`='This is very interesting. The fish here are large, but I didn''t think the difference in bounties between here and the mainland was so great. There must be a reason for this...$B$BWell thank you, $N. I will discuss with the villagers the news you brought. Perhaps, one day, we will find the root of this oddity. But until then, we shall reap its benefits!' WHERE `Id`=6343 AND (`OfferRewardText` IS NULL OR `OfferRewardText`='');
UPDATE `quest_template` SET `RequestItemsText`='How can I help you?' WHERE `Id`=6344 AND (`RequestItemsText` IS NULL OR `RequestItemsText`='');
UPDATE `quest_template` SET `OfferRewardText`='Yes, I have need of a courier who will take a package to Darkshore. Will you help me?' WHERE `Id`=6344 AND (`OfferRewardText` IS NULL OR `OfferRewardText`='');
UPDATE `quest_template` SET `RequestItemsText`='Along with the druids, the Oracle Tree and the Arch Druid have been carefully monitoring the growth of Teldrassil. But though we have a new home, our immortal lives have not been restored.' WHERE `Id`=7383 AND (`RequestItemsText` IS NULL OR `RequestItemsText`='');
UPDATE `quest_template` SET `OfferRewardText`='To be in the presence of the Oracle Tree... it is almost to feel wisdom take form. Let me continue the telling...$B$BWith Teldrassil grown, the Arch Druid approached the dragons for their blessings, as the dragons had placed upon Nordrassil in ancient times. But Nozdormu, Lord of Time, refused to give his blessing, chiding the druid for his arrogance. In agreement with Nozdormu, Alexstrasza also refused Staghelm, and without her blessing, Teldrassil''s growth has been flawed and unpredictable...' WHERE `Id`=7383 AND (`OfferRewardText` IS NULL OR `OfferRewardText`='');
UPDATE `quest_template` SET `RequestItemsText`='Yes friend, may I help you? Do you have a voucher that needs redeeming?' WHERE `Id`=7905 AND (`RequestItemsText` IS NULL OR `RequestItemsText`='');
UPDATE `quest_template` SET `OfferRewardText`='Welcome to the Darkmoon Faire! This voucher is good for FIVE, yes, FIVE prize tickets and a free copy of the world-renowned Darkmoon Adventurer''s Guide!$B$BWhen you accumulate prize tickets, you''ll want to speak to me about redeeming them for valuable prizes. This handy field guide will help you to locate and identify items of value to our collectors here at the faire!' WHERE `Id`=7905 AND (`OfferRewardText` IS NULL OR `OfferRewardText`='');
UPDATE `quest_template` SET `RequestItemsText`='Are you done collecting those samples? We could lose Noggle any minute now!' WHERE `Id`=8277 AND (`RequestItemsText` IS NULL OR `RequestItemsText`='');
UPDATE `quest_template` SET `OfferRewardText`='Cross your fingers, friend! Here''s to hoping we can save Noggle!' WHERE `Id`=8277 AND (`OfferRewardText` IS NULL OR `OfferRewardText`='');
UPDATE `quest_template` SET `RequestItemsText`='This is our last chance to save Noggle! Hurry!' WHERE `Id`=8278 AND (`RequestItemsText` IS NULL OR `RequestItemsText`='');
UPDATE `quest_template` SET `OfferRewardText`='Yes! It seems to be working, Noggle is coming to. We owe ya big time!' WHERE `Id`=8278 AND (`OfferRewardText` IS NULL OR `OfferRewardText`='');
UPDATE `quest_template` SET `RequestItemsText`='Who goes there? Oh, it''s you! Did you find all the Lexicon chapters yet?' WHERE `Id`=8279 AND (`RequestItemsText` IS NULL OR `RequestItemsText`='');
UPDATE `quest_template` SET `OfferRewardText`='Yes! These are the parts to the book! Let''s get started then, $N.$B$BSwap every third word with words from the second chapter... then swap every other word with words from the first chapter... Wait, did I get that backwards?' WHERE `Id`=8279 AND (`OfferRewardText` IS NULL OR `OfferRewardText`='');
UPDATE `quest_template` SET `RequestItemsText`='The dredge strikers are a serious threat and must be dealt with quickly!' WHERE `Id`=8280 AND (`RequestItemsText` IS NULL OR `RequestItemsText`='');
UPDATE `quest_template` SET `OfferRewardText`='You have my sincere gratitude. Your efforts in helping Cenarion Hold have shown true courage.' WHERE `Id`=8280 AND (`OfferRewardText` IS NULL OR `OfferRewardText`='');
UPDATE `quest_template` SET `RequestItemsText`='The dredge crushers are a serious threat and must be dealt with at once!' WHERE `Id`=8281 AND (`RequestItemsText` IS NULL OR `RequestItemsText`='');
UPDATE `quest_template` SET `OfferRewardText`='Excellent! You''ve proven to be a valuable ally in preparing for the war against the silithid.' WHERE `Id`=8281 AND (`OfferRewardText` IS NULL OR `OfferRewardText`='');
UPDATE `quest_template` SET `RequestItemsText`='Still haven''t found my bag? Well I should count my lucky stars, at least the poison''s been cleansed.' WHERE `Id`=8282 AND (`RequestItemsText` IS NULL OR `RequestItemsText`='');
UPDATE `quest_template` SET `OfferRewardText`='Yes! You brought my satchel back. And my rare reagents are all here! I''ll be in your debt for a long time.' WHERE `Id`=8282 AND (`OfferRewardText` IS NULL OR `OfferRewardText`='');
UPDATE `quest_template` SET `RequestItemsText`='I''ll need the creature''s pincer as proof of the deed. No pincer, no reward.' WHERE `Id`=8283 AND (`RequestItemsText` IS NULL OR `RequestItemsText`='');
UPDATE `quest_template` SET `OfferRewardText`='Excellent! With Deathclasp gone we''re free to use the southern mountain range as a strategic path to circumvent the silithid hives. Your work is greatly appreciated.' WHERE `Id`=8283 AND (`OfferRewardText` IS NULL OR `OfferRewardText`='');
UPDATE `quest_template` SET `RequestItemsText`='The ravaged camp can be found northwest of here. Come back when you have all the fragments.' WHERE `Id`=8284 AND (`RequestItemsText` IS NULL OR `RequestItemsText`='');
UPDATE `quest_template` SET `OfferRewardText`='Just as I suspected. I can decipher individual words in the tablets but they appear to be devoid of any logic or meaning. It''s not unknown for Twilight''s Hammer sects to use a code to hide the meaning of their texts; we''ll have to go to someone who knows more about this sort of thing.' WHERE `Id`=8284 AND (`OfferRewardText` IS NULL OR `OfferRewardText`='');
UPDATE `quest_template` SET `RequestItemsText`='You! How did you find me? Who are you? You weren''t followed, were you? Speak!' WHERE `Id`=8285 AND (`RequestItemsText` IS NULL OR `RequestItemsText`='');
UPDATE `quest_template` SET `OfferRewardText`='I see you''re familiar with my old organization. You must be with Cenarion Hold. $B$BYou seek information to use against them? Come closer, perhaps we can be of mutual assistance.' WHERE `Id`=8285 AND (`OfferRewardText` IS NULL OR `OfferRewardText`='');
UPDATE `quest_template` SET `RequestItemsText`='What is this you bring to me, $N?' WHERE `Id`=8287 AND (`RequestItemsText` IS NULL OR `RequestItemsText`='');
UPDATE `quest_template` SET `OfferRewardText`='This is very interesting information indeed, $N. This sheds some light on the presence of the Twilight''s Hammer in Silithus and will undoubtedly help us in our struggle against them. Your efforts will be handsomely rewarded, $C.' WHERE `Id`=8287 AND (`OfferRewardText` IS NULL OR `OfferRewardText`='');
UPDATE `quest_template` SET `RequestItemsText`='Waste no time, $N!' WHERE `Id`=8304 AND (`RequestItemsText` IS NULL OR `RequestItemsText`='');
UPDATE `quest_template` SET `OfferRewardText`='<Commander Mar''alith lowers his head in contemplation.>$B$BWhether she is alive or dead, I must do what is right. She must be found. Alas, I am bound by duty to this outpost. Will you help me once more, $N?' WHERE `Id`=8304 AND (`OfferRewardText` IS NULL OR `OfferRewardText`='');
UPDATE `quest_template` SET `RequestItemsText`='Natalia?' WHERE `Id`=8306 AND (`RequestItemsText` IS NULL OR `RequestItemsText`='');
UPDATE `quest_template` SET `OfferRewardText`='<Commander Mar''alith clutches at his chest.>$B$BC''Thun? WHAT is the meaning of all this? What is C''Thun? How could this fiend have turned my sweet Natalia into the monster that you described?' WHERE `Id`=8306 AND (`OfferRewardText` IS NULL OR `OfferRewardText`='');
UPDATE `quest_template` SET `RequestItemsText`='Oh dear.' WHERE `Id`=8308 AND (`RequestItemsText` IS NULL OR `RequestItemsText`='');
UPDATE `quest_template` SET `OfferRewardText`='Well this explains a lot. If you ever find a way into Ahn''Qiraj, keep an eye out for ol'' Brann. I''m afraid that he''ll be powerless without his monkey.' WHERE `Id`=8308 AND (`OfferRewardText` IS NULL OR `OfferRewardText`='');
UPDATE `quest_template` SET `RequestItemsText`='If you find some crazy night elf lass in one of the hives, be sure to give her a kick in the duff for us.' WHERE `Id`=8309 AND (`RequestItemsText` IS NULL OR `RequestItemsText`='');
UPDATE `quest_template` SET `OfferRewardText`='I can''t make heads or tails of these glyphs. I''ve never seen anything like it! I hope Frankal''s research can shed some light on this mess.' WHERE `Id`=8309 AND (`OfferRewardText` IS NULL OR `OfferRewardText`='');
UPDATE `quest_template` SET `RequestItemsText`='Go play with the monkey, kid. I don''t have time for this.' WHERE `Id`=8310 AND (`RequestItemsText` IS NULL OR `RequestItemsText`='');
UPDATE `quest_template` SET `OfferRewardText`='Outstanding! Don''t wander off too far, kid. We might need you to take on another task or two.' WHERE `Id`=8310 AND (`OfferRewardText` IS NULL OR `OfferRewardText`='');
UPDATE `quest_template` SET `RequestItemsText`='Oh my! What do you have there, $N?' WHERE `Id`=8314 AND (`RequestItemsText` IS NULL OR `RequestItemsText`='');
UPDATE `quest_template` SET `OfferRewardText`='The reason the dwarves could not decipher the glyphs is because there is nothing to decipher. The shifting outer layer of the prism must properly align with the inner crystal''s markings in order for the message to be transmitted. Clever...$B$BWhile we should be able to translate this data, we must first unlock the code. There is only one clue on the surface of the prism - assuming the rubbings were transferred correctly - and it looks grim.' WHERE `Id`=8314 AND (`OfferRewardText` IS NULL OR `OfferRewardText`='');
UPDATE `quest_template` SET `RequestItemsText`='Did you bring me some texts?' WHERE `Id`=8318 AND (`RequestItemsText` IS NULL OR `RequestItemsText`='');
UPDATE `quest_template` SET `OfferRewardText`='Excellent! I''ll stash these away, maybe they''ll be useful later.' WHERE `Id`=8318 AND (`OfferRewardText` IS NULL OR `OfferRewardText`='');
UPDATE `quest_template` SET `OfferRewardText`='Excellent work! I''ll put a good word in for you.' WHERE `Id`=8319 AND (`OfferRewardText` IS NULL OR `OfferRewardText`='');
UPDATE `quest_template` SET `OfferRewardText`='That was a task well performed, $N. Your slaying of the Twilight geolords must have dealt a grievous blow to the cult. Let us hope their plans are slowed...' WHERE `Id`=8320 AND (`OfferRewardText` IS NULL OR `OfferRewardText`='');
UPDATE `quest_template` SET `RequestItemsText`='$N, have you yet defeated Vyral the Vile? Do you have his signet ring?' WHERE `Id`=8321 AND (`RequestItemsText` IS NULL OR `RequestItemsText`='');
UPDATE `quest_template` SET `OfferRewardText`='You''ve done it! Vyral is killed! This can only mean doom for the Twilight Hammer''s operations in Silithus. There may be more of them scurrying about, but the blow you dealt to the cult today is one from which they will not easily recover.' WHERE `Id`=8321 AND (`OfferRewardText` IS NULL OR `OfferRewardText`='');
UPDATE `quest_template` SET `RequestItemsText`='Did you find any encrypted texts? I''m quite curious to read this month''s True Believer.' WHERE `Id`=8323 AND (`RequestItemsText` IS NULL OR `RequestItemsText`='');
UPDATE `quest_template` SET `OfferRewardText`='Excellent! I will get to decoding these as soon as possible. If I find anything of interest I''ll find some way to get the information to you.' WHERE `Id`=8323 AND (`OfferRewardText` IS NULL OR `OfferRewardText`='');
UPDATE `quest_template` SET `OfferRewardText`='Excellent! I can''t wait to read these. Please do keep bringing the encrypted texts here if you find them.' WHERE `Id`=8324 AND (`OfferRewardText` IS NULL OR `OfferRewardText`='');
UPDATE `quest_template` SET `OfferRewardText`='The Alliance needs every able body they can get. The Horde has been receiving a steady supply of reinforcements from the northern part of the continent, and it''s been a struggle to keep up.$B$BLet me explain the situation to you.' WHERE `Id`=9415 AND (`OfferRewardText` IS NULL OR `OfferRewardText`='');
UPDATE `quest_template` SET `RequestItemsText`='Be careful out there, but also be quick. We have no time to lose.' WHERE `Id`=9419 AND (`RequestItemsText` IS NULL OR `RequestItemsText`='');
UPDATE `quest_template` SET `OfferRewardText`='Thank the Light you were successful.$B$BNow if we could only have started this sooner, our need would not be so desperate. We must keep the bounty of the desert from falling into the hands of the Horde.' WHERE `Id`=9419 AND (`OfferRewardText` IS NULL OR `OfferRewardText`='');
UPDATE `quest_template` SET `OfferRewardText`='Good work. Thank you, $C.' WHERE `Id`=13504 AND (`OfferRewardText` IS NULL OR `OfferRewardText`='');
UPDATE `quest_template` SET `RequestItemsText`='Were you able to recover any artifacts?' WHERE `Id`=13505 AND (`RequestItemsText` IS NULL OR `RequestItemsText`='');
UPDATE `quest_template` SET `OfferRewardText`='Perfect! Thank you so much. I would hate to lose more records of our culture to war - far too much has been sacrificed already.' WHERE `Id`=13505 AND (`OfferRewardText` IS NULL OR `OfferRewardText`='');
UPDATE `quest_template` SET `RequestItemsText`='Yes, $C?' WHERE `Id`=13506 AND (`RequestItemsText` IS NULL OR `RequestItemsText`='');
UPDATE `quest_template` SET `OfferRewardText`='"Another?" They have more than one. I will not leave any of my people to be tortured, we must act quickly.' WHERE `Id`=13506 AND (`OfferRewardText` IS NULL OR `OfferRewardText`='');
UPDATE `quest_template` SET `RequestItemsText`='Have you finished the deed?' WHERE `Id`=13507 AND (`RequestItemsText` IS NULL OR `RequestItemsText`='');
UPDATE `quest_template` SET `OfferRewardText`='Excellent work. One more threat we can worry a bit less about. We''ll continue the offensive while they are still off-guard.' WHERE `Id`=13507 AND (`OfferRewardText` IS NULL OR `OfferRewardText`='');
UPDATE `quest_template` SET `OfferRewardText`='<Alanndarian looks very pale, though shallow breaths betray the life that remains in her.>$B$BYou''re here... to save me? A bit later... than I hoped.' WHERE `Id`=13508 AND (`OfferRewardText` IS NULL OR `OfferRewardText`='');
UPDATE `quest_template` SET `OfferRewardText`='Excellent work. That should slow them down a bit.' WHERE `Id`=13509 AND (`OfferRewardText` IS NULL OR `OfferRewardText`='');
UPDATE `quest_template` SET `OfferRewardText`='Some sort of shield you say? We might have a way around that. Balthule had an idea for breaking whatever protective enchantments their shaman had, so it might work on this too. Thank you for saving Aynasha and bringing me this information - it may well make the difference in our battle.' WHERE `Id`=13510 AND (`OfferRewardText` IS NULL OR `OfferRewardText`='');
UPDATE `quest_template` SET `OfferRewardText`='Alanndarian is dead then. That saddens me greatly, but it is not entirely unexpected. I expect no mercy from these savages, and will show them none.' WHERE `Id`=13511 AND (`OfferRewardText` IS NULL OR `OfferRewardText`='');
UPDATE `quest_template` SET `OfferRewardText`='You''ve shown a great deal of talent for one so young. Good work. It seems the final battle is before us.' WHERE `Id`=13512 AND (`OfferRewardText` IS NULL OR `OfferRewardText`='');
UPDATE `quest_template` SET `RequestItemsText`='Did you recover the amulets?' WHERE `Id`=13513 AND (`RequestItemsText` IS NULL OR `RequestItemsText`='');
UPDATE `quest_template` SET `OfferRewardText`='These will do perfectly. I will prepare them for Sandrya - you are sure to be dispatched to meet with her shortly.' WHERE `Id`=13513 AND (`OfferRewardText` IS NULL OR `OfferRewardText`='');
UPDATE `quest_template` SET `RequestItemsText`='I have no yearning for war, but I''ve had sufficient reason to worry that we''d get rusty after so much time away from the front lines. It''s good to see that the Sentinels and the ancients are every bit as dangerous as I remember them.' WHERE `Id`=13514 AND (`RequestItemsText` IS NULL OR `RequestItemsText`='');
UPDATE `quest_template` SET `OfferRewardText`='You performed excellently up there! We are fortunate to have you with us.$B$BI haven''t yet received word regarding their leader. If you haven''t spoken with Sandrya at the cave in the back of the vale, be sure to do so before you depart.' WHERE `Id`=13514 AND (`OfferRewardText` IS NULL OR `OfferRewardText`='');
UPDATE `quest_template` SET `RequestItemsText`='As it should be.' WHERE `Id`=13515 AND (`RequestItemsText` IS NULL OR `RequestItemsText`='');
UPDATE `quest_template` SET `OfferRewardText`='We owe a great debt to you for all that you''ve done to see this battle through.$B$BNot often can we claim victories so decisively, but it seems there''s far more to this plot than just the Shatterspear. If you haven''t already checked his body for information, make sure to do so before you leave.' WHERE `Id`=13515 AND (`OfferRewardText` IS NULL OR `OfferRewardText`='');
UPDATE `quest_template` SET `RequestItemsText`='Their pride kept them in Auberdine for this long, but none deserve such a cruel fate.' WHERE `Id`=13518 AND (`RequestItemsText` IS NULL OR `RequestItemsText`='');
UPDATE `quest_template` SET `OfferRewardText`='Thank you, $C. Some of them surely would not have made it without you.$B$BWe''ll be taking the wounded to the main building once we have them all safely back in town. Perhaps you can meet us there later?' WHERE `Id`=13518 AND (`OfferRewardText` IS NULL OR `OfferRewardText`='');
UPDATE `quest_template` SET `OfferRewardText`='You''ve done well, $N. The Twilight''s Hammer is a dangerous cult. It would be foolish to underestimate the danger they represent.' WHERE `Id`=13519 AND (`OfferRewardText` IS NULL OR `OfferRewardText`='');
UPDATE `quest_template` SET `RequestItemsText`='Did you bring muscles from the clams? I worry that our time grows very short.' WHERE `Id`=13520 AND (`RequestItemsText` IS NULL OR `RequestItemsText`='');
UPDATE `quest_template` SET `OfferRewardText`='This will do perfectly. Thank you so much!$B$BI suspect they will want to thank you personally should they recover, so perhaps you can stop by later on.' WHERE `Id`=13520 AND (`OfferRewardText` IS NULL OR `OfferRewardText`='');
UPDATE `quest_template` SET `RequestItemsText`='<Buzzbox 413 hums at you expectantly.>' WHERE `Id`=13521 AND (`RequestItemsText` IS NULL OR `RequestItemsText`='');
UPDATE `quest_template` SET `OfferRewardText`='<The machine crackles loudly, and then Wizbang''s static-ridden voice becomes audible.>$B$BLovely! I hope you didn''t kill too many of them. We''re not trying to wipe out the population, we just need to get to the source of this corruption quickly! I''m proceeding with the analysis now.' WHERE `Id`=13521 AND (`OfferRewardText` IS NULL OR `OfferRewardText`='');
UPDATE `quest_template` SET `RequestItemsText`='Have you cleared the coast?' WHERE `Id`=13522 AND (`RequestItemsText` IS NULL OR `RequestItemsText`='');
UPDATE `quest_template` SET `OfferRewardText`='Your efforts are very much appreciated. Since the Cataclysm, the elementals have been out of control. We have little hope of taking back Auberdine without extinguishing their presence first.' WHERE `Id`=13522 AND (`OfferRewardText` IS NULL OR `OfferRewardText`='');
UPDATE `quest_template` SET `RequestItemsText`='My lifeforce abandons me... even now...' WHERE `Id`=13523 AND (`RequestItemsText` IS NULL OR `RequestItemsText`='');
UPDATE `quest_template` SET `OfferRewardText`='You''ve succeeded... it hasn''t all been in vain...$B$BMy time approaches. Go now, $N, and may Elune protect you.' WHERE `Id`=13523 AND (`OfferRewardText` IS NULL OR `OfferRewardText`='');
UPDATE `quest_template` SET `OfferRewardText`='Why have you come here, outsider?$B$B<You tell the elder that you were sent by Foriel Broadleaf at the Grove of the Ancients. He seems to relax slightly.>$B$BThe elf is right. The forces of Felwood have seeped into Darkshore and sickened my people.' WHERE `Id`=13525 AND (`OfferRewardText` IS NULL OR `OfferRewardText`='');
UPDATE `quest_template` SET `RequestItemsText`='Have you gathered the bear''s paw?' WHERE `Id`=13526 AND (`RequestItemsText` IS NULL OR `RequestItemsText`='');
UPDATE `quest_template` SET `OfferRewardText`='These are poor, weak stalks, but they are all we have. The corruption spreads quickly, even among the plants of the forest.' WHERE `Id`=13526 AND (`OfferRewardText` IS NULL OR `OfferRewardText`='');
UPDATE `quest_template` SET `RequestItemsText`='Welcome back! Did you find that bear sample that I was looking for?' WHERE `Id`=13527 AND (`RequestItemsText` IS NULL OR `RequestItemsText`='');
UPDATE `quest_template` SET `OfferRewardText`='This definitely looks like the stuff they were eating. Let me take a closer peek...' WHERE `Id`=13527 AND (`OfferRewardText` IS NULL OR `OfferRewardText`='');
UPDATE `quest_template` SET `RequestItemsText`='<Buzzbox 723 hums at you expectantly.>' WHERE `Id`=13528 AND (`RequestItemsText` IS NULL OR `RequestItemsText`='');
UPDATE `quest_template` SET `OfferRewardText`='<Static precedes Wizbang''s distorted voice.>$B$BThe results are coming in now. We should have some information on how the bears contracted this in just a moment.' WHERE `Id`=13528 AND (`OfferRewardText` IS NULL OR `OfferRewardText`='');
UPDATE `quest_template` SET `RequestItemsText`='This is never desirable work. Zenn was not always the corrupt being that you now see. Sadly, he is behind reproach at this point. Much of the damage that he has done to nature is irreversible.' WHERE `Id`=13529 AND (`RequestItemsText` IS NULL OR `RequestItemsText`='');
UPDATE `quest_template` SET `OfferRewardText`='It is done then. Thank you. I only hope that the wildlife here will see more peace with his passing.' WHERE `Id`=13529 AND (`OfferRewardText` IS NULL OR `OfferRewardText`='');
UPDATE `quest_template` SET `OfferRewardText`='I cannot thank you enough, $N. Now we''ll have a fighting chance to retake the ruins as soon as we are in better health.' WHERE `Id`=13542 AND (`OfferRewardText` IS NULL OR `OfferRewardText`='');
UPDATE `quest_template` SET `OfferRewardText`='Without those three coaxing them, perhaps the flow of elementals into the Ruins of Auberdine will be stemmed.$B$BThank you, $N.' WHERE `Id`=13543 AND (`OfferRewardText` IS NULL OR `OfferRewardText`='');
UPDATE `quest_template` SET `RequestItemsText`='Have you visited the old bear statue?' WHERE `Id`=13544 AND (`RequestItemsText` IS NULL OR `RequestItemsText`='');
UPDATE `quest_template` SET `OfferRewardText`='<Elder Brolg accepts the blessed bundle from you and looks over it.>$B$BThis is exactly what we needed. The bear''s spirit favors us and there may be hope for my brothers after all.' WHERE `Id`=13544 AND (`OfferRewardText` IS NULL OR `OfferRewardText`='');
UPDATE `quest_template` SET `RequestItemsText`='Have your efforts and the bear''s blessing cleansed my brothers?' WHERE `Id`=13545 AND (`RequestItemsText` IS NULL OR `RequestItemsText`='');
UPDATE `quest_template` SET `OfferRewardText`='You have done well. My people have begun to emerge from their madness, but they will fall back into it if we do not deal with the source of the corruption.' WHERE `Id`=13545 AND (`OfferRewardText` IS NULL OR `OfferRewardText`='');
UPDATE `quest_template` SET `RequestItemsText`='Have you defeated the satyr who poisons our lands?' WHERE `Id`=13546 AND (`RequestItemsText` IS NULL OR `RequestItemsText`='');
UPDATE `quest_template` SET `OfferRewardText`='Thank you, $N. You are a hero to my people. Without you, we would be doomed to madness and death. May the bear spirit always watch over you.' WHERE `Id`=13546 AND (`OfferRewardText` IS NULL OR `OfferRewardText`='');
UPDATE `quest_template` SET `OfferRewardText`='So much death and pain. Can there be any doubt that there is more yet to come?$B$BAll I wish to do is move onward into the Goddess''s embrace as do these others.$B$BBut first, let us see if we can keep even more misery and destruction from being spread.' WHERE `Id`=13547 AND (`OfferRewardText` IS NULL OR `OfferRewardText`='');
UPDATE `quest_template` SET `RequestItemsText`='Did you get to the stuff? The sooner I can start working on a cure, the more animals we can save!' WHERE `Id`=13554 AND (`RequestItemsText` IS NULL OR `RequestItemsText`='');
UPDATE `quest_template` SET `OfferRewardText`='This should be plenty! Thanks so much! I''ll get working on a cure for this nastiness immediately.' WHERE `Id`=13554 AND (`OfferRewardText` IS NULL OR `OfferRewardText`='');
UPDATE `quest_template` SET `RequestItemsText`='Yes, $R?' WHERE `Id`=13557 AND (`RequestItemsText` IS NULL OR `RequestItemsText`='');
UPDATE `quest_template` SET `OfferRewardText`='I am pleased to hear that you were able to free some of the remaining wildlife. With a bit of good fortune, we will find the cure for the corruption that the others have faced before any more of them die.' WHERE `Id`=13557 AND (`OfferRewardText` IS NULL OR `OfferRewardText`='');
UPDATE `quest_template` SET `RequestItemsText`='You have returned. What news do you bring?' WHERE `Id`=13558 AND (`RequestItemsText` IS NULL OR `RequestItemsText`='');
UPDATE `quest_template` SET `OfferRewardText`='Yalda? The spirits of others from the Ruins of Auberdine?$B$B<The druid ponders what you''ve conveyed about your adventure in the ruins.>$B$BI remember them all. They will be dearly missed, but they have moved on into the Goddess''s embrace and that is for the best.$B$BAnde''thoras-ethil, may your troubles be diminished, $N!' WHERE `Id`=13558 AND (`OfferRewardText` IS NULL OR `OfferRewardText`='');
UPDATE `quest_template` SET `RequestItemsText`='You done yet, boy?' WHERE `Id`=13560 AND (`RequestItemsText` IS NULL OR `RequestItemsText`='');
UPDATE `quest_template` SET `OfferRewardText`='The decoys worked then? Great to hear it! Don''t you worry yourself one bit about the treasures. Me and Gary will take care of the rest this time around.$B$BTruth be told, if something went wrong again and I lost any more of you adventurer types, I''m pretty sure they''d kick me out of town.' WHERE `Id`=13560 AND (`OfferRewardText` IS NULL OR `OfferRewardText`='');
UPDATE `quest_template` SET `RequestItemsText`='Is it done?' WHERE `Id`=13561 AND (`RequestItemsText` IS NULL OR `RequestItemsText`='');
UPDATE `quest_template` SET `OfferRewardText`='You have my thanks. Though they may not be able to show it, you have the thanks of the Highborne spirits as well.$B$BFare safely, traveler.' WHERE `Id`=13561 AND (`OfferRewardText` IS NULL OR `OfferRewardText`='');
UPDATE `quest_template` SET `OfferRewardText`='You have our thanks. It is time that we leave the past behind us, and start looking to our future.' WHERE `Id`=13562 AND (`OfferRewardText` IS NULL OR `OfferRewardText`='');
UPDATE `quest_template` SET `RequestItemsText`='I somehow avoided being inflicted with the same toxin that the other survivors now endure. I cannot help but be envious of them to a degree though... living an eternity alone seems not worth living at all.$B$BI miss you so much, Anaya.' WHERE `Id`=13563 AND (`RequestItemsText` IS NULL OR `RequestItemsText`='');
UPDATE `quest_template` SET `OfferRewardText`='Thank you, $N. Perhaps it would have been better... if I had done it myself. But even after these thousands of years, I could not bear to raise my hand against my beloved.$B$BPlease, I would be alone with my grief...' WHERE `Id`=13563 AND (`OfferRewardText` IS NULL OR `OfferRewardText`='');
UPDATE `quest_template` SET `OfferRewardText`='Greetings, traveler. You seem to have an interest in my friend here. You''re here on behalf of his friend Volcor then I imagine? If Volcor didn''t come himself, he must be injured as well. I hope he recovers quickly.$B$BGrimclaw is too injured to be moved far and he''s going to need some immediate treatment. I''m afraid I can''t let you take him back just yet, but perhaps you can help me while I tend to him.' WHERE `Id`=13564 AND (`OfferRewardText` IS NULL OR `OfferRewardText`='');
UPDATE `quest_template` SET `OfferRewardText`='Thank you, ally. We shall keep a more vigilant eye should they return.' WHERE `Id`=13565 AND (`OfferRewardText` IS NULL OR `OfferRewardText`='');
UPDATE `quest_template` SET `RequestItemsText`='Have you retrieved the materials that I asked for? And please tell me that you did not harm any of the animals in the process...' WHERE `Id`=13566 AND (`RequestItemsText` IS NULL OR `RequestItemsText`='');
UPDATE `quest_template` SET `OfferRewardText`='These will do perfectly. These are the final ingredients for an incense I''ve been working on. I will explain in just a moment, let me mix these in first.' WHERE `Id`=13566 AND (`OfferRewardText` IS NULL OR `OfferRewardText`='');
UPDATE `quest_template` SET `OfferRewardText`='I am the caretaker for my kind, leading not through force, but through wisdom and swift action. Wisdom is what carries us into the deeper forest when danger beckons and swiftness is what leaves our enemies basking in our absence.$B$BIn this wisdom, I see through to your true intentions, and I know that you are deserving of my blessing, the blessing of my swiftness. It can be yours, but know that the other spirits will not welcome you once you proceed - consider this carefully before accepting my boon.' WHERE `Id`=13567 AND (`OfferRewardText` IS NULL OR `OfferRewardText`='');
UPDATE `quest_template` SET `OfferRewardText`='So it is done. You have received the blessing of a great animal spirit, and I shall now complete the ritual for you. Please stand still.' WHERE `Id`=13569 AND (`OfferRewardText` IS NULL OR `OfferRewardText`='');
UPDATE `quest_template` SET `OfferRewardText`='Thank you, $N. With your efforts, we might be able to save the Blackwood who remain.' WHERE `Id`=13572 AND (`OfferRewardText` IS NULL OR `OfferRewardText`='');
UPDATE `quest_template` SET `OfferRewardText`='There is no time to waste, $C. It is taking every ounce of my power to keep Darkshore''s entire landmass from being shattered and swept into the ocean... you must listen to me very carefully.' WHERE `Id`=13573 AND (`OfferRewardText` IS NULL OR `OfferRewardText`='');
UPDATE `quest_template` SET `OfferRewardText`='I have much respect for the great Malfurion Stormrage. I cannot, however, leave my people in their time of need. Maybe there is a way we can both help each other.' WHERE `Id`=13575 AND (`OfferRewardText` IS NULL OR `OfferRewardText`='');
UPDATE `quest_template` SET `RequestItemsText`='Is it done yet, $N?' WHERE `Id`=13576 AND (`RequestItemsText` IS NULL OR `RequestItemsText`='');
UPDATE `quest_template` SET `OfferRewardText`='The element of fire is unique in that attacking it indiscriminately can often lead it to spreading further... succeeding only in agitating its flames.$B$BWe are wiser than that, $N. We are going to dispose of it properly.' WHERE `Id`=13576 AND (`OfferRewardText` IS NULL OR `OfferRewardText`='');
UPDATE `quest_template` SET `OfferRewardText`='A terrible sadness surrounds the creature. Its eyes stare beyond you as you approach it.' WHERE `Id`=13577 AND (`OfferRewardText` IS NULL OR `OfferRewardText`='');
UPDATE `quest_template` SET `RequestItemsText`='You bring others'' feathers?' WHERE `Id`=13578 AND (`RequestItemsText` IS NULL OR `RequestItemsText`='');
UPDATE `quest_template` SET `OfferRewardText`='I thank you, $R. Soon my kin will rest.' WHERE `Id`=13578 AND (`OfferRewardText` IS NULL OR `OfferRewardText`='');
UPDATE `quest_template` SET `OfferRewardText`='If the great Malfurion requires my presence, it is my duty to heed his call. It is also my duty to protect these ruins, however.$B$BPerhaps you''ll help me fulfill both my obligations, $N?' WHERE `Id`=13579 AND (`OfferRewardText` IS NULL OR `OfferRewardText`='');
UPDATE `quest_template` SET `RequestItemsText`='Is it done, $N?' WHERE `Id`=13580 AND (`RequestItemsText` IS NULL OR `RequestItemsText`='');
UPDATE `quest_template` SET `OfferRewardText`='We are in your debt, $N. Perhaps now, with Malfurion''s help, we can save the rest of Darkshore.' WHERE `Id`=13580 AND (`OfferRewardText` IS NULL OR `OfferRewardText`='');
UPDATE `quest_template` SET `OfferRewardText`='This is fortunate news, $N. The furbolg may seem little more than a savage race, but their ties to the land are ancient and their shamans are second to none.' WHERE `Id`=13581 AND (`OfferRewardText` IS NULL OR `OfferRewardText`='');
UPDATE `quest_template` SET `RequestItemsText`='You have torch?' WHERE `Id`=13582 AND (`RequestItemsText` IS NULL OR `RequestItemsText`='');
UPDATE `quest_template` SET `OfferRewardText`='<Aroom lets out a long low-pitched hoot.>$B$BFinally kin may rest.' WHERE `Id`=13582 AND (`OfferRewardText` IS NULL OR `OfferRewardText`='');
UPDATE `quest_template` SET `OfferRewardText`='The wildkin were once the guardians of the land. It is good to hear they haven''t all forgotten their old ways.' WHERE `Id`=13583 AND (`OfferRewardText` IS NULL OR `OfferRewardText`='');
UPDATE `quest_template` SET `RequestItemsText`='The land is deeply unsettled, $N. It''ll be years before calm returns to these parts.' WHERE `Id`=13584 AND (`RequestItemsText` IS NULL OR `RequestItemsText`='');
UPDATE `quest_template` SET `OfferRewardText`='It''s become clear, $N. The elements won''t be calm until Malfurion succeeds in returning balance to the land. Aiding him is, in a way, also fulfilling my task.' WHERE `Id`=13584 AND (`OfferRewardText` IS NULL OR `OfferRewardText`='');
UPDATE `quest_template` SET `OfferRewardText`='Excellent job, $N! Selenn''s help in holding back the vortex will be invaluable.' WHERE `Id`=13585 AND (`OfferRewardText` IS NULL OR `OfferRewardText`='');
UPDATE `quest_template` SET `OfferRewardText`='Malfurion calls? Yes... I can hear his voice through the dream...' WHERE `Id`=13586 AND (`OfferRewardText` IS NULL OR `OfferRewardText`='');
UPDATE `quest_template` SET `RequestItemsText`='Did you find it, $N?' WHERE `Id`=13587 AND (`RequestItemsText` IS NULL OR `RequestItemsText`='');
UPDATE `quest_template` SET `OfferRewardText`='I thank you, $N. You''ve given me my freedom. Let''s see what we can do for your world now.' WHERE `Id`=13587 AND (`OfferRewardText` IS NULL OR `OfferRewardText`='');
UPDATE `quest_template` SET `RequestItemsText`='Is it done, $N? I fear I cannot hold for much longer.' WHERE `Id`=13588 AND (`RequestItemsText` IS NULL OR `RequestItemsText`='');
UPDATE `quest_template` SET `OfferRewardText`='We are turning the tides, $N. We should be able to contain further damage.$B$BMuch work still remains to be done.' WHERE `Id`=13588 AND (`OfferRewardText` IS NULL OR `OfferRewardText`='');
UPDATE `quest_template` SET `OfferRewardText`='Glynda sent you to lend a hand, did she? I''m glad she did - I could certainly use the help.$B$BI''m working on our initial plans to start whittling away at their ranks. Please feel free to help Tysha and Balthule in the meantime.' WHERE `Id`=13589 AND (`OfferRewardText` IS NULL OR `OfferRewardText`='');
UPDATE `quest_template` SET `RequestItemsText`='Greetings, $C. Did you bring the arrow?' WHERE `Id`=13590 AND (`RequestItemsText` IS NULL OR `RequestItemsText`='');
UPDATE `quest_template` SET `OfferRewardText`='It is good to meet you. Word has been sent to me of the efforts you have made to aid us against the trolls, and I must admit I am a bit impressed. The final fight is upon us now, I hope you are prepared.' WHERE `Id`=13590 AND (`OfferRewardText` IS NULL OR `OfferRewardText`='');
UPDATE `quest_template` SET `RequestItemsText`='You''re back! I hear the battle went well.' WHERE `Id`=13591 AND (`RequestItemsText` IS NULL OR `RequestItemsText`='');
UPDATE `quest_template` SET `OfferRewardText`='Well, this news is disturbing indeed. I will start dispatching messengers to Ashenvale immediately and see if we can''t get some reinforcements prepared for them.$B$BI cannot thank you enough for all the help you''ve lent us in these trying times. Such heroic deeds deserve reward. I think I might have something that will serve you perfectly.' WHERE `Id`=13591 AND (`OfferRewardText` IS NULL OR `OfferRewardText`='');
UPDATE `quest_template` SET `OfferRewardText`='<The sentinel eyes you appreciatively for a moment.>$B$BA job well done, $C. If you''re any indication of the quality of the $R adventurers we''re going to be seeing more of, we should have this war against the orcs and their Horde taken care of faster than expected.' WHERE `Id`=13594 AND (`OfferRewardText` IS NULL OR `OfferRewardText`='');
UPDATE `quest_template` SET `RequestItemsText`='Your lives are all so short. Why is it that you insist on squandering them by killing each other?' WHERE `Id`=13595 AND (`RequestItemsText` IS NULL OR `RequestItemsText`='');
UPDATE `quest_template` SET `OfferRewardText`='You have helped me to return to the ground, $N.$B$BNow my hair will cease to sprout for these creatures. Better yet, I will be regrown all the sooner.' WHERE `Id`=13595 AND (`OfferRewardText` IS NULL OR `OfferRewardText`='');
UPDATE `quest_template` SET `RequestItemsText`='Have you obtained the plans yet, $N?' WHERE `Id`=13596 AND (`RequestItemsText` IS NULL OR `RequestItemsText`='');
UPDATE `quest_template` SET `OfferRewardText`='Excellent job, $N. Now give me a moment to examine the plans you''ve brought me.' WHERE `Id`=13596 AND (`OfferRewardText` IS NULL OR `OfferRewardText`='');
UPDATE `quest_template` SET `RequestItemsText`='Grimclaw is quite the fierce combatant. I feel somewhat sorry for those poachers, despite their aims.' WHERE `Id`=13598 AND (`RequestItemsText` IS NULL OR `RequestItemsText`='');
UPDATE `quest_template` SET `OfferRewardText`='You have my thanks, young one. We should be able to speed Grimclaw''s recovery dramatically with this salve.' WHERE `Id`=13598 AND (`OfferRewardText` IS NULL OR `OfferRewardText`='');
UPDATE `quest_template` SET `OfferRewardText`='You''ve returned! It is good to see you again. I suppose we have you to thank for Grimclaw''s return?$B$BI''m afraid... I have some bad news. I''ve been unable to purge the toxin... their conditions worsen. Gershalla died shortly after you left, and Volcor... Volcor passed just before you came back.$B$BHe lived long enough to see Grimclaw come back safely, so he died with a smile on his face. I''m just sorry that I couldn''t do more.$B$BFor now, I''m doing everything I can to save Shaldyn, so please excuse me.' WHERE `Id`=13599 AND (`OfferRewardText` IS NULL OR `OfferRewardText`='');
UPDATE `quest_template` SET `OfferRewardText`='I thank you for coming to our assistance. As you can see, the refugees'' situation is dire.' WHERE `Id`=13601 AND (`OfferRewardText` IS NULL OR `OfferRewardText`='');
UPDATE `quest_template` SET `OfferRewardText`='Very well done, $N. Your actions in the Zoram Strand against the naga are commendable.$B$BI know your feat was not easily accomplished, for the strength and guile of the naga is well known to the night elves. We know this, for we share a history with them.$B$BThe naga are cursed Highborne night elves. Ten thousand years ago, Queen Azshara made a pact of desperation with the Old Gods to save her surviving people from a watery grave.$B$BThe naga are the result of that pact.' WHERE `Id`=13602 AND (`OfferRewardText` IS NULL OR `OfferRewardText`='');
UPDATE `quest_template` SET `OfferRewardText`='Aye, you''re the fine lad who saved my Hollee!$B$BWell, I''ve got a fitting reward for you here, I''m sure. We really can''t thank you enough for bringing her to safety, $N.' WHERE `Id`=13605 AND (`OfferRewardText` IS NULL OR `OfferRewardText`='');
UPDATE `quest_template` SET `OfferRewardText`='Hello, $C.$B$BWhat''s that? You say that Shyela sent you?$B$BVery well, let''s get started.' WHERE `Id`=13617 AND (`OfferRewardText` IS NULL OR `OfferRewardText`='');
UPDATE `quest_template` SET `RequestItemsText`='You''re a brave one to come here given the circumstances.$B$BWhat business have you, stranger?' WHERE `Id`=13623 AND (`RequestItemsText` IS NULL OR `RequestItemsText`='');
UPDATE `quest_template` SET `OfferRewardText`='So, Evenar was succesful. Actually, more to the point, YOU were successful.$B$BI cannot thank you enough, $C, but there is more that must be done to the leaves before they will serve as a curative for what ails the child, Relara.' WHERE `Id`=13623 AND (`OfferRewardText` IS NULL OR `OfferRewardText`='');
UPDATE `quest_template` SET `RequestItemsText`='That''s not nearly enough, $C. We''re about to lose our ground here and when that happens, it''s all over for this section of the forest.$B$BWe must hold the line here!' WHERE `Id`=13624 AND (`RequestItemsText` IS NULL OR `RequestItemsText`='');
UPDATE `quest_template` SET `OfferRewardText`='I''d received a report about you from some of my scouts out in the forest but I had no idea how capable you are!$B$BThank you, $N. With what you''ve accomplished the tide is turned. I''ve no doubt now that we''ll rout them by the end of the day!' WHERE `Id`=13624 AND (`OfferRewardText` IS NULL OR `OfferRewardText`='');
UPDATE `quest_template` SET `RequestItemsText`='Our losses here have been staggering.' WHERE `Id`=13626 AND (`RequestItemsText` IS NULL OR `RequestItemsText`='');
UPDATE `quest_template` SET `OfferRewardText`='I do not look forward to writing the letter to the Argent Dawn embassy in Darnassus. At least we''ll be able to send their most prized possessions back for their loved ones.$B$BI cannot thank you enough for your courage, $N. Please accept this on behalf of the post.' WHERE `Id`=13626 AND (`OfferRewardText` IS NULL OR `OfferRewardText`='');
UPDATE `quest_template` SET `OfferRewardText`='Thank you, $N.$B$BWith the moonstones of Ordil''Aran deactivated, we should not need to worry about any further incursions of furbolg here.$B$BHowever, my scouts have returned with disturbing news from the furbolg village. There is an imminent danger massing there.$B$BI wonder, might I entice you to carry a warning to Astranaar for me?' WHERE `Id`=13630 AND (`OfferRewardText` IS NULL OR `OfferRewardText`='');
UPDATE `quest_template` SET `RequestItemsText`='Ordil''Aran was a night elf city once long ago. It fell to ruins during the Sundering and only recently had some outsiders moved in to pillage it.$B$BNow they are dead, victims of their own curiosity that attracted the furbolg down upon them.' WHERE `Id`=13632 AND (`RequestItemsText` IS NULL OR `RequestItemsText`='');
UPDATE `quest_template` SET `OfferRewardText`='We are in your debt, $C. If I know anything about the furbolg, they do not like their noses bloodied.$B$BIt won''t be long now before they tuck tail and return to their village.' WHERE `Id`=13632 AND (`OfferRewardText` IS NULL OR `OfferRewardText`='');
UPDATE `quest_template` SET `RequestItemsText`='Did you have any trouble getting to the Light of Elune at Lake Falathim?' WHERE `Id`=13642 AND (`RequestItemsText` IS NULL OR `RequestItemsText`='');
UPDATE `quest_template` SET `OfferRewardText`='With the concoction blessed by the Light of Elune, it should be ready for delivery to Astranaar.$B$BThere is no time to waste, $N!' WHERE `Id`=13642 AND (`OfferRewardText` IS NULL OR `OfferRewardText`='');
UPDATE `quest_template` SET `RequestItemsText`='The harbinger yet lives, $N. I cannot begin to cleanse Lake Falathim until it is slain.' WHERE `Id`=13644 AND (`RequestItemsText` IS NULL OR `RequestItemsText`='');
UPDATE `quest_template` SET `OfferRewardText`='With the death of the harbinger, I can begin to cleanse the lake.$B$BYou have my deepest thanks, $N. I mourn the loss of your friend, but know that his remains will fuel the reclamation of the forest hereabouts.' WHERE `Id`=13644 AND (`OfferRewardText` IS NULL OR `OfferRewardText`='');
UPDATE `quest_template` SET `RequestItemsText`='I am Raene Wolfrunner. Who might you be?' WHERE `Id`=13645 AND (`RequestItemsText` IS NULL OR `RequestItemsText`='');
UPDATE `quest_template` SET `OfferRewardText`='Teronis is dead?$B$B<The lady weeps softly for the loss of her friend and then composes herself after a moment.>$B$BWe must see to it that his sacrifice was not in vain. Are you willing to see this through, $C?$B$BVery well, allow me some time to think about how we should proceed. I will know shortly.' WHERE `Id`=13645 AND (`OfferRewardText` IS NULL OR `OfferRewardText`='');
UPDATE `quest_template` SET `OfferRewardText`='Avana is alive?! I feared that she might be dead when we heard about the attack on Maestra''s Post!$B$BAs you can see, we have our hands full with the Horde here as well.$B$BYou have given me the greatest gift by letting me know she is well. Any time that you wish to ride one of my nightsabers back to Maestra''s Post, it is yours.' WHERE `Id`=13646 AND (`OfferRewardText` IS NULL OR `OfferRewardText`='');
UPDATE `quest_template` SET `RequestItemsText`='Please see to it that you disturb as many of the ritual gems as you can.$B$BThe last thing that we want is for any of the draenei here to be twisted into one of the Broken, or the elves to be corrupted into more satyrs.' WHERE `Id`=13683 AND (`RequestItemsText` IS NULL OR `RequestItemsText`='');
UPDATE `quest_template` SET `OfferRewardText`='We are in your debt, $C.$B$BUnable to complete their nefarious rituals, the satyr are now fighting a losing battle where they are unable to replenish their numbers.' WHERE `Id`=13683 AND (`OfferRewardText` IS NULL OR `OfferRewardText`='');
UPDATE `quest_template` SET `RequestItemsText`='Time''s running out, $N.' WHERE `Id`=13698 AND (`RequestItemsText` IS NULL OR `RequestItemsText`='');
UPDATE `quest_template` SET `OfferRewardText`='I saw those explosions all of the way from over here! Those filthy orcs and their goblin lackeys are going to have a hard time doing anything to despoil the forest now!$B$BWe can''t thank you enough, $N. Will this do?' WHERE `Id`=13698 AND (`OfferRewardText` IS NULL OR `OfferRewardText`='');
UPDATE `quest_template` SET `OfferRewardText`='With their gates closed and no further reinforcements coming, it is only a matter of time now before the demons are no more.$B$BYou are a hero of the forest, $N. I give you thanks on behalf of all of Ashenvale''s creatures!' WHERE `Id`=13766 AND (`OfferRewardText` IS NULL OR `OfferRewardText`='');
UPDATE `quest_template` SET `OfferRewardText`='You are brave to come here, $C, but you may be too late. All of the druids are either dead or have been driven insane.$B$BStill, your tale is intriguing, and if what you say is true, then Gnarl must have the Forest Heart and soon, or Ashenvale will begin to wither!' WHERE `Id`=13792 AND (`OfferRewardText` IS NULL OR `OfferRewardText`='');
UPDATE `quest_template` SET `RequestItemsText`='$N, you have returned.' WHERE `Id`=13796 AND (`RequestItemsText` IS NULL OR `RequestItemsText`='');
UPDATE `quest_template` SET `OfferRewardText`='The Forest Heart! It''s corrupted!$B$B<The great ancient creaks as its immense limbs begin to perform a ritual.>$B$BStand back, $N, I will try to cleanse the heart before all is lost!' WHERE `Id`=13796 AND (`OfferRewardText` IS NULL OR `OfferRewardText`='');
UPDATE `quest_template` SET `RequestItemsText`='What''s this? You found something else in the cave?' WHERE `Id`=13831 AND (`RequestItemsText` IS NULL OR `RequestItemsText`='');
UPDATE `quest_template` SET `OfferRewardText`='<Tharnariun Treetender pages through the notes as you relate your story, the lines in his face deepening with concern.>$B$BSo the Forsaken have been studying Foulhoof''s work? My gut crawls at the thought of what they might have done were they able to weaponize his corruption. You''ve done well to destroy their work, but this raises deeper concerns. What brought the Forsaken to our doorstep? Are they working with the Shatterspear trolls to our north? Sorrows are heaping upon sorrows, $C. I''m glad you''re here.' WHERE `Id`=13831 AND (`OfferRewardText` IS NULL OR `OfferRewardText`='');
UPDATE `quest_template` SET `RequestItemsText`='Narassin is no longer our concern, but if his life''s work should fall to our enemies, centuries of dark wisdom could be called down onto our heads. How goes the hunt?' WHERE `Id`=13844 AND (`RequestItemsText` IS NULL OR `RequestItemsText`='');
UPDATE `quest_template` SET `OfferRewardText`='Let''s see what we''ve got here.... By Elune, his notes are scrawled in a half dozen languages. What is this, blood? This archive makes my flesh seethe, but at least it''s secure. It will take us some time to decipher these notes.$B$BOh - your reward? Yes, here. Nice work with those undead scavengers. Now get back to the fight.' WHERE `Id`=13844 AND (`OfferRewardText` IS NULL OR `OfferRewardText`='');
UPDATE `quest_template` SET `RequestItemsText`='What are you waiting for? Put those fires out!' WHERE `Id`=13849 AND (`RequestItemsText` IS NULL OR `RequestItemsText`='');
UPDATE `quest_template` SET `OfferRewardText`='Thank you!$B$BNow it''s time to deal with the Horde!' WHERE `Id`=13849 AND (`OfferRewardText` IS NULL OR `OfferRewardText`='');
UPDATE `quest_template` SET `RequestItemsText`='There''s still more of them bombing us. Please, $N, shoot them down!' WHERE `Id`=13853 AND (`RequestItemsText` IS NULL OR `RequestItemsText`='');
UPDATE `quest_template` SET `OfferRewardText`='We''re saved! You''ve shot down enough of them that we should be able to handle the rest.$B$BI cannot thank you enough, $N.' WHERE `Id`=13853 AND (`OfferRewardText` IS NULL OR `OfferRewardText`='');
UPDATE `quest_template` SET `OfferRewardText`='Well done, $N.$B$BWe are under constant threat from the furbolg. Hopefully this will keep them at bay for a bit longer.' WHERE `Id`=13867 AND (`OfferRewardText` IS NULL OR `OfferRewardText`='');
UPDATE `quest_template` SET `RequestItemsText`='What''s troubling you, $C?' WHERE `Id`=13868 AND (`RequestItemsText` IS NULL OR `RequestItemsText`='');
UPDATE `quest_template` SET `OfferRewardText`='A troll charm? What are the furbolg doing with such a thing?$B$BYou''re right, it does have a feeling of corruption about it... even I can sense that.$B$BThere''s someone here who might be able to help.' WHERE `Id`=13868 AND (`OfferRewardText` IS NULL OR `OfferRewardText`='');
UPDATE `quest_template` SET `RequestItemsText`='Have you the remains, little one?' WHERE `Id`=13869 AND (`RequestItemsText` IS NULL OR `RequestItemsText`='');
UPDATE `quest_template` SET `OfferRewardText`='I have lived a very long time in peace with the forest, but what these orc-things are doing makes me want to feed them back to the ground!$B$BI will put this wood to rest now. Thank you for this kindness, $N. I will never forget.' WHERE `Id`=13869 AND (`OfferRewardText` IS NULL OR `OfferRewardText`='');
UPDATE `quest_template` SET `RequestItemsText`='<The worgen gives you a blank look as you walk up to him.>' WHERE `Id`=13872 AND (`RequestItemsText` IS NULL OR `RequestItemsText`='');
UPDATE `quest_template` SET `OfferRewardText`='<Looking down at the wooden carving in your extended hand, the worgen reaches out to take it.>' WHERE `Id`=13872 AND (`OfferRewardText` IS NULL OR `OfferRewardText`='');
UPDATE `quest_template` SET `RequestItemsText`='Do you think that you retrieved all of the troll charms from Thistlefur Hold?$B$BIf any are left behind, the Thistlefur tribe will continue to be influenced by them, and eventually they will attack this place.' WHERE `Id`=13874 AND (`RequestItemsText` IS NULL OR `RequestItemsText`='');
UPDATE `quest_template` SET `OfferRewardText`='<Hephaestus nods slowly as he looks you straight in the eye.>$B$BYou''ve likely saved the Thistlefur from themselves, at least in the short run. If they can keep from stealing objects of power that don''t belong to them, that is.$B$BI understand that the night elves are having problems with the other furbolg tribe to the south. That''s something that Raene is going to want to speak to you about.$B$BHowever, there are more immediate concerns that I would ask for your help with.' WHERE `Id`=13874 AND (`OfferRewardText` IS NULL OR `OfferRewardText`='');
UPDATE `quest_template` SET `RequestItemsText`='Well? The future of the Thistlefur rests upon your shoulders, $R.' WHERE `Id`=13876 AND (`RequestItemsText` IS NULL OR `RequestItemsText`='');
UPDATE `quest_template` SET `OfferRewardText`='What was done had to be done. As our leader, Dal''s sickness from the troll charms was destroying us.$B$BIt was better for the health and dignity of the tribe that it was you, outsider. This way there will be no civil war amongst us and we will easily find new leadership... hopefully one that does not have a tendency to so easily trust outsiders. Perhaps I am guilty of this as well?$B$BHere, allow me to repay the debt we owe you before we part ways forever.' WHERE `Id`=13876 AND (`OfferRewardText` IS NULL OR `OfferRewardText`='');
UPDATE `quest_template` SET `OfferRewardText`='My brother must have sent you. He wouldn''t have done so unless you are capable of doing what must be done.$B$BFor all of our sakes I hope that he''s right.$B$BThe elementals here are now my allies. You must do as they ask if we are to prevent the destruction of the rest of Ashenvale.' WHERE `Id`=13877 AND (`OfferRewardText` IS NULL OR `OfferRewardText`='');
UPDATE `quest_template` SET `OfferRewardText`='<Kathrena recoils at your description of the ravaged animals and the cruel device at the bottom of the lake.>$B$B$N, this is terrible. What is that thing, and how did it get there? Something is devouring these animals, physically and spiritually. I had suspected the satyrs or some sort of disease was the culprit, but this is shaping up to be something... unnatural.' WHERE `Id`=13881 AND (`OfferRewardText` IS NULL OR `OfferRewardText`='');
UPDATE `quest_template` SET `RequestItemsText`='Life is powerful, $N. Concentrated in its purest form, it can overcome anything. Someday, even Darkshore will heal from its wounds. Did you find everything I need?' WHERE `Id`=13882 AND (`RequestItemsText` IS NULL OR `RequestItemsText`='');
UPDATE `quest_template` SET `OfferRewardText`='Perfect, this is everything. Did you have fun collecting the wisp? I used to chase the wisps around Ashenvale when I was just a girl.$B$B<Lost in memories for a moment, Kathrena suddenly grows somber.>$B$BI''m afraid I''ve found out what we''re dealing with.' WHERE `Id`=13882 AND (`OfferRewardText` IS NULL OR `OfferRewardText`='');
UPDATE `quest_template` SET `OfferRewardText`='So the animals are safe, then. Thank you, thank you!$B$BBut now it''s time to turn our attention to the source.' WHERE `Id`=13885 AND (`OfferRewardText` IS NULL OR `OfferRewardText`='');
UPDATE `quest_template` SET `OfferRewardText`='It is done. The power of fire is subdued and the four elements are returned to harmony.$B$BYou have saved the rest of Ashenvale through your brave and selfless actions, $N. You have our eternal thanks.' WHERE `Id`=13886 AND (`OfferRewardText` IS NULL OR `OfferRewardText`='');
UPDATE `quest_template` SET `RequestItemsText`='I''m afraid to ask, $N. Is the artifact destroyed? What about its guardian?' WHERE `Id`=13891 AND (`RequestItemsText` IS NULL OR `RequestItemsText`='');
UPDATE `quest_template` SET `OfferRewardText`='Love of Elune, look at you. That must''ve been some fight! You''re covered in what looks like... chowder.$B$BIf a mere minion could cause so much agony here in Darkshore, I can''t even imagine the suffering that a true Old One could bring about.$B$BWell, at least the animals are safe for now. I will plant the sapling you created to help rebuild this shattered land. Thank you, $N! I''d give you a hug but, you know. Chowder.' WHERE `Id`=13891 AND (`OfferRewardText` IS NULL OR `OfferRewardText`='');
UPDATE `quest_template` SET `OfferRewardText`='This is dire news, $N. If you are correct, then we''d best act swiftly and decisively.$B$BWe cannot allow this "Soggoth" to be brought back to life.' WHERE `Id`=13892 AND (`OfferRewardText` IS NULL OR `OfferRewardText`='');
UPDATE `quest_template` SET `OfferRewardText`='The dwarf''s story is unsettling... yet informative. It seems we have few options left.' WHERE `Id`=13893 AND (`OfferRewardText` IS NULL OR `OfferRewardText`='');
UPDATE `quest_template` SET `OfferRewardText`='Aros''s body appears to be lifeless yet still warm. Perhaps his killers are nearby.' WHERE `Id`=13895 AND (`OfferRewardText` IS NULL OR `OfferRewardText`='');
UPDATE `quest_template` SET `OfferRewardText`='Oh, we know a thing or two about this Soggoth. The question is... do you really want to know?' WHERE `Id`=13896 AND (`OfferRewardText` IS NULL OR `OfferRewardText`='');
UPDATE `quest_template` SET `OfferRewardText`='We can finally rest here now, $N. It appears Darkshore has been saved -- and we have you to thank for it.' WHERE `Id`=13897 AND (`OfferRewardText` IS NULL OR `OfferRewardText`='');
UPDATE `quest_template` SET `OfferRewardText`='Well done, $N. The naga seek the destruction and subjugation of all surface-dwellers -- do not hesitate to drive them out of our lands and back into the shadowy ocean depths where they belong.' WHERE `Id`=13898 AND (`OfferRewardText` IS NULL OR `OfferRewardText`='');
UPDATE `quest_template` SET `OfferRewardText`='The warlord doesn''t seem to have the horn on him. Perhaps he was telling the truth.' WHERE `Id`=13899 AND (`OfferRewardText` IS NULL OR `OfferRewardText`='');
UPDATE `quest_template` SET `RequestItemsText`='Hail, $N.' WHERE `Id`=13900 AND (`RequestItemsText` IS NULL OR `RequestItemsText`='');
UPDATE `quest_template` SET `OfferRewardText`='You''ve done well, $N. Unfortunately the battle is far from over.' WHERE `Id`=13900 AND (`OfferRewardText` IS NULL OR `OfferRewardText`='');
UPDATE `quest_template` SET `OfferRewardText`='If Malfurion placed his trust in you, then so shall I. You''ll find that our enemies greatly outnumber us this far south.$B$BWhere brute force and numbers fail us, strategy and guile will prove our biggest advantages.' WHERE `Id`=13902 AND (`OfferRewardText` IS NULL OR `OfferRewardText`='');
UPDATE `quest_template` SET `OfferRewardText`='Bravo, $N! Now let''s take a look-see at our new situation.$B$BWhat? MORE murlocs? I swear on my stones, the more murlocs you kill, the more murlocs appear. Is it just me? We''re going to need a new approach.' WHERE `Id`=13907 AND (`OfferRewardText` IS NULL OR `OfferRewardText`='');
UPDATE `quest_template` SET `RequestItemsText`='Wet enough for ya?' WHERE `Id`=13909 AND (`RequestItemsText` IS NULL OR `RequestItemsText`='');
UPDATE `quest_template` SET `OfferRewardText`='<Archaeologist Groff picks through the wreckage.>$B$BWell, not much here that don''t look stepped on, sat on, or soaked in a toilet. But toss some thatch on top and it''ll do.$B$BTell me, $N, do you consider yourself an architect?' WHERE `Id`=13909 AND (`OfferRewardText` IS NULL OR `OfferRewardText`='');
UPDATE `quest_template` SET `RequestItemsText`='How goes our new seaside condo?' WHERE `Id`=13910 AND (`RequestItemsText` IS NULL OR `RequestItemsText`='');
UPDATE `quest_template` SET `OfferRewardText`='Har har, that sounds like quite a heap you built there. Did they take to it? Good, good! Let''s see if my plan comes to fruition.$B$B<Archaeologist Groff watches as scores of murlocs stream down the beach, pouring into the hovel from all corners of the compass. Gradually his brows knit together.>$B$BWhat have I done?' WHERE `Id`=13910 AND (`OfferRewardText` IS NULL OR `OfferRewardText`='');
UPDATE `quest_template` SET `RequestItemsText`='Prospector Remtravel is an unsung hero! Like any great explorer, he is prone to wandering aimlessly.' WHERE `Id`=13911 AND (`RequestItemsText` IS NULL OR `RequestItemsText`='');
UPDATE `quest_template` SET `OfferRewardText`='Ah, you''ve helped the Prospector find his missing journal! To think it was here all along.$B$BSomeday you''ll have to show me this other set of ruins he''s always going on about.' WHERE `Id`=13911 AND (`OfferRewardText` IS NULL OR `OfferRewardText`='');
UPDATE `quest_template` SET `RequestItemsText`='Did you find it? Groff wants to clear out of these ruins as soon as possible!' WHERE `Id`=13912 AND (`RequestItemsText` IS NULL OR `RequestItemsText`='');
UPDATE `quest_template` SET `OfferRewardText`='Spectacular! Good work, $N. I''m sure Remtravel would thank you himself if he could remember your name.$B$BLook at the surface of the disc - these microscopic etchings - this is amazing. I''m certain this strange wheel holds information, if only we could read it...' WHERE `Id`=13912 AND (`OfferRewardText` IS NULL OR `OfferRewardText`='');
UPDATE `quest_template` SET `OfferRewardText`='Thank you, $N. Grim news you bring of the rest of the gnome team, but at least you managed to save a few. For that I am grateful.' WHERE `Id`=13913 AND (`OfferRewardText` IS NULL OR `OfferRewardText`='');
UPDATE `quest_template` SET `RequestItemsText`='Did you assemble all the pieces of the slotted device? We may need to remove Prospector Remtravel''s sandwich from the ancient data interface.' WHERE `Id`=13918 AND (`RequestItemsText` IS NULL OR `RequestItemsText`='');
UPDATE `quest_template` SET `OfferRewardText`='Why yes, yes, this is it! See here, the slot is the exact dimensions of the ancient disc, just as I''d surmised. Here''s your reward, $N - you''ve earned it.$B$BAre you ready to meet history face to face? Let''s see what the ancients have to say!' WHERE `Id`=13918 AND (`OfferRewardText` IS NULL OR `OfferRewardText`='');
UPDATE `quest_template` SET `OfferRewardText`='<The satyr sneers, but when he realizes you are not here to chastise him, he changes his expression.>$B$BFinally, my redemption is at hand. I have waited long for this day and I think I know how to help you in turn.' WHERE `Id`=13921 AND (`OfferRewardText` IS NULL OR `OfferRewardText`='');
UPDATE `quest_template` SET `RequestItemsText`='Five moonstones are required to assure that the girl is healed.' WHERE `Id`=13922 AND (`RequestItemsText` IS NULL OR `RequestItemsText`='');
UPDATE `quest_template` SET `OfferRewardText`='You have all of the moonstones that are needed. And yet, it is said that a sacrifice of life is the only way to ensure the saving of another.$B$BI will ensure that no matter what, the moonstones will cure Relara.' WHERE `Id`=13922 AND (`OfferRewardText` IS NULL OR `OfferRewardText`='');
UPDATE `quest_template` SET `RequestItemsText`='$N, is that you? Have you returned with the cure for Relara?' WHERE `Id`=13924 AND (`RequestItemsText` IS NULL OR `RequestItemsText`='');
UPDATE `quest_template` SET `OfferRewardText`='Oh, $N, you have saved my daughter! I know the power of the moonstones will give back my daughter her strength!$B$BI can never repay you fully for the aid you have given me, but... please, take this. Other than Relara, it is my most dear possession.' WHERE `Id`=13924 AND (`OfferRewardText` IS NULL OR `OfferRewardText`='');
UPDATE `quest_template` SET `RequestItemsText`='The sapling you carry grows in power even as we speak. Life is regenerative, $N. Did it work?' WHERE `Id`=13925 AND (`RequestItemsText` IS NULL OR `RequestItemsText`='');
UPDATE `quest_template` SET `OfferRewardText`='Interesting... It sounds like our cure will keep the wildlife safe, but you say you saw something else? Some kind of angry presence?$B$BThis is a good sign, $N. Whatever is behind this isn''t happy, and that means we''re on to something.' WHERE `Id`=13925 AND (`OfferRewardText` IS NULL OR `OfferRewardText`='');
UPDATE `quest_template` SET `RequestItemsText`='I''m amazed that you broke through the Horde lines and managed to get in here, $R.' WHERE `Id`=13928 AND (`RequestItemsText` IS NULL OR `RequestItemsText`='');
UPDATE `quest_template` SET `OfferRewardText`='Thank you, $C. We have our hands full defending the retreat, but when I can catch my breath, I''ll see to it that these sisters are returned to life, the Goddess willing.$B$BYou''ve demonstrated your prowess... we can use your help.' WHERE `Id`=13928 AND (`OfferRewardText` IS NULL OR `OfferRewardText`='');
UPDATE `quest_template` SET `OfferRewardText`='A brutal display, but one fitting for the enemies of Ashenvale. The Horde dares to think that they can take our beloved forest away from us.$B$BThey are fatally mistaken!$B$BYou have saved Raynewood from destruction, $N. Surely we can find a reward suitable for our champion?' WHERE `Id`=13935 AND (`OfferRewardText` IS NULL OR `OfferRewardText`='');
UPDATE `quest_template` SET `OfferRewardText`='You''re just in time, $N. I don''t know how much longer we can hold.' WHERE `Id`=13940 AND (`OfferRewardText` IS NULL OR `OfferRewardText`='');
UPDATE `quest_template` SET `OfferRewardText`='Impressive. I hope my huntress carried her weight.$B$BIf we continue with this fervor, we may yet still free Teldrassil from the corruption that Alexstrasza herself could not burn out.' WHERE `Id`=13945 AND (`OfferRewardText` IS NULL OR `OfferRewardText`='');
UPDATE `quest_template` SET `OfferRewardText`='Good. I know this probably wasn''t very pleasant work, but we greatly appreciate it.$B$BI fear for our dear Teldrassil... it seems it is becoming more corrupt by the day, and our ignorance to the cause is plaguing me greatly.' WHERE `Id`=13946 AND (`OfferRewardText` IS NULL OR `OfferRewardText`='');
UPDATE `quest_template` SET `OfferRewardText`='This is dire news, $N. If you are correct, then we''d best act swiftly and decisively.$B$BWe cannot allow this "Soggoth" to be brought back to life.' WHERE `Id`=13948 AND (`OfferRewardText` IS NULL OR `OfferRewardText`='');
UPDATE `quest_template` SET `OfferRewardText`='The naga are in league with the Twilight''s Hammer? Just what we needed.' WHERE `Id`=13953 AND (`OfferRewardText` IS NULL OR `OfferRewardText`='');
UPDATE `quest_template` SET `OfferRewardText`='Good to finally meet you, $N. I''ve heard all about what you''ve been up to and let me just say that I''m impressed!$B$BThink you can lend us your expertise?' WHERE `Id`=13964 AND (`OfferRewardText` IS NULL OR `OfferRewardText`='');
UPDATE `quest_template` SET `OfferRewardText`='You say that Faldreas sent you? Good man.$B$BAs it happens, we could use your help.' WHERE `Id`=13965 AND (`OfferRewardText` IS NULL OR `OfferRewardText`='');
UPDATE `quest_template` SET `OfferRewardText`='$C, you must be wary! Kaliva, the foul demoness who has chained us is nearby!' WHERE `Id`=13976 AND (`OfferRewardText` IS NULL OR `OfferRewardText`='');
UPDATE `quest_template` SET `RequestItemsText`='Did you shut that disgusting, wart-ridden goblin up for good?' WHERE `Id`=13979 AND (`RequestItemsText` IS NULL OR `RequestItemsText`='');
UPDATE `quest_template` SET `OfferRewardText`='That''s better. Without him, their technicians are sure to fall back to their normal laziness, which should result in fewer bombs and more accidents.' WHERE `Id`=13979 AND (`OfferRewardText` IS NULL OR `OfferRewardText`='');
UPDATE `quest_template` SET `OfferRewardText`='They what? IT''S HOW BIG?!!!$B$BI have a very bad feeling about this, $N.' WHERE `Id`=13981 AND (`OfferRewardText` IS NULL OR `OfferRewardText`='');
UPDATE `quest_template` SET `RequestItemsText`='If we are to be free, we must have Kaliva''s heart.' WHERE `Id`=13982 AND (`RequestItemsText` IS NULL OR `RequestItemsText`='');
UPDATE `quest_template` SET `OfferRewardText`='Disgusting, I know, but if we three are to be free of Kaliva''s chains, it is not enough that she is dead.$B$BWe must eat of her fel heart!' WHERE `Id`=13982 AND (`OfferRewardText` IS NULL OR `OfferRewardText`='');
UPDATE `quest_template` SET `OfferRewardText`='A fine job, my little $R friend. But as you can see, I am a little busy here.' WHERE `Id`=13985 AND (`OfferRewardText` IS NULL OR `OfferRewardText`='');
UPDATE `quest_template` SET `OfferRewardText`='You''ve saved us all, $N! I have the power to finish off these final few.$B$BNo longer will the forest have to fear the Burning Legion!' WHERE `Id`=13987 AND (`OfferRewardText` IS NULL OR `OfferRewardText`='');
UPDATE `quest_template` SET `OfferRewardText`='Good. Murgut sold his own tribe out to the Horde, allying with them when they took your precious Silverwind Refuge in order to ''save'' his people.$B$BHe sold them into slavery, or worse. And now he has gotten what he deserved!$B$BLet us speak now of a different traitor, one whom I believe has something that will make that rod of yours even more powerful.' WHERE `Id`=13989 AND (`OfferRewardText` IS NULL OR `OfferRewardText`='');
UPDATE `quest_template` SET `RequestItemsText`='Did you find the source of the corruption?' WHERE `Id`=14005 AND (`RequestItemsText` IS NULL OR `RequestItemsText`='');
UPDATE `quest_template` SET `OfferRewardText`='Elune be praised!$B$BEverything I had encountered suggested this corruption to be buried deep within Teldrassil itself... I had worried we might never be able to strike at the source without killing the world tree. I am thankful I was wrong!$B$BMalfurion was the start to this great turn of fortune. Perhaps I will seek him out before I depart to the wilds again.$B$BThank you, $N. Thank you for everything you have done. You are sure to be a great hero someday!' WHERE `Id`=14005 AND (`OfferRewardText` IS NULL OR `OfferRewardText`='');
UPDATE `quest_template` SET `RequestItemsText`='How fare you, young one?' WHERE `Id`=14039 AND (`RequestItemsText` IS NULL OR `RequestItemsText`='');
UPDATE `quest_template` SET `OfferRewardText`='Ah, the blessed waters from our moonwells. You have borne witness to the Spirit of the Kaldorei, then?$B$BIn recent times, I''ve come to find that the spirit offers more questions than it does answers, but such is the continuing nature of discovery that drives us in our darkest hours.$B$BI will offer you the simplest answers that I can. Malfurion has returned to me... to us... but harsh times are yet upon us. Staghelm is gone and the world is wracked with pain - Malfurion has much to mend, and he will need help.' WHERE `Id`=14039 AND (`OfferRewardText` IS NULL OR `OfferRewardText`='');
UPDATE `quest_template` SET `OfferRewardText`='After filling it with liquid from the melons, you proceed to wash your eyes from the ancient font.$B$BUpon opening your eyes, you are able to see the spirits of ancient elves, still faithfully carrying out rituals to their goddess.' WHERE `Id`=14193 AND (`OfferRewardText` IS NULL OR `OfferRewardText`='');
