UPDATE `quest_template` SET `OfferRewardText`='This is how I got my start, you know.$B$BSlingin'' poison to the rogues in Orgrimmar. Ahh, those were the days....' WHERE `Id`=14251 AND (`OfferRewardText` IS NULL OR `OfferRewardText`='');
