UPDATE `quest_template` SET `OfferRewardText`='What''s this?$B$B<Bizby examines the ore.>$B$BWahoo! I know someone who will be most interested in acquiring these samples.$B$BMost generous in payment for them as well, I''ll wager.$B$BHere, $C. Take this as your finder''s fee.' WHERE `Id`=14254 AND (`OfferRewardText` IS NULL OR `OfferRewardText`='');
