UPDATE `quest_template` SET `OfferRewardText`='Hmm... yes, these seeds will do nicely. You have the gratitude of the Cenarion Circle, $N.' WHERE `Id`=24686 AND (`OfferRewardText` IS NULL OR `OfferRewardText`='');
UPDATE `quest_template` SET `OfferRewardText`='You return victorious. Good, good... perhaps the crater will now be a bit safer to those who travel through it.' WHERE `Id`=24687 AND (`OfferRewardText` IS NULL OR `OfferRewardText`='');
UPDATE `quest_template` SET `OfferRewardText`='Ahh... did Garl send you? How are his studies coming? I find that he can be a bit slow at times, but he''s truly a force to be reckoned with when he takes the form of the bear.$B$BNow, we have more pressing matters to attend to.' WHERE `Id`=24689 AND (`OfferRewardText` IS NULL OR `OfferRewardText`='');
UPDATE `quest_template` SET `OfferRewardText`='At last, Blazerunner is dispatched. Thanks, $N... he was driving me batty.' WHERE `Id`=24690 AND (`OfferRewardText` IS NULL OR `OfferRewardText`='');
UPDATE `quest_template` SET `RequestItemsText`='I need a lot of them because I''ve got to pay for shipping, handling, marketing... oh, and I''ve got to pay you as well.' WHERE `Id`=24691 AND (`RequestItemsText` IS NULL OR `RequestItemsText`='');
UPDATE `quest_template` SET `OfferRewardText`='Brilliant! We''re on the cusp of something big here, $N. Here''s your share of the inevitably huge profits.$B$BNow, on to other matters...' WHERE `Id`=24691 AND (`OfferRewardText` IS NULL OR `OfferRewardText`='');
UPDATE `quest_template` SET `OfferRewardText`='You''ve completed a remarkable task, $N. You are truly worthy of commendation. Thank you, and congratulations!' WHERE `Id`=24692 AND (`OfferRewardText` IS NULL OR `OfferRewardText`='');
UPDATE `quest_template` SET `OfferRewardText`='Very well, if Quixxil recommended you, then I suppose you''re alright. In all our years working together, Quixxil''s never steered me wrong.' WHERE `Id`=24693 AND (`OfferRewardText` IS NULL OR `OfferRewardText`='');
UPDATE `quest_template` SET `OfferRewardText`='I have been watching you, $N. Your arrival was not unforeseen.$B$BIn fact, your arrival here has been predetermined for some time now.' WHERE `Id`=24694 AND (`OfferRewardText` IS NULL OR `OfferRewardText`='');
UPDATE `quest_template` SET `RequestItemsText`='You have not yet completed my gauntlet, $N.' WHERE `Id`=24695 AND (`RequestItemsText` IS NULL OR `RequestItemsText`='');
UPDATE `quest_template` SET `OfferRewardText`='You have proven to be both wise and agile, young $N. You have my blessing to take your newfound knowledge and spread it as you continue on your journey.' WHERE `Id`=24695 AND (`OfferRewardText` IS NULL OR `OfferRewardText`='');
UPDATE `quest_template` SET `RequestItemsText`='Throw the meat, then let the dinosaurs chase you into the pit. Easy as that!' WHERE `Id`=24697 AND (`RequestItemsText` IS NULL OR `RequestItemsText`='');
UPDATE `quest_template` SET `OfferRewardText`='Excellent work, $N. Now we''re a bit safer from dinosaur attacks... plus I''ve got all this fresh meat to serve to my men.' WHERE `Id`=24697 AND (`OfferRewardText` IS NULL OR `OfferRewardText`='');
UPDATE `quest_template` SET `OfferRewardText`='Good ol'' Nolen. How is he doing? Hopefully better than I am...' WHERE `Id`=24698 AND (`OfferRewardText` IS NULL OR `OfferRewardText`='');
UPDATE `quest_template` SET `RequestItemsText`='I''m counting on you, $N. I''m invested pretty heavily into this "tar as glue" scheme, and it''d be a shame if you came back empty-handed.' WHERE `Id`=24699 AND (`RequestItemsText` IS NULL OR `RequestItemsText`='');
UPDATE `quest_template` SET `OfferRewardText`='Yes, this tar is just the stuff...$B$BHey, wait a minute, my hands... I can''t seem to get them apart...$B$BMaybe this wasn''t such a good idea. Oh, but wait! Super sticky tar remover! That''s where the real money is!' WHERE `Id`=24699 AND (`OfferRewardText` IS NULL OR `OfferRewardText`='');
UPDATE `quest_template` SET `RequestItemsText`='Have you obtained the tarblossoms yet? I don''t see them...' WHERE `Id`=24700 AND (`RequestItemsText` IS NULL OR `RequestItemsText`='');
UPDATE `quest_template` SET `OfferRewardText`='Oh, there they are. Great work, handsome! Here''s some gold. You''ve earned it.' WHERE `Id`=24700 AND (`OfferRewardText` IS NULL OR `OfferRewardText`='');
UPDATE `quest_template` SET `RequestItemsText`='Did you find anything good?' WHERE `Id`=24701 AND (`RequestItemsText` IS NULL OR `RequestItemsText`='');
UPDATE `quest_template` SET `OfferRewardText`='It''s a bunch of junk, but it''s a bunch of FREE junk, and that''s all that matters to me.$B$BWell, mostly free. Here''s your share. Thanks!' WHERE `Id`=24701 AND (`OfferRewardText` IS NULL OR `OfferRewardText`='');
UPDATE `quest_template` SET `RequestItemsText`='Your first quest is a simple one, yet it somehow remains unfinished. Endure my words and become my squire.' WHERE `Id`=24703 AND (`RequestItemsText` IS NULL OR `RequestItemsText`='');
UPDATE `quest_template` SET `OfferRewardText`='You please me, $N. From this day forward, you are no longer a simple beggar, but a squire loyal to Maximillian of Northshire. Prepare yourself for our first sally, good squire, for together we shall plunge our fists elbow-deep into what they call adventure!' WHERE `Id`=24703 AND (`OfferRewardText` IS NULL OR `OfferRewardText`='');
UPDATE `quest_template` SET `OfferRewardText`='...and that makes 15 of them.$B$BJustice had a name today... and that name was Maximillian of Northshire. For Doloria!' WHERE `Id`=24704 AND (`OfferRewardText` IS NULL OR `OfferRewardText`='');
UPDATE `quest_template` SET `OfferRewardText`='Our duty is fulfilled. Even so, it troubles me that the people of today are less than gracious... Perhaps tomorrow we shall experience proper thankfulness.$B$BNow we must ride. More adventures await!' WHERE `Id`=24705 AND (`OfferRewardText` IS NULL OR `OfferRewardText`='');
UPDATE `quest_template` SET `RequestItemsText`='We have not completed our prayers. Shall I join you?' WHERE `Id`=24706 AND (`RequestItemsText` IS NULL OR `RequestItemsText`='');
UPDATE `quest_template` SET `OfferRewardText`='Might I ask you a question? What act have you committed to make the spirits so angry at you? I''m impressed that you had the patience to sit so still while they pummeled you so violently.$B$BNow we may proceed. The teeth and scales of Un''Goro''s greatest dragon await us.' WHERE `Id`=24706 AND (`OfferRewardText` IS NULL OR `OfferRewardText`='');
UPDATE `quest_template` SET `RequestItemsText`='Have you found anything? Did it work?' WHERE `Id`=24708 AND (`RequestItemsText` IS NULL OR `RequestItemsText`='');
UPDATE `quest_template` SET `OfferRewardText`='What an interesting femur you''ve brought here, but why''s it all sharp and curvy?$B$B...$B$BWait a minute, that thing''s a TALON? A dinosaur with a talon that size would''ve been... well, really big, that''s for sure. Is this the only fossil that you found there?' WHERE `Id`=24708 AND (`OfferRewardText` IS NULL OR `OfferRewardText`='');
UPDATE `quest_template` SET `RequestItemsText`='Is the deed done? Did you manage to salvage his notes?' WHERE `Id`=24709 AND (`RequestItemsText` IS NULL OR `RequestItemsText`='');
UPDATE `quest_template` SET `OfferRewardText`='I knew it! Durrin HAS been digging around here. And he''s been excavating what could be the archaeological find of the century! Now I just have to find out where he''s stashing the bones...$B$BThanks $N. You''ve been a great help.' WHERE `Id`=24709 AND (`OfferRewardText` IS NULL OR `OfferRewardText`='');
UPDATE `quest_template` SET `OfferRewardText`='A-Me lies motionless before you. No power seems to be running through her components.' WHERE `Id`=24714 AND (`OfferRewardText` IS NULL OR `OfferRewardText`='');
UPDATE `quest_template` SET `RequestItemsText`='<A-Me 01 has gone into power save mode.>' WHERE `Id`=24715 AND (`RequestItemsText` IS NULL OR `RequestItemsText`='');
UPDATE `quest_template` SET `OfferRewardText`='You pour the coconut milk into what appears to be A-Me 01''s oil reservoir. You hear the sound of gears whirring and actuators firing.' WHERE `Id`=24715 AND (`OfferRewardText` IS NULL OR `OfferRewardText`='');
UPDATE `quest_template` SET `RequestItemsText`='I never know what style is in vogue, so I''ll want a few different colors. Try to get hides from each different type of gorilla there.' WHERE `Id`=24717 AND (`RequestItemsText` IS NULL OR `RequestItemsText`='');
UPDATE `quest_template` SET `OfferRewardText`='Wow, 2 of each color! You''re certainly an overachiever, $N. My companions and I could use a $R like you around here. Ever consider a career in profiteering?' WHERE `Id`=24717 AND (`OfferRewardText` IS NULL OR `OfferRewardText`='');
UPDATE `quest_template` SET `RequestItemsText`='Red fur? What''re you waiting for! Go back and get that red gorilla! I''ll pay you double!' WHERE `Id`=24718 AND (`RequestItemsText` IS NULL OR `RequestItemsText`='');
UPDATE `quest_template` SET `OfferRewardText`='Wow, look at this one! Not just the color, but the size of it... you could cover a tauren with this.$B$BHere you go, $N. You''ve earned this. Stick around, I''m sure we can find something else for you to do.' WHERE `Id`=24718 AND (`OfferRewardText` IS NULL OR `OfferRewardText`='');
UPDATE `quest_template` SET `RequestItemsText`='Have you gotten any of the claws yet?' WHERE `Id`=24719 AND (`RequestItemsText` IS NULL OR `RequestItemsText`='');
UPDATE `quest_template` SET `OfferRewardText`='My mentor says that sometimes you have to take away from nature before you can give back. These raptors... I feel that they died for good cause.$B$BThank you, $N.' WHERE `Id`=24719 AND (`OfferRewardText` IS NULL OR `OfferRewardText`='');
UPDATE `quest_template` SET `RequestItemsText`='I just know I''m onto something here, $N!' WHERE `Id`=24720 AND (`RequestItemsText` IS NULL OR `RequestItemsText`='');
UPDATE `quest_template` SET `OfferRewardText`='Now I will continue my experiments! Thank you, $N.' WHERE `Id`=24720 AND (`OfferRewardText` IS NULL OR `OfferRewardText`='');
UPDATE `quest_template` SET `OfferRewardText`='You were right to bring this pylon to my attention, $N. This is just the sort of thing I''ve been studying.' WHERE `Id`=24721 AND (`OfferRewardText` IS NULL OR `OfferRewardText`='');
UPDATE `quest_template` SET `RequestItemsText`='Yes, $N?' WHERE `Id`=24722 AND (`RequestItemsText` IS NULL OR `RequestItemsText`='');
UPDATE `quest_template` SET `OfferRewardText`='You think this may be related to the attacks on Marshal''s Refuge, $N?' WHERE `Id`=24722 AND (`OfferRewardText` IS NULL OR `OfferRewardText`='');
UPDATE `quest_template` SET `OfferRewardText`='A pylon in the west? And a relationship between titans and dinosaurs? This is a lot to take in, $N.' WHERE `Id`=24723 AND (`OfferRewardText` IS NULL OR `OfferRewardText`='');
UPDATE `quest_template` SET `RequestItemsText`='Think whatever you want of me, but they''re not going to care if the bones they get to research are from ancient stegodons and diemetradons or the ones that almost devoured us wholesale when we were trying to set up our camps. I''ll just be happy if we get out of here alive...' WHERE `Id`=24730 AND (`RequestItemsText` IS NULL OR `RequestItemsText`='');
UPDATE `quest_template` SET `OfferRewardText`='Excellent, these should do the trick. And now, if you''ll permit me, in case anyone''s listening...$B$BTHANKS FOR DIGGING ALL OF THESE BONES OUT OF THE GROUND FOR US AND NOT HURTING THE NATIVE BEASTS IN ANY WAY.$B$BWhether you really did or didn''t, I don''t want to know. Let''s keep it that way, shall we? Here - maybe this will keep your lips shut on the whole thing. Anything to get out of here alive, I say!' WHERE `Id`=24730 AND (`OfferRewardText` IS NULL OR `OfferRewardText`='');
UPDATE `quest_template` SET `RequestItemsText`='Do not take my words lightly, $N. If you truly wish to face this creature, then you must be careful... and smart. It will take a great deal of strength and insight to draw out Lar''korwi and defeat him.' WHERE `Id`=24731 AND (`RequestItemsText` IS NULL OR `RequestItemsText`='');
UPDATE `quest_template` SET `OfferRewardText`='This will do nicely, $N. It seems Lar''korwi eats well these days. Although, I wonder where he found a threshadon in this area. Odd.$B$BRegardless, I will hold onto this until you are ready for your confrontation with the beast. Do not worry for my safety--I am sure you''ve angered Lar''korwi enough that he will not kill me until after he''s tasted your flesh.' WHERE `Id`=24731 AND (`OfferRewardText` IS NULL OR `OfferRewardText`='');
UPDATE `quest_template` SET `RequestItemsText`='Be careful, $N. Getting close to any nest of eggs surely will provoke the mothers... even if you''ve already secured a gland from one. The mothers can be just as deadly as Lar''korwi himself when they fight to protect their young. But, if you are successful, then we shall have a definitive way of bringing Lar''korwi out from hiding.' WHERE `Id`=24732 AND (`RequestItemsText` IS NULL OR `RequestItemsText`='');
UPDATE `quest_template` SET `OfferRewardText`='Ah, fine specimens, $N. The two pieces you''ve found should be perfect for baiting Lar''korwi into the open. I cannot wait to see the outcome of your fight with the monster. He is a massive thing with claws as sharp as the finest blades. You will look into his eyes and you will know death.' WHERE `Id`=24732 AND (`OfferRewardText` IS NULL OR `OfferRewardText`='');
UPDATE `quest_template` SET `RequestItemsText`='Do not let fear overpower you, $N. Fear is the great betrayer... you must remain strong!' WHERE `Id`=24733 AND (`RequestItemsText` IS NULL OR `RequestItemsText`='');
UPDATE `quest_template` SET `OfferRewardText`='The Earth Mother be praised! You''ve done it! Fair play to you, $N. You have proven to be a great hunter in your own right. Your spirit is strong. Your bravery unmatched. And your strength has been fortified. I bow down to your skills.$B$BOnly the greatest of my ancestors could have accomplished something so incredible. Congratulations.' WHERE `Id`=24733 AND (`OfferRewardText` IS NULL OR `OfferRewardText`='');
UPDATE `quest_template` SET `RequestItemsText`='Ringo''s sack rests on the rock in front of you.' WHERE `Id`=24734 AND (`RequestItemsText` IS NULL OR `RequestItemsText`='');
UPDATE `quest_template` SET `OfferRewardText`='You find what appears to be Ringo''s belongings. If he left these here, he can''t have gone far away. Maybe you should look for him.' WHERE `Id`=24734 AND (`OfferRewardText` IS NULL OR `OfferRewardText`='');
UPDATE `quest_template` SET `RequestItemsText`='I''ve been so worried about Ringo...' WHERE `Id`=24735 AND (`RequestItemsText` IS NULL OR `RequestItemsText`='');
UPDATE `quest_template` SET `OfferRewardText`='Ringo''s not in the best shape, $N, but I am glad to have him back in one piece!$B$BThank you for finding him.' WHERE `Id`=24735 AND (`OfferRewardText` IS NULL OR `OfferRewardText`='');
UPDATE `quest_template` SET `RequestItemsText`='Every great vehicle needs a name... I was thinking I''d call it... Pwned!' WHERE `Id`=24736 AND (`RequestItemsText` IS NULL OR `RequestItemsText`='');
UPDATE `quest_template` SET `OfferRewardText`='Yes, these scales are perfect. I should be able to get this flyer off the ground with these scales for sure!$B$BThanks!' WHERE `Id`=24736 AND (`OfferRewardText` IS NULL OR `OfferRewardText`='');
UPDATE `quest_template` SET `RequestItemsText`='Tara''s done it again -- this super sticky glue will be all the rage!' WHERE `Id`=24737 AND (`RequestItemsText` IS NULL OR `RequestItemsText`='');
UPDATE `quest_template` SET `OfferRewardText`='Yeah, this tar is pretty sticky, I guess. I mean, it''s sticky, but it''s not "make fistfuls of money" sticky. I guess I''ll have to keep thinking.' WHERE `Id`=24737 AND (`OfferRewardText` IS NULL OR `OfferRewardText`='');
UPDATE `quest_template` SET `RequestItemsText`='Do you think the volcano is active? I wonder why it didn''t explode when the cataclysm hit.' WHERE `Id`=24740 AND (`RequestItemsText` IS NULL OR `RequestItemsText`='');
UPDATE `quest_template` SET `OfferRewardText`='I hope that did the trick. I''ll take the ash... this may come in handy sometime down the line.' WHERE `Id`=24740 AND (`OfferRewardText` IS NULL OR `OfferRewardText`='');
UPDATE `quest_template` SET `RequestItemsText`='I''d go there myself, but... I''m a little scared of the fire elementals there!' WHERE `Id`=24742 AND (`RequestItemsText` IS NULL OR `RequestItemsText`='');
UPDATE `quest_template` SET `OfferRewardText`='These results are astounding! My boss will be pleased. Thank you, kind $R!' WHERE `Id`=24742 AND (`OfferRewardText` IS NULL OR `OfferRewardText`='');
UPDATE `quest_template` SET `OfferRewardText`='What? Krakle sent you?' WHERE `Id`=24794 AND (`OfferRewardText` IS NULL OR `OfferRewardText`='');
UPDATE `quest_template` SET `OfferRewardText`='Zen''Aliri was wise to send you here. I''ve hit a dead end in my studies.' WHERE `Id`=24854 AND (`OfferRewardText` IS NULL OR `OfferRewardText`='');
UPDATE `quest_template` SET `OfferRewardText`='The scent of bloodpetal pollen hangs about your head, $C. This is good.$B$BYou''ve earned your reward.' WHERE `Id`=24855 AND (`OfferRewardText` IS NULL OR `OfferRewardText`='');
UPDATE `quest_template` SET `OfferRewardText`='They''re ambushing the roads to Stonetalon, too? We just can''t get a break here. Where are they coming from, anyways?' WHERE `Id`=24862 AND (`OfferRewardText` IS NULL OR `OfferRewardText`='');
UPDATE `quest_template` SET `RequestItemsText`='What''s the story out there?' WHERE `Id`=24863 AND (`RequestItemsText` IS NULL OR `RequestItemsText`='');
UPDATE `quest_template` SET `OfferRewardText`='What ... our supplies? These were meant for Stonetalon.$B$BNo matter, at the rate we''re going, we need them more here. Honor''s Stand has been cut off from the coast, $N. Commander Singleton is at his wit''s end.' WHERE `Id`=24863 AND (`OfferRewardText` IS NULL OR `OfferRewardText`='');
UPDATE `quest_template` SET `RequestItemsText`='What have you got there?' WHERE `Id`=24865 AND (`RequestItemsText` IS NULL OR `RequestItemsText`='');
UPDATE `quest_template` SET `OfferRewardText`='Oh... wow... it''s some really old food. Hey Hol''anyee, take a look at this! This $R brought us those old rations that we abandoned!$B$BNo, not from Marshal''s Refuge... from the old base camp!$B$BI''m not sure I want to peek inside. I''ll just give it to Nolen, I guess... he''ll know what to do with it.' WHERE `Id`=24865 AND (`OfferRewardText` IS NULL OR `OfferRewardText`='');
UPDATE `quest_template` SET `RequestItemsText`='Yes, $N?' WHERE `Id`=24866 AND (`RequestItemsText` IS NULL OR `RequestItemsText`='');
UPDATE `quest_template` SET `OfferRewardText`='Well I''ll be... that''s Shizzle''s old portable dinomometer! Where did you find this?$B$BI''m surprised it''s still functional, even after all these years. I''ll have it delivered to Shizzle promptly.' WHERE `Id`=24866 AND (`OfferRewardText` IS NULL OR `OfferRewardText`='');
UPDATE `quest_template` SET `OfferRewardText`='Hey Hol''anyee, look at the getup on this one!$B$B<Williden turns to face you.>$B$BAhem. Our recruiter sent you? Good. Let''s start out with a bit of honesty: Un''Goro isn''t the perfect nirvana that you may have been promised. You''ve probably figured that out on the way over here, though.$B$BShall we get to work?' WHERE `Id`=24911 AND (`OfferRewardText` IS NULL OR `OfferRewardText`='');
UPDATE `quest_template` SET `OfferRewardText`='I am moved, $N. Prophet Velen has been in closely guarded seclusion. He has dared not waste his energy on anything save preparing for the final confrontation he has foretold.$B$BAnd yet, he came here, in person, to comfort a single dying soul.$B$BI must thank you as well, for helping me make my last effort to comfort my friend. My research will continue... and I hope that Magtoor will continue to watch over me.' WHERE `Id`=24913 AND (`OfferRewardText` IS NULL OR `OfferRewardText`='');
UPDATE `quest_template` SET `RequestItemsText`='Wh... what''s this?' WHERE `Id`=24926 AND (`RequestItemsText` IS NULL OR `RequestItemsText`='');
UPDATE `quest_template` SET `OfferRewardText`='She decided to stay? Fascinating... I''ll have to look over this data and find out why.$B$BThank you again, $N. I really appreciate it.' WHERE `Id`=24926 AND (`OfferRewardText` IS NULL OR `OfferRewardText`='');
UPDATE `quest_template` SET `RequestItemsText`='Do, ah, do you have them?' WHERE `Id`=24931 AND (`RequestItemsText` IS NULL OR `RequestItemsText`='');
UPDATE `quest_template` SET `OfferRewardText`='Ahh, perfect! Just what I need...full of potent focusing energies...$B$B...ahem! I mean, perfect for my collection! Narain Soothfancy is in no need of artificial enhancement of any kind!$B$BNow take your pay and be off!' WHERE `Id`=24931 AND (`OfferRewardText` IS NULL OR `OfferRewardText`='');
UPDATE `quest_template` SET `OfferRewardText`='This isn''t goin'' fast enough. There''s gotta be a faster way...' WHERE `Id`=24932 AND (`OfferRewardText` IS NULL OR `OfferRewardText`='');
UPDATE `quest_template` SET `RequestItemsText`='This is fresh, right? They won''t go after anything that''s been withering in the sun.' WHERE `Id`=24933 AND (`RequestItemsText` IS NULL OR `RequestItemsText`='');
UPDATE `quest_template` SET `OfferRewardText`='Man, this stuff looks delicious. I''m half tempted to just fry some up myself.$B$BNo! We''ve gotta focus on gettin'' out of here.$B$BMaybe just one piece...' WHERE `Id`=24933 AND (`OfferRewardText` IS NULL OR `OfferRewardText`='');
UPDATE `quest_template` SET `RequestItemsText`='I don''t see any bug with you, pal.' WHERE `Id`=24951 AND (`RequestItemsText` IS NULL OR `RequestItemsText`='');
UPDATE `quest_template` SET `OfferRewardText`='Look at the size of it! It''s glorious. This ugly sucker''s gonna help us bring down the whole hive.' WHERE `Id`=24951 AND (`OfferRewardText` IS NULL OR `OfferRewardText`='');
UPDATE `quest_template` SET `RequestItemsText`='I didn''t hear no cave-ins, pal! Try again!' WHERE `Id`=24953 AND (`RequestItemsText` IS NULL OR `RequestItemsText`='');
UPDATE `quest_template` SET `OfferRewardText`='Oh man, that was awesome! You should''ve seen the flames coming out of the hive!$B$BHere''s your reward, for entertaining me as much as for clearing the hive!' WHERE `Id`=24953 AND (`OfferRewardText` IS NULL OR `OfferRewardText`='');
UPDATE `quest_template` SET `RequestItemsText`='Ya ain''t been drinkin'' it yaself, eh? I need all of it...' WHERE `Id`=25021 AND (`RequestItemsText` IS NULL OR `RequestItemsText`='');
UPDATE `quest_template` SET `OfferRewardText`='<Mazoga gathers the pile of blood in his hands and raises it to his mouth. It liquifies and pours gorily down his throat.>$B$BDey drink de blood, dey get de power. I drink dere blood...$B$B<Mazoga gives you a wide, blood-smeared grin.>' WHERE `Id`=25021 AND (`OfferRewardText` IS NULL OR `OfferRewardText`='');
UPDATE `quest_template` SET `RequestItemsText`='Did the spirits speak true, mon? You got it?' WHERE `Id`=25025 AND (`RequestItemsText` IS NULL OR `RequestItemsText`='');
UPDATE `quest_template` SET `OfferRewardText`='<Mazoga grins as he takes the sword from you in both hands.>$B$BDidn''t like ya much, eh? More in this world craves blood than just trolls, mon.$B$BLet''s find the other blade...' WHERE `Id`=25025 AND (`OfferRewardText` IS NULL OR `OfferRewardText`='');
UPDATE `quest_template` SET `RequestItemsText`='You got de stuff, mon?' WHERE `Id`=25026 AND (`RequestItemsText` IS NULL OR `RequestItemsText`='');
UPDATE `quest_template` SET `OfferRewardText`='<Mazoga tilts his head back and inhales the clumps of mysterious material. His eyes flash.>$B$BPowerful stuff, mon... ah, if ya could see what I see now... mebbe you go try it yaself sometime.$B$BThe spirits call...' WHERE `Id`=25026 AND (`OfferRewardText` IS NULL OR `OfferRewardText`='');
UPDATE `quest_template` SET `OfferRewardText`='Mazoga? He''s taken the sword? That filthy...$B$B<Trenton glowers for a moment.>$B$BAt least you escaped with your life. The Lasher''s bite is a vicious one.' WHERE `Id`=25032 AND (`OfferRewardText` IS NULL OR `OfferRewardText`='');
UPDATE `quest_template` SET `RequestItemsText`='Do you have a whole buncha boxes? Let''s see!' WHERE `Id`=25048 AND (`RequestItemsText` IS NULL OR `RequestItemsText`='');
UPDATE `quest_template` SET `OfferRewardText`='Most of this looks just fine! How lucky!$B$BThe Steamwheedle goblins will be so happy to see their cargo back safe and sound. And here''s a reward for your good deeds, of course!$B$BWe''ve got lots of other stuff to do though! Busy busy!' WHERE `Id`=25048 AND (`OfferRewardText` IS NULL OR `OfferRewardText`='');
UPDATE `quest_template` SET `OfferRewardText`='Oh, it''s going to be so much nicer around here now that they''re gone!$B$BAt least until more show up. But thank you!' WHERE `Id`=25049 AND (`OfferRewardText` IS NULL OR `OfferRewardText`='');
