UPDATE `quest_template` SET `RequestItemsText`='I hope you don''t think you''re hiding any for yourself, silly! These goggles can see right through your bags.$B$BAnd your armor.' WHERE `Id`=25054 AND (`RequestItemsText` IS NULL OR `RequestItemsText`='');
UPDATE `quest_template` SET `OfferRewardText`='Fantastic! Gosh, this will make enough wire for an entire army.$B$BLucky us!' WHERE `Id`=25054 AND (`OfferRewardText` IS NULL OR `OfferRewardText`='');
