UPDATE `quest_template` SET `OfferRewardText`='I''m amazed that Soothfancy was capable of following a simple set of instructions. And ones that required him to keep his foolish mouth silenced as well.$B$BIn addition, it is honestly good to see you again, $N. Now that I''ve dropped the charade, you''ll get to see how gnomes get things done around here.' WHERE `Id`=25061 AND (`OfferRewardText` IS NULL OR `OfferRewardText`='');
