UPDATE `quest_template` SET `OfferRewardText`='<Kelsey takes the journal and gingerly flips through it.>$B$BI''m trying not to laugh. This is classic. They have no idea they''re even on Kalimdor!$B$BThese later pages though...something more significant may be occurring here.' WHERE `Id`=25062 AND (`OfferRewardText` IS NULL OR `OfferRewardText`='');
UPDATE `quest_template` SET `RequestItemsText`='Hopefully your spree of turtle destruction left it intact.' WHERE `Id`=25063 AND (`RequestItemsText` IS NULL OR `RequestItemsText`='');
UPDATE `quest_template` SET `OfferRewardText`='Well, gosh, this day just keeps getting better and better! I may actually smile.$B$BWhen you''re not looking. You''ve seen enough of that already.' WHERE `Id`=25063 AND (`OfferRewardText` IS NULL OR `OfferRewardText`='');
