UPDATE `quest_template` SET `OfferRewardText`='Thanks for the help, this was really killin'' things here. Once you start losing men, you start losing manpower. And morale. And weapons. And the magazines you loaned to that one guy.$B$BYou know how it is.' WHERE `Id`=25072 AND (`OfferRewardText` IS NULL OR `OfferRewardText`='');
UPDATE `quest_template` SET `OfferRewardText`='Marin sent you? I''m appreciative of his help.$B$BI''m here to seek out Sul''thraze. If you wish to help, speak with Mazoga...he''s been cooperative so far.' WHERE `Id`=25091 AND (`OfferRewardText` IS NULL OR `OfferRewardText`='');
