UPDATE `quest_template` SET `OfferRewardText`='Alchemists pay through the nose for these things. Sure, maybe I tell some of them they''re dragon parts, but that ain''t my problem, right?' WHERE `Id`=25111 AND (`OfferRewardText` IS NULL OR `OfferRewardText`='');
UPDATE `quest_template` SET `OfferRewardText`='Nice going, kid. Didn''t lose any fingers? Good, we can get some more work for you then.' WHERE `Id`=25112 AND (`OfferRewardText` IS NULL OR `OfferRewardText`='');
UPDATE `quest_template` SET `OfferRewardText`='Beautiful! We''ll have these puppies shined up and ready to sell in no time.' WHERE `Id`=25115 AND (`OfferRewardText` IS NULL OR `OfferRewardText`='');
UPDATE `quest_template` SET `OfferRewardText`='Hi there! The fun''s already started!' WHERE `Id`=25121 AND (`OfferRewardText` IS NULL OR `OfferRewardText`='');
UPDATE `quest_template` SET `RequestItemsText`='My patience is beginning to wear thin. I don''t have enough time to wait around for you, so kill that captain already.$B$BUm, I mean, please? Tee-hee?' WHERE `Id`=25166 AND (`RequestItemsText` IS NULL OR `RequestItemsText`='');
UPDATE `quest_template` SET `OfferRewardText`='He was controlling a sea giant? Fascinating. If we''d managed to investigate further...$B$BOh, I mean, wow, that''s totally crazy! But thank goodness he''s gone, hooray! Mister Noggenfogger will be so pleased.$B$BHere''s a nice big reward, you!' WHERE `Id`=25166 AND (`OfferRewardText` IS NULL OR `OfferRewardText`='');
