UPDATE `quest_template` SET `OfferRewardText`='Welcome back from the battle! The Twilight''s Hammer have been disgraced in the eyes of the Gordunni, and driven from Feralas.$B$BWe''ve shown the glory of the Alliance in full force today! Be proud!' WHERE `Id`=25333 AND (`OfferRewardText` IS NULL OR `OfferRewardText`='');
