UPDATE `quest_template` SET `OfferRewardText`='I''m free...finally! Oh, it feels so good to be free...$B$BOh, you saw, didn''t you?' WHERE `Id`=25368 AND (`OfferRewardText` IS NULL OR `OfferRewardText`='');
