UPDATE `quest_template` SET `OfferRewardText`='This development worries me greatly. This has happened before...' WHERE `Id`=25394 AND (`OfferRewardText` IS NULL OR `OfferRewardText`='');
UPDATE `quest_template` SET `RequestItemsText`='The tears are among the very rocks that the giants themselves rise from. There should be loose ones near the base of these large monoliths.' WHERE `Id`=25396 AND (`RequestItemsText` IS NULL OR `RequestItemsText`='');
UPDATE `quest_template` SET `OfferRewardText`='The mountain giants are precious allies of our race. We must stop this corruption before it claims any more creatures of the forest.' WHERE `Id`=25396 AND (`OfferRewardText` IS NULL OR `OfferRewardText`='');
UPDATE `quest_template` SET `OfferRewardText`='The spirits of these guardians will return in time, $N. You''ve freed them to move on in nature''s cycle.$B$BNow it falls to us to make sure that cycle is free of corruption and needless suffering.' WHERE `Id`=25397 AND (`OfferRewardText` IS NULL OR `OfferRewardText`='');
UPDATE `quest_template` SET `OfferRewardText`='Your bravery has seen us through! The Emerald Nightmare has been shut out from this land.$B$BThe fate of the dragon Taerar worries me...but there is much work still to be done. I cannot afford to dwell on it.' WHERE `Id`=25398 AND (`OfferRewardText` IS NULL OR `OfferRewardText`='');
UPDATE `quest_template` SET `OfferRewardText`='Your valor was mentioned in my briefings, $N. I commend you.' WHERE `Id`=25399 AND (`OfferRewardText` IS NULL OR `OfferRewardText`='');
