UPDATE `quest_template` SET `OfferRewardText`='Wisps have always lived in harmony with night elves, and we depend on them for many things. These little guys you sent back, for example, will be helping us with some new construction and repairs.$B$BReady for more?' WHERE `Id`=25407 AND (`OfferRewardText` IS NULL OR `OfferRewardText`='');
UPDATE `quest_template` SET `OfferRewardText`='A properly trained squadron of hippogryph riders can take on nearly any opposing force. Feathermoon Stronghold will be much safer with these noble beasts on our side.' WHERE `Id`=25409 AND (`OfferRewardText` IS NULL OR `OfferRewardText`='');
UPDATE `quest_template` SET `OfferRewardText`='They may not look it, but some treants grow to be ancient protectors. We could use a few more of those around here...' WHERE `Id`=25410 AND (`OfferRewardText` IS NULL OR `OfferRewardText`='');
