UPDATE `quest_template` SET `OfferRewardText`='This is amazing. These hieroglyphs are undoubtedly titan, but the markings below it...$B$BIf I had to hope, this is the same passage written over and over again in an entire assortment of ancient languages. We might be able to use this to decipher the hieroglyphs! If the antechamber was covered in them as you say, who knows what else we''ll learn.$B$BI''d like to grant you a fine reward, $N. We''ve made the find of the century!' WHERE `Id`=25421 AND (`OfferRewardText` IS NULL OR `OfferRewardText`='');
UPDATE `quest_template` SET `RequestItemsText`='Do you have the soil? I''m having trouble staying together...hurry...' WHERE `Id`=25422 AND (`RequestItemsText` IS NULL OR `RequestItemsText`='');
UPDATE `quest_template` SET `OfferRewardText`='Thank you! Thank you...$B$BI feel much better. With just a bit more...' WHERE `Id`=25422 AND (`OfferRewardText` IS NULL OR `OfferRewardText`='');
UPDATE `quest_template` SET `RequestItemsText`='Have you gathered it?' WHERE `Id`=25423 AND (`RequestItemsText` IS NULL OR `RequestItemsText`='');
UPDATE `quest_template` SET `OfferRewardText`='You can feel their anguish, can''t you?$B$BMy poor friends. At least we can use you to fix things...' WHERE `Id`=25423 AND (`OfferRewardText` IS NULL OR `OfferRewardText`='');
UPDATE `quest_template` SET `RequestItemsText`='The manes aren''t just for trophies. If there''s to be slaughter, we may as well not let it be a total waste.' WHERE `Id`=25426 AND (`RequestItemsText` IS NULL OR `RequestItemsText`='');
UPDATE `quest_template` SET `OfferRewardText`='Excellent work, $N. I didn''t think those gnolls would give you much trouble.' WHERE `Id`=25426 AND (`OfferRewardText` IS NULL OR `OfferRewardText`='');
UPDATE `quest_template` SET `OfferRewardText`='Perfect. Any gnolls left will be simple prey, lost in the woods.$B$BHeh...here, soldier, take your reward before I get distracted. We''ve got other threats to deal with.' WHERE `Id`=25427 AND (`OfferRewardText` IS NULL OR `OfferRewardText`='');
UPDATE `quest_template` SET `RequestItemsText`='How goes the hunt, $N? Are you here to report your success?' WHERE `Id`=25429 AND (`RequestItemsText` IS NULL OR `RequestItemsText`='');
UPDATE `quest_template` SET `OfferRewardText`='These are silithid after all...I wasn''t sure, having never seen one in person. Gilneas had its problems, but at least we didn''t have these monstrosities running around!' WHERE `Id`=25429 AND (`OfferRewardText` IS NULL OR `OfferRewardText`='');
UPDATE `quest_template` SET `OfferRewardText`='Well done, $N! You''re proving very valuable to securing this area for the Alliance.' WHERE `Id`=25431 AND (`OfferRewardText` IS NULL OR `OfferRewardText`='');
