UPDATE `quest_template` SET `OfferRewardText`='I didn''t want to scare you, but this is a grave situation. If the portal at Dream Bough was sealed, and the corruption is still spreading...' WHERE `Id`=25436 AND (`OfferRewardText` IS NULL OR `OfferRewardText`='');
UPDATE `quest_template` SET `OfferRewardText`='You''ve come.$B$BI am ashamed to ask this of you, $C, but I''ve ran from him long enough. Taerar must be stopped.' WHERE `Id`=25437 AND (`OfferRewardText` IS NULL OR `OfferRewardText`='');
UPDATE `quest_template` SET `OfferRewardText`='To be drawn into a fight between dragons...I don''t know if you''re blessed or cursed.$B$BLady Shandris has heard of all you''ve done, and has personally sent this reward for your bravery. I''m glad you came back in one piece to receive it.' WHERE `Id`=25438 AND (`OfferRewardText` IS NULL OR `OfferRewardText`='');
