UPDATE `quest_template` SET `OfferRewardText`='Good riddance to foul creatures. May the naga slither back into the sea and never return.$B$BYou''ve proven yourself on the battlefield, $N. I would ask more assistance of you in defending our lands here.' WHERE `Id`=25458 AND (`OfferRewardText` IS NULL OR `OfferRewardText`='');
UPDATE `quest_template` SET `OfferRewardText`='Good to see you here. Estulan is being...difficult. We''re going to have to deal with these ogres for Lady Shandris on our own until he decides to deal with us.' WHERE `Id`=25463 AND (`OfferRewardText` IS NULL OR `OfferRewardText`='');
UPDATE `quest_template` SET `RequestItemsText`='I had to tweak the thing to stop working on mountain giants. Even though I wasn''t the one running around zapping things, those night elves beat the copper out of me after they found those guys shrunk.' WHERE `Id`=25465 AND (`RequestItemsText` IS NULL OR `RequestItemsText`='');
UPDATE `quest_template` SET `OfferRewardText`='Splendifimous! Not only am I glad to see that you''ve returned with the residue, but also with all your major appendages intact! That is, well, there was never any danger in using the Ultra-Shrinker, now was there!$B$BI do appreciate your effort on my behalf, $N. Truly, you are a friend to goblins everywhere. Accept this as a token of my appreciation!' WHERE `Id`=25465 AND (`OfferRewardText` IS NULL OR `OfferRewardText`='');
UPDATE `quest_template` SET `RequestItemsText`='While I could bore you with the technical details of the utility behind elemental cores, I will instead tempt you to completion of this important task by offering valuable coin and prizes for doing so. Yon verily, are you finished?' WHERE `Id`=25466 AND (`RequestItemsText` IS NULL OR `RequestItemsText`='');
UPDATE `quest_template` SET `OfferRewardText`='Scrumdillyriffic! These cores will keep me working for some time. Add to that the benefit of there now being fewer elementals along the coast, and I might no longer cry myself to sleep at the prospect of having set up shop in perhaps the worst place imaginable!$B$BThank you, $N, for your efforts on my behalf. While it certainly straps me financially to do this, allow me to show you some gratitude you may understand and appreciate... loot!' WHERE `Id`=25466 AND (`OfferRewardText` IS NULL OR `OfferRewardText`='');
UPDATE `quest_template` SET `OfferRewardText`='Aren''t they adorable? The babies are even cuter.' WHERE `Id`=25468 AND (`OfferRewardText` IS NULL OR `OfferRewardText`='');
UPDATE `quest_template` SET `OfferRewardText`='Excellent!$B$B$N, you''ve helped bolster our forces here, and you''ve saved many of these forest creatures from the Horde as well. With our army now ready, Feathermoon will stand against all threats, Horde or otherwise!$B$BOn behalf of Lady Feathermoon, I''d like to award you with this weapon, fit for a Sentinel.' WHERE `Id`=25469 AND (`OfferRewardText` IS NULL OR `OfferRewardText`='');
UPDATE `quest_template` SET `RequestItemsText`='You appear to have uncovered the wreckage of... a robotic chicken? The voice from within the egg crackles to life again:$B$B"Yes, excellent work! This is indeed my homing robot, though my sensors indicate that it needs a jump start before it can fly back to Booty Bay for repairs. Go ahead and place the beacon inside the rover - the beacon will take care of the rest!"' WHERE `Id`=25475 AND (`RequestItemsText` IS NULL OR `RequestItemsText`='');
UPDATE `quest_template` SET `OfferRewardText`='You place the egg... distress beacon... inside the chicken... homing robot.$B$BHums and whirs are heard from inside the robot as it struggles to stand up. After the robot comes to life, Oglethorpe''s voice is heard once more, but now from inside the robot:$B$B"OOX-22/FE is working at least, but it needs major repairs! It is much too heavy for you to carry it... but I think I have an idea. Are you up for watching over it some more?"' WHERE `Id`=25475 AND (`OfferRewardText` IS NULL OR `OfferRewardText`='');
UPDATE `quest_template` SET `OfferRewardText`='Oh, YOU''RE the great savior of OOX-22/FE! I cannot even begin to express my thanks for your assistance! My homing robot series needs more development, but your recovery has saved me countless hours of extra rebuilding time, as well as many gold pieces in manufacture costs!$B$BPlease, take your choice of any of these items I have. Thank you again for your generous assistance $N, my robots and I are in your debt!' WHERE `Id`=25476 AND (`OfferRewardText` IS NULL OR `OfferRewardText`='');
UPDATE `quest_template` SET `OfferRewardText`='Falfindel Waywarder sent you? Good! We need your help, now!' WHERE `Id`=25481 AND (`OfferRewardText` IS NULL OR `OfferRewardText`='');
UPDATE `quest_template` SET `RequestItemsText`='Think you could take care of a few more of the Grimtotem for us first, friend?' WHERE `Id`=25486 AND (`RequestItemsText` IS NULL OR `RequestItemsText`='');
UPDATE `quest_template` SET `OfferRewardText`='A boat? Yes, you can have this last one.' WHERE `Id`=25486 AND (`OfferRewardText` IS NULL OR `OfferRewardText`='');
UPDATE `quest_template` SET `OfferRewardText`='YES?! Do you see me interrupting your fascinating argument?$B$BNo... no, please, go ahead. I''m sure that your interruption is about something very important. More important than dealing with the survival of everyone here, in fact.$B$B<Fizzle taps his foot impatiently.>' WHERE `Id`=25488 AND (`OfferRewardText` IS NULL OR `OfferRewardText`='');
UPDATE `quest_template` SET `RequestItemsText`='Is that the list of parts, finally? I''ve been waiting all day for that!' WHERE `Id`=25504 AND (`RequestItemsText` IS NULL OR `RequestItemsText`='');
UPDATE `quest_template` SET `OfferRewardText`='<Jinky eyes the list of parts and spits!>$B$BI don''t have even half of that stuff!' WHERE `Id`=25504 AND (`OfferRewardText` IS NULL OR `OfferRewardText`='');
UPDATE `quest_template` SET `OfferRewardText`='Fantastic. I might challenge you to a duel myself someday.' WHERE `Id`=25513 AND (`OfferRewardText` IS NULL OR `OfferRewardText`='');
