UPDATE `quest_template` SET `OfferRewardText`='<Kalen sighs.>$B$BWe use guns just fine, friend. CANNONS, on the other hand, I take issue with...' WHERE `Id`=25613 AND (`OfferRewardText` IS NULL OR `OfferRewardText`='');
