UPDATE `quest_template` SET `OfferRewardText`='Excellent work, $N. The gnome technology, while somewhat obnoxious, is highly effective. We should now have a clear path to Windshear Hold.' WHERE `Id`=25614 AND (`OfferRewardText` IS NULL OR `OfferRewardText`='');
UPDATE `quest_template` SET `OfferRewardText`='With the airways clear our hippogryphs will be able to move into Stonetalon freely. Well done, $N!$B$BNow on to more pressing matters. $B$BWhat you witnessed at Trueshot Point was a small sampling of the decimation left in the wake of Hellscream''s legacy. As Warchief of the Horde, Hellscream has declared Kalimdor as the Horde''s sovereign territory. All that would oppose the Horde are destroyed.$B$BWe are Kalimdor''s last line of defense. Should we fall, Kalimdor will also fall. The Horde must be stopped!' WHERE `Id`=25615 AND (`OfferRewardText` IS NULL OR `OfferRewardText`='');
UPDATE `quest_template` SET `OfferRewardText`='With the Krom''gar incinerators dealt with, the forest may be allowed to regrow. Only time can heal the wounds left by the Horde.' WHERE `Id`=25616 AND (`OfferRewardText` IS NULL OR `OfferRewardText`='');
UPDATE `quest_template` SET `OfferRewardText`='<The Gnomecorder crackles and pops with static electricity.>$B$BCome in, $N. Can you hear me? Zis iz Professor Xakxak!$B$B*POP*$B$B*CRACKLE*$B$BPERFECT! Viz ze Gnomecorder I vill be able to direct you about Stonetalon vile staying out of harmz vay!$B$BNow, onto our next order of buziness!' WHERE `Id`=25621 AND (`OfferRewardText` IS NULL OR `OfferRewardText`='');
UPDATE `quest_template` SET `OfferRewardText`='<The Gnomecorder buzzes loudly.>$B$BVonderful! As promised, VOILA, your reward!$B$BNow, I have a bit of news that you might find interesting.' WHERE `Id`=25622 AND (`OfferRewardText` IS NULL OR `OfferRewardText`='');
UPDATE `quest_template` SET `RequestItemsText`='What''s going on? You gonna get me out of here?' WHERE `Id`=25627 AND (`RequestItemsText` IS NULL OR `RequestItemsText`='');
UPDATE `quest_template` SET `OfferRewardText`='Yeah, yeah, yeah... I''m sure that your little adventure into the cave was very interesting.$B$BHow about we talk about it over drinks back on the Speedbarge once you get me out of this cage?' WHERE `Id`=25627 AND (`OfferRewardText` IS NULL OR `OfferRewardText`='');
UPDATE `quest_template` SET `OfferRewardText`='Good to see you again, $N. Thanks for the rescue in Ashenvale. Damn shame about all the gnomes we lost.$B$BYou ready to get down to business?' WHERE `Id`=25640 AND (`OfferRewardText` IS NULL OR `OfferRewardText`='');
UPDATE `quest_template` SET `RequestItemsText`='Get me those ore samples!' WHERE `Id`=25642 AND (`RequestItemsText` IS NULL OR `RequestItemsText`='');
UPDATE `quest_template` SET `OfferRewardText`='Not too much trouble, I hope. With these samples we should be able to figure out what they plan to do with the ore and the big bomb.' WHERE `Id`=25642 AND (`OfferRewardText` IS NULL OR `OfferRewardText`='');
UPDATE `quest_template` SET `OfferRewardText`='Nice job, I could hear their shrill screams from out here. You''ve turned the whole place on its head!$B$BDid you happen to find any other information about the mining operation?' WHERE `Id`=25646 AND (`OfferRewardText` IS NULL OR `OfferRewardText`='');
UPDATE `quest_template` SET `RequestItemsText`='What have you got there?' WHERE `Id`=25647 AND (`RequestItemsText` IS NULL OR `RequestItemsText`='');
UPDATE `quest_template` SET `OfferRewardText`='<Boog takes the letter from you and begins to examine it.>$B$BInteresting.$B$B<Boog smells the parchment.>$B$BHrm... Troubling...$B$B<Boog folds the paper in half and looks at you.>$B$BCan''t understand a damn thing written here - if that is writing. Could just be toilet paper. Sure smells like it.' WHERE `Id`=25647 AND (`OfferRewardText` IS NULL OR `OfferRewardText`='');
UPDATE `quest_template` SET `RequestItemsText`='What have you got there?' WHERE `Id`=25649 AND (`RequestItemsText` IS NULL OR `RequestItemsText`='');
UPDATE `quest_template` SET `OfferRewardText`='<Minx takes the letter from you and begins to read it.>$B$BUh oh...$B$B<Minx smells the parchment.>$B$BDisgusting!$B$B<Minx folds the paper in half and looks at you.>$B$BThe good news is that this isn''t toilet paper. The bad news is that the ink on this paper is a mixture of kodo poop and blood. That''s not the worst of it, though...' WHERE `Id`=25649 AND (`OfferRewardText` IS NULL OR `OfferRewardText`='');
UPDATE `quest_template` SET `RequestItemsText`='Well? What''s it say?' WHERE `Id`=25650 AND (`RequestItemsText` IS NULL OR `RequestItemsText`='');
UPDATE `quest_template` SET `OfferRewardText`='<Beads of sweat roll down Boog''s overly large forehead as he reads the translated letter.>$B$BThis is bad. Really, really bad. You have to warn Lord Fallowmere at Windshear Hold.$B$BWhat in the... It''s MOVING! The goblin balloon is taking off! We''re too late!' WHERE `Id`=25650 AND (`OfferRewardText` IS NULL OR `OfferRewardText`='');
UPDATE `quest_template` SET `OfferRewardText`='Amazing story, lad. I''d have never believed you had I not seen it with my own eyes. You did enough damage to that balloon to make those fiends pull back! Alas, the threat is far from over. We have only delayed the attack. There is much work to do if we are to stop the Horde from destroying Stonetalon!' WHERE `Id`=25652 AND (`OfferRewardText` IS NULL OR `OfferRewardText`='');
UPDATE `quest_template` SET `RequestItemsText`='We must not tolerate the infestation of our ancestor''s ruins by the harpies.' WHERE `Id`=25654 AND (`RequestItemsText` IS NULL OR `RequestItemsText`='');
UPDATE `quest_template` SET `OfferRewardText`='These lands will finally be free of the foulness of the harpies. I cannot thank you enough.' WHERE `Id`=25654 AND (`OfferRewardText` IS NULL OR `OfferRewardText`='');
UPDATE `quest_template` SET `OfferRewardText`='What ya be wantin''? Oh no you don''t. I can see ya got Tony''s spirit with ya, and I want nothin'' to do with it!' WHERE `Id`=25660 AND (`OfferRewardText` IS NULL OR `OfferRewardText`='');
UPDATE `quest_template` SET `RequestItemsText`='A fresh heart, lungs, an'' liver be what we needin''. The ones from his cap''ns will have ta do though they all be likely picked.' WHERE `Id`=25661 AND (`RequestItemsText` IS NULL OR `RequestItemsText`='');
UPDATE `quest_template` SET `OfferRewardText`='<Ajamon makes a face at the state of the organs.>$B$BThey''s gonna have ta do. It not be like he had many friends. Ain''t that right, Two-Tusk?' WHERE `Id`=25661 AND (`OfferRewardText` IS NULL OR `OfferRewardText`='');
UPDATE `quest_template` SET `RequestItemsText`='My captor holds the key to this cage.' WHERE `Id`=25662 AND (`RequestItemsText` IS NULL OR `RequestItemsText`='');
UPDATE `quest_template` SET `OfferRewardText`='We don''t have much time. To get me out of here you are going to have to take out Warlord Roktrog. He holds the key to this prison.' WHERE `Id`=25662 AND (`OfferRewardText` IS NULL OR `OfferRewardText`='');
UPDATE `quest_template` SET `OfferRewardText`='A hero thwarted their plans to destroy Windshear Hold, eh? That hero was you, $N. You are the pride of the Alliance!$B$BIt seems that you have bought us a little bit of time. I must plan for the battle that lies ahead of us. Seek out the other inhabitants of Windshear Hold and lend them your assistance. I will call for you when I am ready to initiate our defensive strategy.' WHERE `Id`=25669 AND (`OfferRewardText` IS NULL OR `OfferRewardText`='');
UPDATE `quest_template` SET `OfferRewardText`='Good. Their blood is on Hellscream''s hands. Send enough of them back to Orgrimmar in a body bag and the populace of the Horde might react.$B$B<Lord Fallowmere laughs.>$B$BWho am I kidding? They''re monsters!' WHERE `Id`=25671 AND (`OfferRewardText` IS NULL OR `OfferRewardText`='');
UPDATE `quest_template` SET `RequestItemsText`='Ya gots to get me lotsa those carcasses, mon! We not be rid of his foolish spirit if ya don''t!' WHERE `Id`=25672 AND (`RequestItemsText` IS NULL OR `RequestItemsText`='');
UPDATE `quest_template` SET `OfferRewardText`='Oh, that''s disgustin''!$B$BWe almost there, mon. Just need ta do one more ting!' WHERE `Id`=25672 AND (`OfferRewardText` IS NULL OR `OfferRewardText`='');
UPDATE `quest_template` SET `RequestItemsText`='Mr. P is so sad. We need to make him happy!' WHERE `Id`=25673 AND (`RequestItemsText` IS NULL OR `RequestItemsText`='');
UPDATE `quest_template` SET `OfferRewardText`='<Alice claps excitedly.>$B$BMr. P you''re gonna be ok! Hooray!$B$B<Alice expertly places all of the parts you collected into Big Papa.>$B$BOh, Mr. P! I knew it!' WHERE `Id`=25673 AND (`OfferRewardText` IS NULL OR `OfferRewardText`='');
UPDATE `quest_template` SET `RequestItemsText`='Ya gotta use the stick on Tirth''s corpse if ya gonna help, $N.' WHERE `Id`=25704 AND (`RequestItemsText` IS NULL OR `RequestItemsText`='');
UPDATE `quest_template` SET `OfferRewardText`='Now we gonna bring Tony Two-Tusk back ta life. You both ready, mon?' WHERE `Id`=25704 AND (`OfferRewardText` IS NULL OR `OfferRewardText`='');
UPDATE `quest_template` SET `OfferRewardText`='<Lord Fallowmere coughs.>$B$BThis is awkward...$B$BGood job out there with the robot. You caught me a little off guard. I didn''t realize the little girl was so...$B$B<Lord Fallowmere points to his temple and twirls his finger around.>$B$BSpecial...$B$BWell, whatever gets the job done, right? Am I right?$B$BProbably.$B$BHave some ice cream.' WHERE `Id`=25728 AND (`OfferRewardText` IS NULL OR `OfferRewardText`='');
UPDATE `quest_template` SET `OfferRewardText`='<The Gnomecorder buzzes loudly.>$B$BVonderful! That''s von more name I can scratch off of my list!$B$BI vill be in touch.$B$BXakxak, out!' WHERE `Id`=25729 AND (`OfferRewardText` IS NULL OR `OfferRewardText`='');
UPDATE `quest_template` SET `RequestItemsText`='You kill the beast?' WHERE `Id`=25730 AND (`RequestItemsText` IS NULL OR `RequestItemsText`='');
UPDATE `quest_template` SET `OfferRewardText`='Well I''ll be a monkey''s uncle. You actually got the beast, eh? Well, a deal''s a deal! Here''s your reward!' WHERE `Id`=25730 AND (`OfferRewardText` IS NULL OR `OfferRewardText`='');
UPDATE `quest_template` SET `OfferRewardText`='<Captain Kosak forces a smile at you.>$B$BDon''t worry about me. Should be ok now that big hero killed the spider queen.$B$BCan get reinforcements through safely now.' WHERE `Id`=25739 AND (`OfferRewardText` IS NULL OR `OfferRewardText`='');
UPDATE `quest_template` SET `RequestItemsText`='Have you recovered the venom sacs I requested?' WHERE `Id`=25741 AND (`RequestItemsText` IS NULL OR `RequestItemsText`='');
UPDATE `quest_template` SET `OfferRewardText`='This will keep us stocked on anti-venom for the foreseeable future. Thank you, $N!' WHERE `Id`=25741 AND (`OfferRewardText` IS NULL OR `OfferRewardText`='');
UPDATE `quest_template` SET `OfferRewardText`='<Crazzle gets a gleam in his eye.>$B$BI''ve got Kravel Koalbeard up there talking to one of their chiefs, but now that you''re here, we''ll have the rights to pump up their oil in no time!' WHERE `Id`=25744 AND (`OfferRewardText` IS NULL OR `OfferRewardText`='');
UPDATE `quest_template` SET `RequestItemsText`='Do you have the Horde''s proposal? What are they offering for the drilling rights?' WHERE `Id`=25756 AND (`RequestItemsText` IS NULL OR `RequestItemsText`='');
UPDATE `quest_template` SET `OfferRewardText`='What?! How''d they get that much gold to offer?$B$BWe don''t have that kind of money!' WHERE `Id`=25756 AND (`OfferRewardText` IS NULL OR `OfferRewardText`='');
UPDATE `quest_template` SET `RequestItemsText`='You have the Sacred Flame? Do not speak to me unless you do, $R!' WHERE `Id`=25762 AND (`RequestItemsText` IS NULL OR `RequestItemsText`='');
UPDATE `quest_template` SET `OfferRewardText`='You did this favor to ingratiate yourself with me, but I will not sing your praises.$B$BI know what is to come. Where the sea failed, the great air spirit will strike you and your people down for your many transgressions against the elements.$B$BBegone from my sight!' WHERE `Id`=25762 AND (`OfferRewardText` IS NULL OR `OfferRewardText`='');
UPDATE `quest_template` SET `OfferRewardText`='Kosak sent you, eh? Surprising. I thought for sure that he''d be dead by now.$B$BWell if you made it past the blockade then you definitely have something that we can use.$B$BNow, do you have any news of the Horde? What are they doing? Where are they going? Tell me everything.' WHERE `Id`=25765 AND (`OfferRewardText` IS NULL OR `OfferRewardText`='');
UPDATE `quest_template` SET `OfferRewardText`='I assure you, simpleton, the spirits you captured are at rest. Do not let their protests move you.' WHERE `Id`=25766 AND (`OfferRewardText` IS NULL OR `OfferRewardText`='');
UPDATE `quest_template` SET `RequestItemsText`='Have you recovered the ancient relics?' WHERE `Id`=25767 AND (`RequestItemsText` IS NULL OR `RequestItemsText`='');
UPDATE `quest_template` SET `OfferRewardText`='Wonderful! Arcanist Valdurian will be most pleased.' WHERE `Id`=25767 AND (`OfferRewardText` IS NULL OR `OfferRewardText`='');
UPDATE `quest_template` SET `OfferRewardText`='I''m assuming you saw the Krom''gar hot air balloon on your way here. If not, get your eyes checked. It''s hovering directly over the oil platform.' WHERE `Id`=25768 AND (`OfferRewardText` IS NULL OR `OfferRewardText`='');
UPDATE `quest_template` SET `OfferRewardText`='Good to see you again, $N. I have some news from Mirkfallon Lake.' WHERE `Id`=25769 AND (`OfferRewardText` IS NULL OR `OfferRewardText`='');
UPDATE `quest_template` SET `RequestItemsText`='Once you return with enough of that pyrite, we''ll give it a once over with a paint brush, pile it all up on a pallet, and send you back up with it to the chieftain.' WHERE `Id`=25774 AND (`RequestItemsText` IS NULL OR `RequestItemsText`='');
UPDATE `quest_template` SET `OfferRewardText`='Genius! Now, where''s that gold paint? I know it''s around here somewhere.' WHERE `Id`=25774 AND (`OfferRewardText` IS NULL OR `OfferRewardText`='');
UPDATE `quest_template` SET `RequestItemsText`='What''s this? That is a lot of gold you have there.' WHERE `Id`=25778 AND (`RequestItemsText` IS NULL OR `RequestItemsText`='');
UPDATE `quest_template` SET `OfferRewardText`='Just put it down on the ground, $R.' WHERE `Id`=25778 AND (`OfferRewardText` IS NULL OR `OfferRewardText`='');
UPDATE `quest_template` SET `OfferRewardText`='THEY WHAT?!' WHERE `Id`=25790 AND (`OfferRewardText` IS NULL OR `OfferRewardText`='');
UPDATE `quest_template` SET `OfferRewardText`='Seal it off? That''s gonna take some work, friend.' WHERE `Id`=25793 AND (`OfferRewardText` IS NULL OR `OfferRewardText`='');
UPDATE `quest_template` SET `OfferRewardText`='That''ll teach them. You''ve softened the Splithoof up enough that we should be able to govern them now with a minimal guard presence from the Speedbarge.$B$BThat is, once we''ve dealt with their supposed air elemental leader.' WHERE `Id`=25796 AND (`OfferRewardText` IS NULL OR `OfferRewardText`='');
UPDATE `quest_template` SET `OfferRewardText`='Oil! Black gold! Tanaris Tea!$B$BWe''re rich! We just have to clear out the remaining pesky centaur. I''m sure with all the money we''re going to make, we can relocate them to some other bluff.' WHERE `Id`=25798 AND (`OfferRewardText` IS NULL OR `OfferRewardText`='');
UPDATE `quest_template` SET `RequestItemsText`='Oh so you are alive.' WHERE `Id`=25808 AND (`RequestItemsText` IS NULL OR `RequestItemsText`='');
UPDATE `quest_template` SET `OfferRewardText`='Nicely done, $N! You worked the mines like a pro. Now how about returning my goggles.' WHERE `Id`=25808 AND (`OfferRewardText` IS NULL OR `OfferRewardText`='');
UPDATE `quest_template` SET `OfferRewardText`='Thank the Light! You truly are a righteous instrument of power! The Alliance is lucky to you have, $N.' WHERE `Id`=25809 AND (`OfferRewardText` IS NULL OR `OfferRewardText`='');
UPDATE `quest_template` SET `OfferRewardText`='Here goes nothin''!' WHERE `Id`=25811 AND (`OfferRewardText` IS NULL OR `OfferRewardText`='');
UPDATE `quest_template` SET `OfferRewardText`='Well then, let''s see them get any kind of magical hocus pocus air support now when we take over!' WHERE `Id`=25813 AND (`OfferRewardText` IS NULL OR `OfferRewardText`='');
UPDATE `quest_template` SET `OfferRewardText`='I knew that you''d be a special snowflake when I first set my eyes upon you, $N. So special, in fact, that I''d trust no one else here with what I''m about to ask of you.' WHERE `Id`=25821 AND (`OfferRewardText` IS NULL OR `OfferRewardText`='');
UPDATE `quest_template` SET `RequestItemsText`='Have you gathered the armaments of war?' WHERE `Id`=25822 AND (`RequestItemsText` IS NULL OR `RequestItemsText`='');
UPDATE `quest_template` SET `OfferRewardText`='This should be enough to supply a hundred Grimtotem! Now to present the weaponry to their chieftain.' WHERE `Id`=25822 AND (`OfferRewardText` IS NULL OR `OfferRewardText`='');
UPDATE `quest_template` SET `OfferRewardText`='I will call for the infantry to move in and clear up whatever might be left over. If only we had ten-thousand more like you, $N!' WHERE `Id`=25823 AND (`OfferRewardText` IS NULL OR `OfferRewardText`='');
UPDATE `quest_template` SET `RequestItemsText`='What''s this? Is that oil?!' WHERE `Id`=25825 AND (`RequestItemsText` IS NULL OR `RequestItemsText`='');
UPDATE `quest_template` SET `OfferRewardText`='It is oil! You''re really proving yourself to be invaluable, $N!$B$BToo bad I''m going to have to send you off now.' WHERE `Id`=25825 AND (`OfferRewardText` IS NULL OR `OfferRewardText`='');
UPDATE `quest_template` SET `OfferRewardText`='The name be "Cookie," lad: greatest cook ''cross Azeroth. Now the Commander''s told me what we be needin'' to do. To gain audience with the Grimtotem chief we''re gonna have to cook up the finest of tauren cuisine.$B$BYe get me the ingredients and I''ll put together an offerin'' no tauren could refuse. Not even a grim tauren or whatever them things be.' WHERE `Id`=25834 AND (`OfferRewardText` IS NULL OR `OfferRewardText`='');
UPDATE `quest_template` SET `OfferRewardText`='I''m glad that Fizzle finally sent you here. We''re helping the tauren to retake Freewind Post and push back the Grimtotem.' WHERE `Id`=25835 AND (`OfferRewardText` IS NULL OR `OfferRewardText`='');
UPDATE `quest_template` SET `RequestItemsText`='This ramlette ain''t gonna make itself!' WHERE `Id`=25837 AND (`RequestItemsText` IS NULL OR `RequestItemsText`='');
UPDATE `quest_template` SET `OfferRewardText`='Stand back, $N, there''s about to be a flavor explosion and I wouldn''t want ya gettin'' hurt.' WHERE `Id`=25837 AND (`OfferRewardText` IS NULL OR `OfferRewardText`='');
UPDATE `quest_template` SET `RequestItemsText`='<Ton Window sniffs at the air and raises his left hand.>$B$BYou have brought something for us?' WHERE `Id`=25844 AND (`RequestItemsText` IS NULL OR `RequestItemsText`='');
UPDATE `quest_template` SET `OfferRewardText`='<Ton and his bodyguards scarf down the meaty offering.>$B$BThis... this is the greatest thing I have ever tasted. You may prove to be a valuable ally, but before the Grimtotem agree to work with the Alliance, you must agree to our terms. I will now give to you those terms as told to me by my leader. Take them back to your commander and see if he accepts.' WHERE `Id`=25844 AND (`OfferRewardText` IS NULL OR `OfferRewardText`='');
UPDATE `quest_template` SET `RequestItemsText`='Well???' WHERE `Id`=25845 AND (`RequestItemsText` IS NULL OR `RequestItemsText`='');
UPDATE `quest_template` SET `OfferRewardText`='Weapons, eh?$B$B<Force Commander Valen sighs.>$B$BI''m about to make an executive decision here, $N. Let''s hope this pays off, else King Wrynn will have my head!' WHERE `Id`=25845 AND (`OfferRewardText` IS NULL OR `OfferRewardText`='');
UPDATE `quest_template` SET `RequestItemsText`='Do you have the weapons?' WHERE `Id`=25846 AND (`RequestItemsText` IS NULL OR `RequestItemsText`='');
UPDATE `quest_template` SET `OfferRewardText`='These are fine weapons! Powerful steel! My warriors will be unstoppable armed with such weaponry. Magatha smiles down upon you, $N.$B$BThere is but one thing I ask of you, perhaps two.' WHERE `Id`=25846 AND (`OfferRewardText` IS NULL OR `OfferRewardText`='');
UPDATE `quest_template` SET `RequestItemsText`='Have you armed the Grimtotem?' WHERE `Id`=25847 AND (`RequestItemsText` IS NULL OR `RequestItemsText`='');
UPDATE `quest_template` SET `OfferRewardText`='The fight is far from over, $N. The Horde generals still live...' WHERE `Id`=25847 AND (`OfferRewardText` IS NULL OR `OfferRewardText`='');
UPDATE `quest_template` SET `RequestItemsText`='Are the generals dead?' WHERE `Id`=25848 AND (`RequestItemsText` IS NULL OR `RequestItemsText`='');
UPDATE `quest_template` SET `OfferRewardText`='<Grundig crushes the insignia in his massive fist.>$B$BYes, ally, you have done it! It will take Hellscream weeks to recover from this blow. Southern Stonetalon belongs to the Grimtotem... and the Alliance, of course.' WHERE `Id`=25848 AND (`OfferRewardText` IS NULL OR `OfferRewardText`='');
UPDATE `quest_template` SET `OfferRewardText`='Outstanding work, $N! Now our forces only need to worry about the Horde as they enter Stonetalon.' WHERE `Id`=25851 AND (`OfferRewardText` IS NULL OR `OfferRewardText`='');
UPDATE `quest_template` SET `OfferRewardText`='You say the Grimtotem are no longer a threat? That''s great, but we''ve got Horde all up our keesters!' WHERE `Id`=25852 AND (`OfferRewardText` IS NULL OR `OfferRewardText`='');
UPDATE `quest_template` SET `OfferRewardText`='Grim business, that.<Quentin coughs.>$B$BNo pun intended.' WHERE `Id`=25869 AND (`OfferRewardText` IS NULL OR `OfferRewardText`='');
UPDATE `quest_template` SET `OfferRewardText`='Thank you for freeing her, $N. Those Grimtotem monsters would have killed her in cold blood.' WHERE `Id`=25871 AND (`OfferRewardText` IS NULL OR `OfferRewardText`='');
UPDATE `quest_template` SET `RequestItemsText`='What''s this, $C?' WHERE `Id`=25873 AND (`RequestItemsText` IS NULL OR `RequestItemsText`='');
UPDATE `quest_template` SET `OfferRewardText`='A traitor amongst the tauren?$B$BI''ve never heard of such a thing. Clan rivalries and warfare are one thing, but killing your own in cold blood.$B$B<Quentin shakes his head in disbelief.>' WHERE `Id`=25873 AND (`OfferRewardText` IS NULL OR `OfferRewardText`='');
UPDATE `quest_template` SET `OfferRewardText`='Get in here and hug a wall! I can''t risk blowing my cover!' WHERE `Id`=25875 AND (`OfferRewardText` IS NULL OR `OfferRewardText`='');
UPDATE `quest_template` SET `RequestItemsText`='Did you recover the log book?' WHERE `Id`=25876 AND (`RequestItemsText` IS NULL OR `RequestItemsText`='');
UPDATE `quest_template` SET `OfferRewardText`='OH NO! They plan to "test" the bomb at Thal''darah Grove! That''s the school for young druids located in the heart of Battlescar Valley. You''ve got to return to Barus with this information! Master Thal''darah must be warned!' WHERE `Id`=25876 AND (`OfferRewardText` IS NULL OR `OfferRewardText`='');
UPDATE `quest_template` SET `OfferRewardText`='Blasted Horde! I''ve got friends at that grove. Hopefully you know how to ride a hippogryph. We''ve got to get you to Master Thal''darah at the overlook immediately!' WHERE `Id`=25877 AND (`OfferRewardText` IS NULL OR `OfferRewardText`='');
UPDATE `quest_template` SET `OfferRewardText`='I could see the explosions from here, $N! The Horde won''t be refueling from Mirkfallon anymore, thanks to you!' WHERE `Id`=25878 AND (`OfferRewardText` IS NULL OR `OfferRewardText`='');
UPDATE `quest_template` SET `OfferRewardText`='Slowly, but surely, we pick away at the Horde''s numbers. They won''t have a leg to stand on when this war really opens up.' WHERE `Id`=25879 AND (`OfferRewardText` IS NULL OR `OfferRewardText`='');
UPDATE `quest_template` SET `OfferRewardText`='These are dire times, indeed, $N. Our outpost in Stonetalon Peak has been overrun by fiendish creatures from the depths and the Horde seeks to destroy us. We need a hero, $N; a soldier of the Alliance strong enough to guide us through these trying times.' WHERE `Id`=25880 AND (`OfferRewardText` IS NULL OR `OfferRewardText`='');
UPDATE `quest_template` SET `RequestItemsText`='Use the whistle to call for my hippogryph, $N.' WHERE `Id`=25889 AND (`RequestItemsText` IS NULL OR `RequestItemsText`='');
UPDATE `quest_template` SET `OfferRewardText`='Praise you, $N. The hero we have been searching for has finally arrived, and not a moment too soon.' WHERE `Id`=25889 AND (`OfferRewardText` IS NULL OR `OfferRewardText`='');
UPDATE `quest_template` SET `OfferRewardText`='Do you know why the Horde destroys? The Horde destroys because they cannot comprehend beauty. They fear it and that which they fear they must destroy. Why else would they destroy Thal''darah Grove?$B$BTogether, we will make them understand. They will know that what they do comes at a great cost.' WHERE `Id`=25891 AND (`OfferRewardText` IS NULL OR `OfferRewardText`='');
UPDATE `quest_template` SET `RequestItemsText`='Have you found my sketch book?' WHERE `Id`=25912 AND (`RequestItemsText` IS NULL OR `RequestItemsText`='');
UPDATE `quest_template` SET `OfferRewardText`='You''ve found it! Elune bless you, child! Perhaps this book will give me the strength to carry on.' WHERE `Id`=25912 AND (`OfferRewardText` IS NULL OR `OfferRewardText`='');
UPDATE `quest_template` SET `RequestItemsText`='Recover the sentinel''s glaives, $N. Each glaive is unique to a sentinel.' WHERE `Id`=25913 AND (`RequestItemsText` IS NULL OR `RequestItemsText`='');
UPDATE `quest_template` SET `OfferRewardText`='Thank you, $N. Each glaive has the name of the sentinel it belonged to imprinted upon its blade. We can now send word to their families and put their souls to rest.' WHERE `Id`=25913 AND (`OfferRewardText` IS NULL OR `OfferRewardText`='');
UPDATE `quest_template` SET `OfferRewardText`='I''m afraid that the death of Harbinger Aph''lass has not ceased the tendril attacks. You''ve done all that you can, $N, and for that I thank you.' WHERE `Id`=25914 AND (`OfferRewardText` IS NULL OR `OfferRewardText`='');
UPDATE `quest_template` SET `OfferRewardText`='We witnessed the detonation of the bomb. Terrible, terrible destruction... Farwatcher Glen, for better or for worse, is still intact. Unfortunately we''ve nowhere to run.' WHERE `Id`=25925 AND (`OfferRewardText` IS NULL OR `OfferRewardText`='');
UPDATE `quest_template` SET `OfferRewardText`='<The Gnomecorder crackles with energy.>$B$BI say, are you there, $N? It would appear that you are in the center of a dragon''s lair.' WHERE `Id`=25930 AND (`OfferRewardText` IS NULL OR `OfferRewardText`='');
UPDATE `quest_template` SET `OfferRewardText`='A smashing success! Perhaps only a minor victory against the brood of Deathwing, but a victory nonetheless!' WHERE `Id`=25931 AND (`OfferRewardText` IS NULL OR `OfferRewardText`='');
UPDATE `quest_template` SET `RequestItemsText`='Have you recovered the blazing heart of fire?' WHERE `Id`=25934 AND (`RequestItemsText` IS NULL OR `RequestItemsText`='');
UPDATE `quest_template` SET `OfferRewardText`='Excellent. This will allow me to finish my last task and hopefully gain the form of the wolf!$B$B<Salsbury howls.>' WHERE `Id`=25934 AND (`OfferRewardText` IS NULL OR `OfferRewardText`='');
UPDATE `quest_template` SET `RequestItemsText`='Hurry, $N, the pups are hungry!' WHERE `Id`=25935 AND (`RequestItemsText` IS NULL OR `RequestItemsText`='');
UPDATE `quest_template` SET `OfferRewardText`='Excellent. The dogs will be well fed and ready to defend our outpost for weeks!' WHERE `Id`=25935 AND (`OfferRewardText` IS NULL OR `OfferRewardText`='');
UPDATE `quest_template` SET `OfferRewardText`='Did the sentinels send you? Thank Elune. We need everyone we can get.' WHERE `Id`=26383 AND (`OfferRewardText` IS NULL OR `OfferRewardText`='');
UPDATE `quest_template` SET `RequestItemsText`='You''re back... and without him...' WHERE `Id`=26401 AND (`RequestItemsText` IS NULL OR `RequestItemsText`='');
UPDATE `quest_template` SET `OfferRewardText`='How horrible... for someone so young and full of promise to fall to demons!$B$BI beg your forgiveness for sending you into danger as well, $N. I hope you don''t cross paths with that demoness again...' WHERE `Id`=26401 AND (`OfferRewardText` IS NULL OR `OfferRewardText`='');
UPDATE `quest_template` SET `OfferRewardText`='Telaron has already sent word of you, $N. I''m interested in seeing if you''re half as skilled as he claims.$B$BI am fighting a war on multiple fronts, while keeping our currently held areas properly defended, as well as overseeing the instruction of our youngest sentinels. If you''re a decent fighter, there will be plenty for you to do.' WHERE `Id`=26402 AND (`OfferRewardText` IS NULL OR `OfferRewardText`='');
UPDATE `quest_template` SET `OfferRewardText`='Good to see a new face around here!$B$BThe forest crawls with Horde, but my assignment requires that I keep this outpost safe. I could really use someone who might be up for a good fight.' WHERE `Id`=26408 AND (`OfferRewardText` IS NULL OR `OfferRewardText`='');
UPDATE `quest_template` SET `RequestItemsText`='What do you have there, sir?' WHERE `Id`=26443 AND (`RequestItemsText` IS NULL OR `RequestItemsText`='');
UPDATE `quest_template` SET `OfferRewardText`='By the Seven Crystals of Ata''mal, this cannot be! They plan to attack Forest Song?!$B$BNot on my watch!$B$B<Vindicator Vedaar crumples the demon-scrawled plans in his fist.>$B$BNo. We will not allow this to happen!' WHERE `Id`=26443 AND (`OfferRewardText` IS NULL OR `OfferRewardText`='');
UPDATE `quest_template` SET `OfferRewardText`='You have my respect and thanks, $C. Perhaps we''ll be able to create a new home here without having to worry about the Burning Legion yet again.' WHERE `Id`=26444 AND (`OfferRewardText` IS NULL OR `OfferRewardText`='');
UPDATE `quest_template` SET `RequestItemsText`='Our night elf scouts report that preparations for the attack are almost complete. Those dreadlords must die soon, $N!' WHERE `Id`=26445 AND (`RequestItemsText` IS NULL OR `RequestItemsText`='');
UPDATE `quest_template` SET `OfferRewardText`='Never again will the Burning Legion threaten Ashenvale! You have delivered us from a fight we very likely would have lost, $C.$B$BI give you thanks, $N, and the deepest gratitude of the Hand of Argus. It honors me to have you at our side!' WHERE `Id`=26445 AND (`OfferRewardText` IS NULL OR `OfferRewardText`='');
UPDATE `quest_template` SET `RequestItemsText`='Surely you have not yet planted all of my seeds?' WHERE `Id`=26446 AND (`RequestItemsText` IS NULL OR `RequestItemsText`='');
UPDATE `quest_template` SET `OfferRewardText`='Good. Though it may take a great deal of your years for the seedlings to grow into ancients, in the fullness of time they will aid us in our fight against all of the enemies of Ashenvale.' WHERE `Id`=26446 AND (`OfferRewardText` IS NULL OR `OfferRewardText`='');
UPDATE `quest_template` SET `RequestItemsText`='<The ancient creaks as it turns toward you.>$B$BArchitect Nemos said that you might be bringing wood salvaged from befouled Satyrnaar.' WHERE `Id`=26454 AND (`RequestItemsText` IS NULL OR `RequestItemsText`='');
UPDATE `quest_template` SET `OfferRewardText`='Wood warped by foul demonic magic is of no use to the draenei at Forest Song. Nothing sound can be built with it, but I shall purify it and return it in good time to Architect Nemos and his people for their use.$B$BSome good will come from this tragedy, after all.' WHERE `Id`=26454 AND (`OfferRewardText` IS NULL OR `OfferRewardText`='');
UPDATE `quest_template` SET `RequestItemsText`='Can you feel it, $N, the touch of corruption upon the wind? If we do nothing, it will continue to advance. That is why I seek the Chalice of Elune. Were you able to find it?' WHERE `Id`=26455 AND (`RequestItemsText` IS NULL OR `RequestItemsText`='');
UPDATE `quest_template` SET `OfferRewardText`='Excellent work, $N. There is certainly a latent power here, one that not even constant exposure to the corruption of the satyr can dim.$B$BDo you see how it still shines, after all these years?' WHERE `Id`=26455 AND (`OfferRewardText` IS NULL OR `OfferRewardText`='');
UPDATE `quest_template` SET `RequestItemsText`='What''s that you have there, $C?' WHERE `Id`=26456 AND (`RequestItemsText` IS NULL OR `RequestItemsText`='');
UPDATE `quest_template` SET `OfferRewardText`='Thank you for delivering this report, $C. From what Sentinel Melyria writes, it seems our worst fears have come to pass. With each advance we make, the Horde appears more determined to do as much damage as possible.$B$BWe can''t afford to back down; the fate of our ancestral lands hangs in the balance. With more people like you on the frontlines, I''m certain we could triumph.$B$BWill you join our fight? A new front has just opened in Warsong Gulch to the south.' WHERE `Id`=26456 AND (`OfferRewardText` IS NULL OR `OfferRewardText`='');
UPDATE `quest_template` SET `OfferRewardText`='At last we have sent a message that the orcs won''t dare ignore. Any overseer or foreman who sets foot within the camp to replace Gorthak will feel my wrath!$B$BWe must press our advantage, $N, and never rest until the Warsong Lumber Camp is a distant memory and a glade of trees stands upon that ground.$B$BNow what was this about explosives...?' WHERE `Id`=26457 AND (`OfferRewardText` IS NULL OR `OfferRewardText`='');
UPDATE `quest_template` SET `OfferRewardText`='Teronis'' body lies broken atop the small rise next to the Keeper.$B$BDeep slashes crisscross his corpse.' WHERE `Id`=26463 AND (`OfferRewardText` IS NULL OR `OfferRewardText`='');
UPDATE `quest_template` SET `RequestItemsText`='Ah, welcome back, $N.' WHERE `Id`=26464 AND (`RequestItemsText` IS NULL OR `RequestItemsText`='');
UPDATE `quest_template` SET `OfferRewardText`='This is terrible, $N. Teronis is dead?!$B$BThe time for mourning will come, but for now we must focus our efforts. I will send some of the Sentinels to recover Teronis'' body and to assist the keeper.$B$BYou have the gem that Teronis was seeking? It must be delivered to Astranaar.' WHERE `Id`=26464 AND (`OfferRewardText` IS NULL OR `OfferRewardText`='');
UPDATE `quest_template` SET `RequestItemsText`='Have you found many statuettes, $N?' WHERE `Id`=26465 AND (`RequestItemsText` IS NULL OR `RequestItemsText`='');
UPDATE `quest_template` SET `OfferRewardText`='That''s quite a few that you have found! Thank you, $N!$B$BThe old city of Zoram holds many secrets, and these statuettes may be the key to many of them.' WHERE `Id`=26465 AND (`OfferRewardText` IS NULL OR `OfferRewardText`='');
UPDATE `quest_template` SET `RequestItemsText`='It is said that the Ring of Zoram is the key to any lock within the city. Do you have it, $N?' WHERE `Id`=26466 AND (`RequestItemsText` IS NULL OR `RequestItemsText`='');
UPDATE `quest_template` SET `OfferRewardText`='You found the ring! Thank you, $N.$B$BPlease take this as payment, and know that your deeds today will remain forever in my memory.' WHERE `Id`=26466 AND (`OfferRewardText` IS NULL OR `OfferRewardText`='');
UPDATE `quest_template` SET `OfferRewardText`='Judging by the gaping wound in her side, Anilia is on the verge of death.' WHERE `Id`=26467 AND (`OfferRewardText` IS NULL OR `OfferRewardText`='');
UPDATE `quest_template` SET `RequestItemsText`='Have you found them? What did Anilia say? Where is she?' WHERE `Id`=26468 AND (`RequestItemsText` IS NULL OR `RequestItemsText`='');
UPDATE `quest_template` SET `OfferRewardText`='Anilia died? No... that can''t be! It was just yesterday that we were running and playing together in the woods.$B$BI guess those days are over...' WHERE `Id`=26468 AND (`OfferRewardText` IS NULL OR `OfferRewardText`='');
UPDATE `quest_template` SET `RequestItemsText`='Please, help me avenge Anilia''s death.' WHERE `Id`=26469 AND (`RequestItemsText` IS NULL OR `RequestItemsText`='');
UPDATE `quest_template` SET `OfferRewardText`='Thank you, kind $R. My sister''s spirit is gladdened by your efforts.' WHERE `Id`=26469 AND (`OfferRewardText` IS NULL OR `OfferRewardText`='');
UPDATE `quest_template` SET `OfferRewardText`='Well done, $N! With the befouled elemental numbers thinned and Tideress put back into the lake, we should be able to launch a counter-offensive on Silverwind Refuge.$B$BJust as soon as we''re done with defending the spire....' WHERE `Id`=26470 AND (`OfferRewardText` IS NULL OR `OfferRewardText`='');
UPDATE `quest_template` SET `OfferRewardText`='Rest in peace, my friends.$B$B<You can see the sorrow in the druid cat''s eyes.>$B$BI felt the anguish of the Dor''danil Barrows lessen, and knew that you had completed your task.$B$BIt was grim work that you did, $N, for the spirits you destroyed were merely victims of the Horde''s evil. But with their destruction, let us hope the maddened spirits will finally find peace.' WHERE `Id`=26472 AND (`OfferRewardText` IS NULL OR `OfferRewardText`='');
UPDATE `quest_template` SET `RequestItemsText`='Have you gathered the Bathran''s Hair, $N? The child''s health grows weaker by the hour....' WHERE `Id`=26473 AND (`RequestItemsText` IS NULL OR `RequestItemsText`='');
UPDATE `quest_template` SET `OfferRewardText`='Ah, you have the hair! This is a good first step. There are other ingredients that we will need, but the hair of the fallen Ancient could well be the most important.$B$BI only hope that whatever the Forsaken are devising from the plant will not be turned into a weapon. We simply do not have the numbers to remove them right now, especially with Maestra''s Post under attack!' WHERE `Id`=26473 AND (`OfferRewardText` IS NULL OR `OfferRewardText`='');
UPDATE `quest_template` SET `RequestItemsText`='I must apologize, for I have no time to speak. My child, Relara, is deathly ill!' WHERE `Id`=26474 AND (`RequestItemsText` IS NULL OR `RequestItemsText`='');
UPDATE `quest_template` SET `OfferRewardText`='This is from Orendil?$B$BHis skill with herbs and healing is great! This cure gives me hope, when before I had little....' WHERE `Id`=26474 AND (`OfferRewardText` IS NULL OR `OfferRewardText`='');
UPDATE `quest_template` SET `RequestItemsText`='$N, did you find the remains of the lake? Do you have the Tear?' WHERE `Id`=26475 AND (`RequestItemsText` IS NULL OR `RequestItemsText`='');
UPDATE `quest_template` SET `OfferRewardText`='Oh, you found it! Odd... it looks tarnished somehow. I will place the tear in a stew, and pray that it will cure her.$B$BThank you! Thank you, $N!' WHERE `Id`=26475 AND (`OfferRewardText` IS NULL OR `OfferRewardText`='');
UPDATE `quest_template` SET `RequestItemsText`='Hello. How are you?' WHERE `Id`=26476 AND (`RequestItemsText` IS NULL OR `RequestItemsText`='');
UPDATE `quest_template` SET `OfferRewardText`='Oh, Raene sent you? It must be serious indeed.$B$BWhat can I help you with?' WHERE `Id`=26476 AND (`OfferRewardText` IS NULL OR `OfferRewardText`='');
UPDATE `quest_template` SET `RequestItemsText`='It upsets me so that the treants have become corrupt. I wish I could do more to help them.' WHERE `Id`=26477 AND (`RequestItemsText` IS NULL OR `RequestItemsText`='');
UPDATE `quest_template` SET `OfferRewardText`='I''m pleased to see you''re back, $N.' WHERE `Id`=26477 AND (`OfferRewardText` IS NULL OR `OfferRewardText`='');
UPDATE `quest_template` SET `RequestItemsText`='Did you find the final piece of the rod, $N? How did my technique work?' WHERE `Id`=26478 AND (`RequestItemsText` IS NULL OR `RequestItemsText`='');
UPDATE `quest_template` SET `OfferRewardText`='You got it? Wonderful for you... and for Raene!$B$BI guess we''ll have to see about reassembling it, won''t we?' WHERE `Id`=26478 AND (`OfferRewardText` IS NULL OR `OfferRewardText`='');
UPDATE `quest_template` SET `RequestItemsText`='Yes, $N? How go your efforts?' WHERE `Id`=26479 AND (`RequestItemsText` IS NULL OR `RequestItemsText`='');
UPDATE `quest_template` SET `OfferRewardText`='You''ve recreated the rod Teronis had set out to find? That''s wonderful to hear.$B$BShael''dryn has been indispensible in her assistance. Teronis would be proud to see his quest is continuing even after his tragic passing.$B$B<Raene looks over the reconstructed rod with a look of approval and thoughts racing behind her eyes.>$B$BNow it is time for us to make use of its power to eliminate the enemies of Ashenvale!' WHERE `Id`=26479 AND (`OfferRewardText` IS NULL OR `OfferRewardText`='');
UPDATE `quest_template` SET `OfferRewardText`='Yes, yes... you appear as one of my kind, but I care not what you truly are if you can help the furbolg.$B$BThe night elves and now the orcs have visited many atrocities upon my people.$B$BCorruption runs through our veins, corruption brought down upon us by the prideful night elves and the warlike orcs. They are the ones who did this to our people... They are the ones I blame for being cast out of my tribe.$B$BAt night I can still see the campfires burning in the darkness.' WHERE `Id`=26480 AND (`OfferRewardText` IS NULL OR `OfferRewardText`='');
UPDATE `quest_template` SET `RequestItemsText`='Have you slain Ran yet, my friend? We must have his skull if you''re to deliver my people from bondage.' WHERE `Id`=26481 AND (`RequestItemsText` IS NULL OR `RequestItemsText`='');
UPDATE `quest_template` SET `OfferRewardText`='You have done well, my friend.$B$BNow quickly, hand me Ran''s skull. While his essence yet taints it, we shall fashion it upon Dartol''s Rod giving you the power to influence my brethren and deliver them from evil!' WHERE `Id`=26481 AND (`OfferRewardText` IS NULL OR `OfferRewardText`='');
UPDATE `quest_template` SET `RequestItemsText`='You return, $N. What''s that affixed to the top of the rod? A skull?' WHERE `Id`=26482 AND (`RequestItemsText` IS NULL OR `RequestItemsText`='');
UPDATE `quest_template` SET `OfferRewardText`='So, you used the skull of the furbolg king to modify the power of Dartol''s Rod? You then used that power to convince the captured furbolg to rise up and attack the Horde at Silverwind Refuge?$B$BI am more than pleased and impressed with your abilities, $N. The Sentinels cannot thank you enough. It should be a simple matter for us to sweep away the orcs and retake the refuge now!$B$BTeronis would be proud. You have my deepest respect.' WHERE `Id`=26482 AND (`OfferRewardText` IS NULL OR `OfferRewardText`='');
UPDATE `quest_template` SET `OfferRewardText`='Welcome to Shadebough, $N. Lady Shandris sent word of you.' WHERE `Id`=26574 AND (`OfferRewardText` IS NULL OR `OfferRewardText`='');
UPDATE `quest_template` SET `OfferRewardText`='Welcome to our camp, $C. You couldn''t have arrived at a better time.' WHERE `Id`=26838 AND (`OfferRewardText` IS NULL OR `OfferRewardText`='');
UPDATE `quest_template` SET `RequestItemsText`='I''m glad that you''ve come, $N.' WHERE `Id`=26841 AND (`RequestItemsText` IS NULL OR `RequestItemsText`='');
UPDATE `quest_template` SET `OfferRewardText`='I will be your mentor and guide for now. It is my duty to teach you the arcane arts and how you might best fit in among our people.$B$BAs you learn and grow in power, you will learn an immense variety of spells that should allow you to deal with nearly any situation. But until then, return to me as often as you like and I will teach you what I can in the ways of our kind.' WHERE `Id`=26841 AND (`OfferRewardText` IS NULL OR `OfferRewardText`='');
UPDATE `quest_template` SET `RequestItemsText`='Blackfathom Deeps was once an ancient night elf temple. It once housed a most powerful moonwell. Who knows what evil brews there now at the hands of the Twilight''s Hammer.$B$BHave you made any progress in ridding the temple of their presence?' WHERE `Id`=26883 AND (`RequestItemsText` IS NULL OR `RequestItemsText`='');
UPDATE `quest_template` SET `OfferRewardText`='You are no doubt of brave and noble blood, $N. We and all of the people of Ashenvale commend you for your efforts against evil.' WHERE `Id`=26883 AND (`OfferRewardText` IS NULL OR `OfferRewardText`='');
UPDATE `quest_template` SET `OfferRewardText`='Wonderful! I hope you didn''t get hit with too many cannonballs.' WHERE `Id`=26886 AND (`OfferRewardText` IS NULL OR `OfferRewardText`='');
UPDATE `quest_template` SET `RequestItemsText`='Have you got the fillings?' WHERE `Id`=26887 AND (`RequestItemsText` IS NULL OR `RequestItemsText`='');
UPDATE `quest_template` SET `OfferRewardText`='More gold! We''ll be sure to give some of this to Mister Noggenfogger to smoothly ensure our continued relations.$B$BAnd only a little bit of it will go back to Gnomeregan for experimental weapons development!' WHERE `Id`=26887 AND (`OfferRewardText` IS NULL OR `OfferRewardText`='');
UPDATE `quest_template` SET `OfferRewardText`='You know, I''m usually not impressed when I see a $R, but I''ve heard about what you''ve been doin'' for the Steamwheedle. You''re alright, kid.' WHERE `Id`=26889 AND (`OfferRewardText` IS NULL OR `OfferRewardText`='');
UPDATE `quest_template` SET `OfferRewardText`='Thank Elune you''re here! We could use all the help we can get.' WHERE `Id`=26897 AND (`OfferRewardText` IS NULL OR `OfferRewardText`='');
UPDATE `quest_template` SET `OfferRewardText`='I knew you would master this lesson quickly. You are a credit to the highborn and to all our kin. Remember, as you grow in power, return to me and I will instruct you further.' WHERE `Id`=26940 AND (`OfferRewardText` IS NULL OR `OfferRewardText`='');
UPDATE `quest_template` SET `OfferRewardText`='You seem an able warrior. Perhaps you can help me put an end to the terrible evil here.' WHERE `Id`=27063 AND (`OfferRewardText` IS NULL OR `OfferRewardText`='');
UPDATE `quest_template` SET `OfferRewardText`='He''s gone? Did he have the sword?$B$BNah...don''t tell me. Don''t matter no more. Mazoga don''t care.$B$BI''m off now, mon. De consequences of my actions await me. Take whatever I was holdin''... I don''t need it where I''m goin''...' WHERE `Id`=27068 AND (`OfferRewardText` IS NULL OR `OfferRewardText`='');
UPDATE `quest_template` SET `OfferRewardText`='You killed dem? All of dem? And you return alive?$B$BTake what you want off my body, den. It''s mostly curse-free, Mazoga promises.' WHERE `Id`=27071 AND (`OfferRewardText` IS NULL OR `OfferRewardText`='');
UPDATE `quest_template` SET `OfferRewardText`='Have you been in contact with a druid of the talon recently, $C? I can feel the lingering presence of one.' WHERE `Id`=27129 AND (`OfferRewardText` IS NULL OR `OfferRewardText`='');
UPDATE `quest_template` SET `OfferRewardText`='I sensed your coming all the way from Dreamer''s Rest. Your assistance would be most welcome.' WHERE `Id`=27131 AND (`OfferRewardText` IS NULL OR `OfferRewardText`='');
UPDATE `quest_template` SET `OfferRewardText`='Welcome to the Wizard''s Sanctum, $N. I have been watching your progress with interest.' WHERE `Id`=27271 AND (`OfferRewardText` IS NULL OR `OfferRewardText`='');
UPDATE `quest_template` SET `OfferRewardText`='Good to see you again, $N. Let us put the fear of the Goddess into the Grimtotem.' WHERE `Id`=27275 AND (`OfferRewardText` IS NULL OR `OfferRewardText`='');
UPDATE `quest_template` SET `RequestItemsText`='We''ll need to destroy more of their weapon racks if we''re going to put a dent in their ability to fight.' WHERE `Id`=27310 AND (`RequestItemsText` IS NULL OR `RequestItemsText`='');
UPDATE `quest_template` SET `OfferRewardText`='Let''s see them wage their war now!' WHERE `Id`=27310 AND (`OfferRewardText` IS NULL OR `OfferRewardText`='');
UPDATE `quest_template` SET `OfferRewardText`='That put a dent in their numbers! Can''t say that they didn''t deserve it.' WHERE `Id`=27312 AND (`OfferRewardText` IS NULL OR `OfferRewardText`='');
UPDATE `quest_template` SET `RequestItemsText`='Isha Gloomaxe must meet her end, $N!' WHERE `Id`=27314 AND (`RequestItemsText` IS NULL OR `RequestItemsText`='');
UPDATE `quest_template` SET `OfferRewardText`='She was tougher than I thought. We worked well together, but we''re going to have to make sure not to underestimate the other Grimtotem chiefs.' WHERE `Id`=27314 AND (`OfferRewardText` IS NULL OR `OfferRewardText`='');
UPDATE `quest_template` SET `RequestItemsText`='That''s the fabled Rattle of Bones, $N!' WHERE `Id`=27316 AND (`RequestItemsText` IS NULL OR `RequestItemsText`='');
UPDATE `quest_template` SET `OfferRewardText`='It''s true then! What is it doing here, though? And if it''s here, that must mean that the writ and the drums are also nearby!$B$BMaybe there''s some link between it and the wind serpent that just appeared? I think that I''ve an idea what that creature is as well.' WHERE `Id`=27316 AND (`OfferRewardText` IS NULL OR `OfferRewardText`='');
UPDATE `quest_template` SET `OfferRewardText`='That''s two of them. Two more to go.$B$BI wonder what he meant about being "chosen"?' WHERE `Id`=27318 AND (`OfferRewardText` IS NULL OR `OfferRewardText`='');
UPDATE `quest_template` SET `RequestItemsText`='We''ll need the actual writ, not just any tauren scroll hanging.' WHERE `Id`=27320 AND (`RequestItemsText` IS NULL OR `RequestItemsText`='');
UPDATE `quest_template` SET `OfferRewardText`='I''m fairly certain that''s it. This is very intriguing, $N. What are they doing here? Are they being used as a weapon?$B$BThe wind serpent flew northwest to that next bluff. Maybe that''s where the drums are?' WHERE `Id`=27320 AND (`OfferRewardText` IS NULL OR `OfferRewardText`='');
UPDATE `quest_template` SET `OfferRewardText`='<The sentinel gives you an appraising look.>$B$BWhat is it with you? Why do they all seem spooked by you being here?' WHERE `Id`=27323 AND (`OfferRewardText` IS NULL OR `OfferRewardText`='');
UPDATE `quest_template` SET `RequestItemsText`='The tauren love their drums. I can only imagine the Drums of War will be somehow different from the others.' WHERE `Id`=27325 AND (`RequestItemsText` IS NULL OR `RequestItemsText`='');
UPDATE `quest_template` SET `OfferRewardText`='Surely that was the voice of the Elder Crone!$B$BWe must be very careful, $N. Great danger lies ahead if Magatha Grimtotem has taken notice of you.' WHERE `Id`=27325 AND (`OfferRewardText` IS NULL OR `OfferRewardText`='');
UPDATE `quest_template` SET `RequestItemsText`='We have to kill Arnak, $N, if we are to win the battle for the tauren of Freewind Post.' WHERE `Id`=27327 AND (`RequestItemsText` IS NULL OR `RequestItemsText`='');
UPDATE `quest_template` SET `OfferRewardText`='For some reason they all think that you''ve been sent by Magatha Grimtotem. I know it must have something to do with that wind serpent that''s been hanging around.$B$BDoesn''t matter. Their leader is dead. It''s only a matter of time before the tauren of Freewind Post regain their home.$B$BIf I were them, I''d push back a little to teach the Grimtotem a lesson, but they probably won''t. They''re tauren.' WHERE `Id`=27327 AND (`OfferRewardText` IS NULL OR `OfferRewardText`='');
