UPDATE `quest_template` SET `OfferRewardText`='So, she''s been taken prisoner by the Twilight''s Hammer. I can''t say that I feel sorry for her, but she might prove even more dangerous in their hands.' WHERE `Id`=27329 AND (`OfferRewardText` IS NULL OR `OfferRewardText`='');
