UPDATE `quest_template` SET `OfferRewardText`='It is embarrassing to have been kidnapped by Arnak again. I heard the fighting outside. Did you kill him?$B$B<The shaman looks sad for just a moment.>$B$BI am happy to be free once more. Now, how can I help you, $R?' WHERE `Id`=27357 AND (`OfferRewardText` IS NULL OR `OfferRewardText`='');
