UPDATE `quest_template` SET `OfferRewardText`='What did I tell you, eh? Perfectly safe!$B$BI''ll see about getting some of these over to to your friends, $N. At a discount.' WHERE `Id`=27536 AND (`OfferRewardText` IS NULL OR `OfferRewardText`='');
