UPDATE `quest_template` SET `OfferRewardText`='Our ice-cold, refreshing Silversnap Ice! I can''t thank you enough, "dawg", for this entirely spontaneous act of heroism!$B$BHere, have your very own bottle as a totally sincere gesture of thanks! Be sure to tell ALL YOUR FRIENDS how good it is.' WHERE `Id`=27592 AND (`OfferRewardText` IS NULL OR `OfferRewardText`='');
UPDATE `quest_template` SET `OfferRewardText`='Silversnap sent you?! I''m DOOMED!$B$BOh, he sent you to help me! That''s different, haha!' WHERE `Id`=27597 AND (`OfferRewardText` IS NULL OR `OfferRewardText`='');
