UPDATE `quest_template` SET `OfferRewardText`='WOW!$B$BI don''t know why I said that. I''m excitable! But man, there was a lot of stuff on these guys, check it out!$B$BHere, you want this?' WHERE `Id`=27599 AND (`OfferRewardText` IS NULL OR `OfferRewardText`='');
