UPDATE `quest_template` SET `OfferRewardText`='Ah, good, good! Just what I needed.' WHERE `Id`=27663 AND (`OfferRewardText` IS NULL OR `OfferRewardText`='');
UPDATE `quest_template` SET `OfferRewardText`='You have to wonder just what''s out there. This is the coast of the Forbidding Sea, with nothing beyond its reaches... but all these fishy folk just stomped right out of it.$B$BWhat''s more, I saw where they''ve been going...' WHERE `Id`=27691 AND (`OfferRewardText` IS NULL OR `OfferRewardText`='');
UPDATE `quest_template` SET `OfferRewardText`='Thank you, $N. As you can see, my mere presence here has resulted in a bloom of glorious life despite my mate''s presence. Names aside, perhaps one day you will again venture into Desolace and find it a verdant oasis free of any traces of the Old Gods.' WHERE `Id`=27692 AND (`OfferRewardText` IS NULL OR `OfferRewardText`='');
