UPDATE `quest_template` SET `OfferRewardText`='Good riddance. Another source of corruption in this world put to rest.$B$BI thank you for your bravery, $N.' WHERE `Id`=27705 AND (`OfferRewardText` IS NULL OR `OfferRewardText`='');
UPDATE `quest_template` SET `OfferRewardText`='Ah, it''s so nice to have help dropped in.$B$BModern convenience... I can''t get enough of it.' WHERE `Id`=27740 AND (`OfferRewardText` IS NULL OR `OfferRewardText`='');
UPDATE `quest_template` SET `OfferRewardText`='Oh my. It sounds like you ran across quite a sinister being. I wonder what one of those was doing all the way out here...' WHERE `Id`=27757 AND (`OfferRewardText` IS NULL OR `OfferRewardText`='');
