UPDATE `quest_template` SET `OfferRewardText`='You''ve followed orders well, $N. On behalf of the crown, I''m rewarding you for your bravery on the battlefield.' WHERE `Id`=27849 AND (`OfferRewardText` IS NULL OR `OfferRewardText`='');
