UPDATE `quest_template` SET `OfferRewardText`='The goblin sent you? She has a cunning eye, that one.$B$BShe speaks the truth. I am here to stem the tide of corruption seeping from this temple. If you would save your people from a wicked fate, $N, I ask for your assistance.' WHERE `Id`=27869 AND (`OfferRewardText` IS NULL OR `OfferRewardText`='');
