UPDATE `quest_template` SET `OfferRewardText`='I am pleased to see you once again, $N. You are truly noble to assist me further.' WHERE `Id`=27915 AND (`OfferRewardText` IS NULL OR `OfferRewardText`='');
UPDATE `quest_template` SET `OfferRewardText`='Thank you, $C. I am afraid it may be too late... but I refuse to give up, even if the Exodar itself does not hear my cries.' WHERE `Id`=27918 AND (`OfferRewardText` IS NULL OR `OfferRewardText`='');
