UPDATE `quest_template` SET `OfferRewardText`='Surprising... you lived.$B$BI thank you for doing my dirty work, $C. You kept my hands clean while ridding me of some incompetent Grimtotem leaders.$B$BNot only do I have the Rattle of Bones, the Writ of History, and the Drums of War, but I now have the ultimate artifact: the Doomstone!' WHERE `Id`=28159 AND (`OfferRewardText` IS NULL OR `OfferRewardText`='');
UPDATE `quest_template` SET `OfferRewardText`='Wow, she''s evil! But, what does it mean, $N? Is Magatha going to destroy us? Is she in charge of the Twilight''s Hammer now?$B$BWhatever happens, you''ve delivered us from our enemies. Please allow me to show you our gratitude.' WHERE `Id`=28160 AND (`OfferRewardText` IS NULL OR `OfferRewardText`='');
UPDATE `quest_template` SET `OfferRewardText`='It''s good to see you again, $N. Stormwind has need of your skills.' WHERE `Id`=28263 AND (`OfferRewardText` IS NULL OR `OfferRewardText`='');
