UPDATE `quest_template` SET `OfferRewardText`='Thank goodness you''re here. I''ve discovered the secret of the fierce Winterfall furbolg.' WHERE `Id`=28544 AND (`OfferRewardText` IS NULL OR `OfferRewardText`='');
