UPDATE `quest_template` SET `OfferRewardText`='Elune be praised! And you as well, young $C.$B$BThere are many young night elves in need of these, but I''d be more than happy to give you one of the bags as a reward. I''m sure it will come in handy.$B$BSafe travels to you.' WHERE `Id`=28715 AND (`OfferRewardText` IS NULL OR `OfferRewardText`='');
UPDATE `quest_template` SET `OfferRewardText`='It is good that you''ve come. It seems your training progresses quickly.' WHERE `Id`=28723 AND (`OfferRewardText` IS NULL OR `OfferRewardText`='');
UPDATE `quest_template` SET `RequestItemsText`='Our dear friend is not doing well, even with my mending. Have you brought the supplies I require?' WHERE `Id`=28724 AND (`RequestItemsText` IS NULL OR `RequestItemsText`='');
UPDATE `quest_template` SET `OfferRewardText`='These will do perfectly. Thank you, $N. Your swiftness is appreciated.' WHERE `Id`=28724 AND (`OfferRewardText` IS NULL OR `OfferRewardText`='');
UPDATE `quest_template` SET `OfferRewardText`='I see you found me, young $R. Dentaria was wise to have sent you.' WHERE `Id`=28725 AND (`OfferRewardText` IS NULL OR `OfferRewardText`='');
UPDATE `quest_template` SET `RequestItemsText`='This is grim work. It pains me to have to inflict such violence on creature of the forest, corrupt or not.' WHERE `Id`=28726 AND (`RequestItemsText` IS NULL OR `RequestItemsText`='');
UPDATE `quest_template` SET `OfferRewardText`='This corruption these spiders suffer from is not simply surface deep. It cannot be magic or subtle malintent. It is bred into them.$B$BIt seems our next task is clear.' WHERE `Id`=28726 AND (`OfferRewardText` IS NULL OR `OfferRewardText`='');
UPDATE `quest_template` SET `RequestItemsText`='I adore these forests. I want to see the corruption purged from them completely. When next I return, I want to do so with a lighter heart.' WHERE `Id`=28727 AND (`RequestItemsText` IS NULL OR `RequestItemsText`='');
UPDATE `quest_template` SET `OfferRewardText`='Githyiss and her brood were being corrupted by this totem. This is a furbolg totem.$B$BThis is very troubling indeed. This means the Gnarlpine are still a danger to these forests. We let our guard down too soon.' WHERE `Id`=28727 AND (`OfferRewardText` IS NULL OR `OfferRewardText`='');
UPDATE `quest_template` SET `OfferRewardText`='You''ve returned! It''s good to see you. It seems you''ve dealt with the source of much of the corruption in Shadowglen.$B$BTeldrassil still suffers and will need attention, but we can afford a moment or two for you to finish your training here in Shadowglen.' WHERE `Id`=28728 AND (`OfferRewardText` IS NULL OR `OfferRewardText`='');
UPDATE `quest_template` SET `RequestItemsText`='Our recent history is fraught with strife and violence. There is still much with which we must come to terms.' WHERE `Id`=28729 AND (`RequestItemsText` IS NULL OR `RequestItemsText`='');
UPDATE `quest_template` SET `OfferRewardText`='Well done, $N. You have one task left for you before you depart Shadowglen for the open wilds of Teldrassil.' WHERE `Id`=28729 AND (`OfferRewardText` IS NULL OR `OfferRewardText`='');
UPDATE `quest_template` SET `RequestItemsText`='The moonwells hold the waters of the Well of Eternity, the ancient source of magic that has wrought so many horrors upon our world.$B$BThe druids take advantage of its properties, the Sentinels revere the wells as shrines to Elune, and now even the returning Highborne look to the wells longingly.' WHERE `Id`=28730 AND (`RequestItemsText` IS NULL OR `RequestItemsText`='');
UPDATE `quest_template` SET `OfferRewardText`='So you have heard the first part of the aftermath of the Battle of Mount Hyjal. There is much more for you to learn and the task you have begun here will continue through the rest of your journey through Teldrassil and into Darnassus.' WHERE `Id`=28730 AND (`OfferRewardText` IS NULL OR `OfferRewardText`='');
UPDATE `quest_template` SET `RequestItemsText`='Greetings, $C. For what purpose do I owe the pleasure of our meeting?' WHERE `Id`=28731 AND (`RequestItemsText` IS NULL OR `RequestItemsText`='');
UPDATE `quest_template` SET `OfferRewardText`='Ah, I see. You were sent by Tenaron. Well then, it would seem we have much to talk about, much to do.$B$BBefore we get to the task at hand, you should take in the lesson of this moonwell.' WHERE `Id`=28731 AND (`OfferRewardText` IS NULL OR `OfferRewardText`='');
UPDATE `quest_template` SET `OfferRewardText`='Welcome to Cenarion Hold, traveler.' WHERE `Id`=28859 AND (`OfferRewardText` IS NULL OR `OfferRewardText`='');
UPDATE `quest_template` SET `OfferRewardText`='Silithus, not such a great place, eh? We get a lot of you from there...' WHERE `Id`=28867 AND (`OfferRewardText` IS NULL OR `OfferRewardText`='');
UPDATE `quest_template` SET `OfferRewardText`='What, you here to help?' WHERE `Id`=28881 AND (`OfferRewardText` IS NULL OR `OfferRewardText`='');
UPDATE `quest_template` SET `OfferRewardText`='Not only do you not fear me or my home, you have defeated me honorably. I''m impressed.' WHERE `Id`=31726 AND (`OfferRewardText` IS NULL OR `OfferRewardText`='');
UPDATE `quest_template` SET `RequestItemsText`='Where did you acquire such an intriguing team?' WHERE `Id`=31729 AND (`RequestItemsText` IS NULL OR `RequestItemsText`='');
UPDATE `quest_template` SET `OfferRewardText`='What a show! A most excellent skirmish indeed.' WHERE `Id`=31729 AND (`OfferRewardText` IS NULL OR `OfferRewardText`='');
UPDATE `quest_template` SET `OfferRewardText`='Don''t forget to buy your mount while you are here! You can buy one from Lelanai right here.' WHERE `Id`=32664 AND (`OfferRewardText` IS NULL OR `OfferRewardText`='');

